# ------------------------------------------------------------

# CellChat requires log-normalized data
DefaultAssay(sc_obj) <- "RNA"

# Check whether RNA data is already normalized
# If the data layer has raw counts, normalize it
rna_data <- GetAssayData(sc_obj, assay = "RNA", layer = "data")
cat(sprintf("RNA data range: %.2f - %.2f\n", min(rna_data), max(rna_data)))

