) %>%
  filter(!grepl("^[a-j]$", CellType)) %>%          # ← 关键修复
  mutate(Highlight = ifelse(CellType == "Stellate.cells",
                            "Stellate", "Others")) %>%
  arrange(desc(N)) %>%
  head(15)

p1a <- ggplot(ct_df, aes(reorder(CellType, N), N, fill = Highlight)) +
