  geom_point(size = 2, color = "#C73E1D") +
  geom_text(size = 2.5, vjust = -0.5) +
  coord_fixed() +
  labs(title = "Slide1 FOV centroids",
       x = "x_slide_mm", y = "y_slide_mm") +
  theme_classic()

print(p)
