# 输出每个 FOV 及其聚类标签
cat("\n=== FOV 及聚类标签 ===\n")
print(fov_centroids[, c("fov", "x_center", "y_center", "cluster")],
      n = 64)

# ============================================================
# GSE292268 患者分界识别 (2026-10-09)
# 
# 发现:
#   Slide1 的 64 个 FOV 按 x 坐标分成两组:
#     - 左侧 (FOV 1-31, x < 1.8): Patient A
#     - 右侧 (FOV 32-64, x > 8.7): Patient B
#   x = 5 作为分界阈值
# 
# 依据:
#   - FOV 1-31 的 x 全部 < 1.8
#   - FOV 32-64 的 x 全部 > 8.7
#   - x 从 1.77 跳到 8.77, 中间约 7 mm 无 FOV
#   - GEO 描述: Slide1 含 Sample 1 + Sample 2 (2 患者)
# 
# 结论:
#   Slide1 的 metadata 虽无患者标签, 但可通过 FOV 空间位置恢复
#   分界: x_center = 5
# ============================================================

# ============================================================
# GSE292268 Slide1 患者分组与空间分析
# 患者分界依据: FOV x_center < 5 → Patient_A, ≥ 5 → Patient_B
# (依据 GEO 描述: Slide1 含 Sample 1+2; FOV x 从 1.77 跳到 8.77)
# ============================================================
suppressPackageStartupMessages({
  library(Seurat); library(tidyverse)
})

SLIDE1_PATIENT_X_CUTOFF <- 5

# ============================================================
# 1. 按 FOV 的 x 中心分配患者标签
# ============================================================
fov_patient <- cosmx1@meta.data %>%
  group_by(fov) %>%
  summarise(x_center = mean(x_slide_mm), .groups = "drop") %>%
  mutate(patient = ifelse(x_center < SLIDE1_PATIENT_X_CUTOFF,
                          "Patient_A", "Patient_B"))

cat("=== FOV 患者分配 ===\n")
print(table(fov_patient$patient))

# ============================================================
# 2. 写入 cosmx1@meta.data (用 match 按位置匹配, 不用 $<-)
# ============================================================
cosmx1@meta.data$patient <- fov_patient$patient[
  match(cosmx1@meta.data$fov, fov_patient$fov)
]

cat("\n=== 细胞水平患者分布 ===\n")
print(table(cosmx1@meta.data$patient, useNA = "ifany"))

# ============================================================
# 3. 提取表达矩阵 + 细胞类型 + 坐标
# ============================================================
col1 <- "RNA_nbclust_8b0a3ae1.8754.4ba9.8269.45e2cf2e855a_1_clusters"
ct    <- cosmx1@meta.data[[col1]]
expr  <- cosmx1[["RNA"]]$data
coords <- cosmx1@meta.data[, c("x_slide_mm", "y_slide_mm",
                               "fov", "patient")]

stellate_idx <- which(ct == "Stellate.cells")
hgf_expr     <- as.numeric(expr["HGF", ])
hgf_pos      <- stellate_idx[hgf_expr[stellate_idx] > 0]
hgf_neg      <- setdiff(stellate_idx, hgf_pos)
hep4_idx     <- which(ct == "Hep.4")

# ============================================================
# 4. 最近邻距离函数 (同 FOV 内, mm → µm)
# ============================================================
compute_nn <- function(src_idx, tgt_idx, coords) {
  out <- rep(NA_real_, length(src_idx))
  for (f in unique(coords$fov)) {
    s <- src_idx[coords$fov[src_idx] == f]
    t <- tgt_idx[coords$fov[tgt_idx] == f]
    if (length(s) == 0 || length(t) == 0) next
    sc <- coords[s, ]; tc <- coords[t, ]
    for (i in seq_along(s)) {
      d <- sqrt((tc$x_slide_mm - sc$x_slide_mm[i])^2 +
                  (tc$y_slide_mm - sc$y_slide_mm[i])^2)
      out[which(src_idx == s[i])] <- min(d) * 1000
    }
  }
  out
}

# ============================================================
# 5. 按患者分组, 分别计算核心空间指标
# ============================================================
cat("\n========================================\n")
cat("  跨患者空间分析\n")
cat("========================================\n")

results <- list()

for (p in c("Patient_A", "Patient_B")) {
  cat(sprintf("\n===== %s =====\n", p))
  
  p_stellate <- intersect(stellate_idx, which(coords$patient == p))
  p_hgf_pos  <- intersect(hgf_pos,      which(coords$patient == p))
  p_hgf_neg  <- intersect(hgf_neg,      which(coords$patient == p))
  p_hep4     <- intersect(hep4_idx,     which(coords$patient == p))
  
  cat(sprintf("HSC: %d, HGF+ HSC: %d (%.1f%%), HGF- HSC: %d, Hep.4: %d\n",
              length(p_stellate), length(p_hgf_pos),
              100 * length(p_hgf_pos) / length(p_stellate),
              length(p_hgf_neg), length(p_hep4)))
  
  d_pos <- compute_nn(p_hgf_pos, p_hep4, coords)
  d_neg <- compute_nn(p_hgf_neg, p_hep4, coords)
  
  cat(sprintf("HGF+ HSC -> Hep.4 中位距离: %.1f µm\n",
              median(d_pos, na.rm = TRUE)))
  cat(sprintf("HGF- HSC -> Hep.4 中位距离: %.1f µm\n",
              median(d_neg, na.rm = TRUE)))
  
  w <- wilcox.test(d_pos, d_neg)
  cat(sprintf("Wilcoxon p = %.2e\n", w$p.value))
  
  results[[p]] <- list(
    n_stellate = length(p_stellate),
    n_hgf_pos  = length(p_hgf_pos),
    n_hgf_neg  = length(p_hgf_neg),
    n_hep4     = length(p_hep4),
    pct_hgf_pos = 100 * length(p_hgf_pos) / length(p_stellate),
    median_dist_hgf_pos = median(d_pos, na.rm = TRUE),
    median_dist_hgf_neg = median(d_neg, na.rm = TRUE),
    p_wilcox = w$p.value
  )
}

# ============================================================
# 6. 汇总表
# ============================================================
cat("\n========================================\n")
cat("  跨患者汇总\n")
cat("========================================\n")

summary_df <- do.call(rbind, lapply(names(results), function(p) {
  r <- results[[p]]
  data.frame(
    Patient = p,
    N_HSC = r$n_stellate,
    N_HGFpos = r$n_hgf_pos,
    Pct_HGFpos = round(r$pct_hgf_pos, 1),
    N_Hep4 = r$n_hep4,
    Median_dist_HGFpos_um = round(r$median_dist_hgf_pos, 1),
    Median_dist_HGFneg_um = round(r$median_dist_hgf_neg, 1),
    Wilcoxon_p = format(r$p_wilcox, scientific = TRUE, digits = 3)
  )
}))
print(summary_df)

# ============================================================
# 7. 方向一致性判断
# ============================================================
dir_a <- results$Patient_A$median_dist_hgf_pos <
  results$Patient_A$median_dist_hgf_neg
dir_b <- results$Patient_B$median_dist_hgf_pos <
  results$Patient_B$median_dist_hgf_neg

cat(sprintf("\nPatient_A: HGF+ %s HGF- (方向: %s)\n",
            ifelse(dir_a, "closer to", "farther from"),
            ifelse(dir_a, "consistent", "reverse")))
cat(sprintf("Patient_B: HGF+ %s HGF- (方向: %s)\n",
            ifelse(dir_b, "closer to", "farther from"),
            ifelse(dir_b, "consistent", "reverse")))

if (dir_a && dir_b) {
  cat("\n✅ 两个患者方向一致 → 空间发现在 2 个独立患者中重现\n")
} else if (!dir_a && !dir_b) {
  cat("\n⚠️ 两个患者方向一致但相反 → 需重新检查分界\n")
} else {
  cat("\n❌ 两个患者方向不一致 → x=5 可能不是患者分界\n")
}

# ============================================================
# 8. 保存
# ============================================================
saveRDS(list(
  patient_map = fov_patient,
  x_cutoff = SLIDE1_PATIENT_X_CUTOFF,
  results = results,
  summary_df = summary_df
), "results/Slide1_patient_split_analysis.rds")

write.csv(summary_df,
          "results/Slide1_patient_split_summary.csv",
          row.names = FALSE)

cat("\n✅ Saved: results/Slide1_patient_split_analysis.rds\n")

