  coord_cartesian(xlim = c(0.5, 0.95)) +
  labs(title = "Model comparison: CHI3L1 single-gene vs multi-gene",
       subtitle = "Training CV and external validation AUC",
       x = "AUC", y = NULL, color = NULL) +
  theme_classic(base_size = 11) +
  theme(legend.position = "top")

ggsave("figures/Figure2/FigS_CHI3L1_comparison.pdf", p,
