# ============================================================
# 诊断: 11-gene 外部验证 AUC 0.784 vs 0.773 差异来源
#
# 背景:
#   手稿中记录 11-gene 验证 AUC = 0.784 (来自 GSE49541_validation_unified_zscored.rds)
#   CHI3L1 对比分析中重新拟合得到 AUC = 0.773
#   两者差异 0.011, 需要定位来源
#
# 假设:
#   差异来自两种 z-score 方式
#   方式 A: 训练集 z-score 参数 (mu, sd) 应用到验证集
#   方式 B: 验证集内部独立 z-score (mean=0, sd=1 per gene)
#
# 手稿 Methods 2.3 措辞: "z-scored per gene within each cohort separately"
#   → 字面意思对应方式 B
#   但方式 A 更符合"锁定模型"的严格定义
#
# 输出:
#   两种方式各自的 AUC, 与旧版 RDS 记录对比
#   用于决定手稿采用哪个数字 + Methods 措辞如何改
# ============================================================

# ============================================================
# CHI3L1 单基因/双基因 vs 11-gene signature（统一方式 B）
# 外部验证用验证集内部 z-score（与手稿 0.784 一致）
# ============================================================
rm(list = ls()); gc()
setwd("~/Desktop/sjfx3")
suppressPackageStartupMessages({
  library(tidyverse); library(caret); library(pROC); library(org.Hs.eg.db)
})

# ---- 1. 载入训练集 ----
data <- readRDS("results/GSE135251_DEG_results.rds")
log_expr <- data$log_expr
y <- as.numeric(data$fibro_stage >= 2)

sym <- mapIds(org.Hs.eg.db, keys = rownames(log_expr),
              column = "SYMBOL", keytype = "ENSEMBL", multiVals = "first")
valid <- !is.na(sym) & !duplicated(sym)
log_expr_sym <- as.matrix(log_expr[valid, ])
rownames(log_expr_sym) <- sym[valid]

# ---- 2. 定义模型 ----
model_list <- list(
  "CHI3L1 only"       = c("CHI3L1"),
  "CHI3L1 + ILDR1"    = c("CHI3L1", "ILDR1"),
  "CHI3L1 + SULF2"    = c("CHI3L1", "SULF2"),
  "11-gene signature" = c("EYA2","FERMT1","PYROXD2","EPB41L4A","CHI3L1",
                          "CNKSR1","ILDR1","GSN","TMPRSS3","ESRRG","SULF2")
)

# ---- 3. CV 函数（折内 z-score，方式 B 一致） ----
run_cv <- function(X, y, k = 10, seed = 123) {
  set.seed(seed)
  X <- as.matrix(X)
  folds <- createFolds(y, k = k, list = TRUE)
  cv_pred <- numeric(length(y))
  for (i in seq_along(folds)) {
    te <- folds[[i]]; tr <- setdiff(seq_along(y), te)
    X_tr <- X[tr, , drop = FALSE]
    X_te <- X[te, , drop = FALSE]
    X_tr_z <- scale(X_tr)
    mu  <- attr(X_tr_z, "scaled:center")
    sdv <- attr(X_tr_z, "scaled:scale")
    X_tr_z[is.na(X_tr_z)] <- 0
    X_te_z <- scale(X_te, center = mu, scale = sdv)
    X_te_z[is.na(X_te_z)] <- 0
    df_tr <- as.data.frame(X_tr_z); df_tr$y <- y[tr]
    m <- glm(y ~ ., data = df_tr, family = binomial)
    df_te <- as.data.frame(X_te_z)
    cv_pred[te] <- predict(m, newdata = df_te, type = "response")
  }
  roc_obj <- roc(y, cv_pred, quiet = TRUE)
  list(pred = cv_pred, auc = as.numeric(auc(roc_obj)),
       ci = as.numeric(ci.auc(roc_obj)))
}

# ---- 4. 训练集 CV ----
cat("=== 训练集 10-fold CV ===\n")
train_res <- list()
for (nm in names(model_list)) {
  genes <- model_list[[nm]]
  X <- t(log_expr_sym[genes, , drop = FALSE])
  colnames(X) <- genes
  res <- run_cv(X, y)
  train_res[[nm]] <- res
  cat(sprintf("%-20s AUC = %.3f (%.3f-%.3f)\n",
              nm, res$auc, res$ci[1], res$ci[3]))
}

# ---- 5. 外部验证 GSE49541（方式 B：验证集内部 z-score） ----
val_data <- readRDS("results/GSE49541_validation.rds")
expr_val <- as.matrix(val_data$expr_gene)
group_val <- val_data$group

cat("\n=== GSE49541 外部验证 (方式 B) ===\n")
val_res <- list()
for (nm in names(model_list)) {
  genes <- model_list[[nm]]
  
  # 检查基因完整性
  missing <- setdiff(genes, rownames(expr_val))
  if (length(missing) > 0) {
    cat(sprintf("%-20s 缺失基因: %s\n", nm, paste(missing, collapse = ",")))
    next
  }
  
  # 训练集全量拟合
  X_tr <- t(log_expr_sym[genes, , drop = FALSE])
  colnames(X_tr) <- genes
  X_tr_z <- scale(X_tr)
  X_tr_z[is.na(X_tr_z)] <- 0
  df_tr <- as.data.frame(X_tr_z); df_tr$y <- y
  m <- glm(y ~ ., data = df_tr, family = binomial)
  
  # 验证集: 方式 B — 验证集内部独立 z-score
  X_v <- t(expr_val[genes, , drop = FALSE])
  colnames(X_v) <- genes
  X_v_z <- scale(X_v)                    # ← 关键: 不传 center/scale
  X_v_z[is.na(X_v_z)] <- 0
  df_v <- as.data.frame(X_v_z)
  pred_v <- predict(m, newdata = df_v, type = "response")
  
  keep <- !is.na(group_val)
  roc_v <- roc(group_val[keep], pred_v[keep], quiet = TRUE)
  ci_v  <- as.numeric(ci.auc(roc_v))
  val_res[[nm]] <- list(pred = pred_v, auc = as.numeric(auc(roc_v)), ci = ci_v)
  cat(sprintf("%-20s AUC = %.3f (%.3f-%.3f)\n",
              nm, as.numeric(auc(roc_v)), ci_v[1], ci_v[3]))
}

# ---- 6. 汇总表 ----
summary_tab <- data.frame(
  Model = names(model_list),
  Training_AUC = sapply(names(model_list), function(nm)
    round(train_res[[nm]]$auc, 3)),
  Training_CI = sapply(names(model_list), function(nm)
    sprintf("%.3f-%.3f", train_res[[nm]]$ci[1], train_res[[nm]]$ci[3])),
  Validation_AUC = sapply(names(model_list), function(nm)
    ifelse(is.null(val_res[[nm]]), NA, round(val_res[[nm]]$auc, 3))),
  Validation_CI = sapply(names(model_list), function(nm)
    ifelse(is.null(val_res[[nm]]), NA,
           sprintf("%.3f-%.3f", val_res[[nm]]$ci[1], val_res[[nm]]$ci[3])))
)
