# ---- 7. 森林图 ----
plot_df <- data.frame(
  Model = factor(rep(names(model_list), 2), levels = rev(names(model_list))),
  Dataset = rep(c("Training CV", "External validation"),
                each = length(model_list)),
  AUC = c(sapply(names(model_list), function(nm) train_res[[nm]]$auc),
          sapply(names(model_list), function(nm)
            ifelse(is.null(val_res[[nm]]), NA, val_res[[nm]]$auc))),
  CI_low = c(sapply(names(model_list), function(nm) train_res[[nm]]$ci[1]),
             sapply(names(model_list), function(nm)
               ifelse(is.null(val_res[[nm]]), NA, val_res[[nm]]$ci[1]))),
  CI_high = c(sapply(names(model_list), function(nm) train_res[[nm]]$ci[3]),
              sapply(names(model_list), function(nm)
                ifelse(is.null(val_res[[nm]]), NA, val_res[[nm]]$ci[3])))
)

p <- ggplot(plot_df, aes(AUC, Model, color = Dataset)) +
  geom_point(size = 3, position = position_dodge(0.5)) +
  geom_errorbarh(aes(xmin = CI_low, xmax = CI_high),
                 height = 0.2, position = position_dodge(0.5)) +
  geom_vline(xintercept = 0.5, linetype = "dashed", color = "grey60") +
  scale_color_manual(values = c("Training CV" = "#2E86AB",
                                "External validation" = "#C73E1D")) +
  coord_cartesian(xlim = c(0.5, 0.95)) +
  labs(title = "Model comparison: CHI3L1 single-gene vs multi-gene",
       subtitle = "Training CV and external validation AUC",
       x = "AUC", y = NULL, color = NULL) +
  theme_classic(base_size = 11) +
  theme(legend.position = "top")

ggsave("figures/Figure2/FigS_CHI3L1_comparison.pdf", p,
       width = 8, height = 4, device = "pdf")
ggsave("figures/Figure2/FigS_CHI3L1_comparison.png", p,
       width = 8, height = 4, dpi = 300, device = "png")

