  geom_text(aes(label = sprintf("%.3f", Value)),
            vjust = -0.6, size = 4, color = "black") +
  scale_fill_manual(values = c("Near (<50 µm)" = "#C73E1D",
                               "Far (>100 µm)" = "#2E86AB")) +
  scale_y_continuous(expand = expansion(mult = c(0, 0.18)),   # ← 关键
                     limits = c(0, 0.35)) +
  labs(title = "MET expression in Hep.4",
       subtitle = "Initial P = 0.028; depth-matched P = 0.118 (n.s.)",
       x = NULL, y = "Mean expression") +
  theme_classic(base_size = 11) +
  theme(plot.title = element_text(face = "bold"),
        plot.subtitle = element_text(size = 9, color = "grey30"),
        legend.position = "none")

# ---- Panel b: MAPK/ERK ----
mapk_df <- data.frame(
  Group = factor(c("Near (<50 µm)", "Far (>100 µm)"),
                 levels = c("Near (<50 µm)", "Far (>100 µm)")),
  Value = c(0.507, 0.402)
)

p_b <- ggplot(mapk_df, aes(Group, Value, fill = Group)) +
  geom_col(alpha = 0.9, width = 0.6) +
  geom_text(aes(label = sprintf("%.3f", Value)),
            vjust = -0.6, size = 4, color = "black") +
  scale_fill_manual(values = c("Near (<50 µm)" = "#C73E1D",
                               "Far (>100 µm)" = "#2E86AB")) +
  scale_y_continuous(expand = expansion(mult = c(0, 0.18)),
                     limits = c(0, 0.6)) +
  labs(title = "MAPK/ERK pathway activity",
       subtitle = "Initial P = 0.016; depth-matched P = 0.373 (n.s.)",
       x = NULL, y = "Mean pathway score") +
  theme_classic(base_size = 11) +
  theme(plot.title = element_text(face = "bold"),
        plot.subtitle = element_text(size = 9, color = "grey30"),
        legend.position = "none")

# ---- Panel c: threshold sensitivity ----
thr_df <- data.frame(
  Comparison = factor(
    c("Near<30 vs Far>150", "Near<50 vs Far>100",
      "Near<50 vs Far>150", "Near<75 vs Far>100"),
    levels = c("Near<30 vs Far>150", "Near<50 vs Far>100",
               "Near<50 vs Far>150", "Near<75 vs Far>100")
  ),
  P = c(0.151, 0.028, 0.158, 0.034)
)

p_c <- ggplot(thr_df, aes(Comparison, P)) +
  geom_col(fill = "#2E86AB", alpha = 0.9, width = 0.6) +
  geom_hline(yintercept = 0.05, linetype = "dashed",
             color = "#C73E1D", linewidth = 0.8) +
  geom_text(aes(label = sprintf("%.3f", P)),
            vjust = -0.5, size = 3.5, color = "black") +
  scale_y_continuous(expand = expansion(mult = c(0, 0.15)),
                     limits = c(0, 0.22)) +
  labs(title = "Sensitivity to distance thresholds",
       subtitle = "Only intermediate thresholds reach P < 0.05",
       x = NULL, y = "P value") +
  theme_classic(base_size = 11) +
  theme(plot.title = element_text(face = "bold"),
        plot.subtitle = element_text(size = 9, color = "grey30"),
        axis.text.x = element_text(angle = 30, hjust = 1, size = 9))

# ---- 拼接 ----
figS8 <- (p_a | p_b | p_c) +
