# S12. Nested CV 稳定性
# ============================================================
tabS12 <- read.csv("results/supplementary/TableS12_nested_CV_stability.csv")
# 如果读不到，从原始 RDS 重建
if (!exists("tabS12") || is.null(tabS12) || nrow(tabS12) == 0) {
  full_cv <- readRDS("results/Module1_nested_cv_FULL.rds")
  core_sigs <- full_cv$core_signatures
  gene_count <- full_cv$gene_count
  fallback_fold <- which(gene_count == 15)
  all_genes <- sort(unique(unlist(core_sigs)))
  tabS12 <- data.frame(Gene = all_genes, stringsAsFactors = FALSE)
  for (i in seq_along(core_sigs)) {
    tabS12[[paste0("Fold_", i)]] <- as.integer(all_genes %in% core_sigs[[i]])
  }
  tabS12$N_folds <- rowSums(tabS12[, grep("^Fold_", colnames(tabS12))])
  real_folds <- setdiff(seq_along(core_sigs), fallback_fold)
  tabS12$N_folds_real <- rowSums(tabS12[, paste0("Fold_", real_folds)])
  tabS12 <- tabS12[order(-tabS12$N_folds, -tabS12$N_folds_real), ]
  tabS12$Stable_80pct <- tabS12$N_folds >= 8
  write.csv(tabS12,
            file.path(supp, "TableS12_nested_CV_stability.csv"),
            row.names = FALSE)
}
cat("✅ S12: nested CV stability\n")

