dir.create("results", showWarnings = FALSE)
dir.create("figures/Figure2", showWarnings = FALSE, recursive = TRUE)

# ---- 1. 载入 GSE135251 数据 ----
data <- readRDS("results/GSE135251_DEG_results.rds")
log_expr <- data$log_expr
stage <- data$fibro_stage

cat(sprintf("数据: %d 基因 x %d 样本\n", nrow(log_expr), ncol(log_expr)))
cat("Stage 分布:\n"); print(table(stage))

# ---- 2. Ensembl -> Symbol ----
sym <- mapIds(org.Hs.eg.db,
              keys = rownames(log_expr),
              column = "SYMBOL",
              keytype = "ENSEMBL",
              multiVals = "first")
valid <- !is.na(sym) & !duplicated(sym)
log_expr_sym <- log_expr[valid, ]
rownames(log_expr_sym) <- sym[valid]

cat(sprintf("Symbol 映射后: %d 基因\n", nrow(log_expr_sym)))

# ---- 3. 目标基因（HGF/IL11 轴 + HSC 活化标志）----
target_genes <- c(
  "HGF", "MET",                # HGF-MET 轴
  "IL11", "IL11RA", "IL6R",    # IL11/IL6 轴
  "LIFR", "OSMR", "IL6ST",     # IL6 家族受体
  "CHI3L1", "SULF2", "GSN"     # HSC 活化标志
)

present <- intersect(target_genes, rownames(log_expr_sym))
missing <- setdiff(target_genes, rownames(log_expr_sym))

cat(sprintf("\n目标基因可用: %d / %d\n", length(present), length(target_genes)))
if (length(missing) > 0) {
  cat("缺失:", paste(missing, collapse = ", "), "\n")
}

# ---- 4. 分期趋势检验 ----
cat("\n========== 分期趋势检验 ==========\n")

trend_results <- data.frame()

for (g in present) {
  expr_g <- as.numeric(log_expr_sym[g, ])

  # 4.1 Kruskal-Wallis (整体差异)
  kt <- kruskal.test(expr_g ~ factor(stage))

  # 4.2 Jonckheere-Terpstra (单调趋势)
  jt <- jonckheere.test(expr_g, as.numeric(factor(stage)),
                        alternative = "increasing")

  # 4.3 Spearman (连续相关)
  sp <- cor.test(expr_g, stage, method = "spearman")

  trend_results <- rbind(trend_results, data.frame(
    Gene = g,
    KW_P = kt$p.value,
    JT_P = jt$p.value,
    JT_stat = jt$statistic,
    Spearman_rho = round(sp$estimate, 3),
    Spearman_P = sp$p.value,
    Mean_F0 = round(mean(expr_g[stage == 0]), 3),
    Mean_F1 = round(mean(expr_g[stage == 1]), 3),
    Mean_F2 = round(mean(expr_g[stage == 2]), 3),
    Mean_F3 = round(mean(expr_g[stage == 3]), 3),
    Mean_F4 = round(mean(expr_g[stage == 4]), 3)
  ))
}

# 按 JT_P 排序
trend_results <- trend_results[order(trend_results$JT_P), ]
print(trend_results)
write.csv(trend_results,
          "results/stage_trend_HGF_IL11_axis.csv",
          row.names = FALSE)

# ---- 5. 16-gene HGF+ HSC signature 沿分期的趋势 ----
sig16 <- read.csv("results/signature_HGFpos_up.csv")$gene
sig_in <- intersect(sig16, rownames(log_expr_sym))
cat(sprintf("\n16-gene signature 在 bulk 中可用: %d / 16\n",
            length(sig_in)))

# Signature score (z-mean across genes)
mat_z <- t(scale(t(log_expr_sym[sig_in, , drop = FALSE])))
mat_z[is.na(mat_z)] <- 0
sig_score <- colMeans(mat_z)

# 分期检验
kt_sig <- kruskal.test(sig_score ~ factor(stage))
jt_sig <- jonckheere.test(sig_score, as.numeric(factor(stage)),
                          alternative = "increasing")
sp_sig <- cor.test(sig_score, stage, method = "spearman")

cat("\n=== 16-gene signature 沿分期 ===\n")
cat(sprintf("Kruskal-Wallis P = %.3e\n", kt_sig$p.value))
cat(sprintf("Jonckheere-Terpstra P = %.3e\n", jt_sig$p.value))
cat(sprintf("Spearman rho = %.3f, P = %.3e\n",
            sp_sig$estimate, sp_sig$p.value))

saveRDS(list(
  sig_score = sig_score,
  stage = stage,
  kt = kt_sig, jt = jt_sig, sp = sp_sig
), "results/signature_stage_trend.rds")

