# ============================================================
# Platt scaling 校准：把外部验证的校准斜率 0.685 提升到 1.0 附近
# 目的：回应审稿人"predictions are not well calibrated"的质疑
# ============================================================
# Platt scaling 校准：修复 y 提取问题
# ============================================================
rm(list = ls()); gc()
setwd("~/Desktop/sjfx3")
suppressPackageStartupMessages({
  library(tidyverse); library(pROC); library(dcurves)
})

# ---- 1. 加载训练集 CV 预测 + 提取 y ----
tr <- readRDS("results/Module1_cv_fixed.rds")

# 优先从 zscored 版本加载 y（最稳）
zs <- readRDS("results/Module1_ROC_results_zscored.rds")
y_train <- as.integer(zs$y)
cv_pred_train <- as.numeric(tr$cv_pred)

# 长度检查
if (length(y_train) != length(cv_pred_train)) {
  cat("警告：长度不一致，改用 zscored 版本的 cv_pred\n")
  cv_pred_train <- as.numeric(zs$cv_pred)
}

stopifnot(length(y_train) == length(cv_pred_train))
cat(sprintf("y_train: %d 个值, 事件数 = %d\n",
            length(y_train), sum(y_train == 1)))
cat(sprintf("cv_pred: %d 个值\n", length(cv_pred_train)))

train_df <- data.frame(
  outcome   = y_train,
  pred_prob = cv_pred_train
)
train_df$logit_p <- qlogis(pmin(pmax(train_df$pred_prob, 1e-10), 1 - 1e-10))

# ---- 2. Platt scaling: logistic 回归拟合 logit(p) -> outcome ----
cal_model <- glm(outcome ~ logit_p, family = binomial, data = train_df)
cat("\nPlatt 校准模型系数:\n"); print(coef(cal_model))

# ---- 3. 应用到验证集 ----
val <- readRDS("results/GSE49541_validation_unified_zscored.rds")
df <- data.frame(
  outcome   = as.integer(val$group),
  pred_prob = as.numeric(val$pred_prob)
)
df <- df[!is.na(df$outcome), ]
df$logit_p <- qlogis(pmin(pmax(df$pred_prob, 1e-10), 1 - 1e-10))
df$pred_prob_cal <- predict(cal_model, newdata = df, type = "response")

# ---- 4. 校准前后对比 ----
brier_raw <- mean((df$pred_prob - df$outcome)^2)
brier_cal <- mean((df$pred_prob_cal - df$outcome)^2)

slope_raw <- coef(glm(outcome ~ qlogis(pred_prob), data = df,
                      family = binomial))[2]
slope_cal <- coef(glm(outcome ~ qlogis(pred_prob_cal), data = df,
                      family = binomial))[2]

cat(sprintf("\n=== 校准前后对比 ===\n"))
cat(sprintf("Brier score: %.3f (raw) → %.3f (calibrated)\n",
            brier_raw, brier_cal))
cat(sprintf("Calibration slope: %.3f (raw) → %.3f (calibrated)\n",
            slope_raw, slope_cal))

# ---- 5. DCA（校准后）----
dca_obj <- dcurves::dca(outcome ~ pred_prob_cal, data = df)
sel <- dca_obj$dca %>%
  filter(variable == "pred_prob_cal",
         round(threshold, 3) %in% c(0.2, 0.3, 0.4))
cat("\n校准后 DCA net benefit:\n")
print(sel[, c("threshold", "net_benefit")])

# ---- 6. 校准曲线 ----
df$bin <- cut(df$pred_prob_cal, breaks = seq(0, 1, 0.2), include.lowest = TRUE)
cal_df <- df %>%
  group_by(bin) %>%
  summarise(mean_pred = mean(pred_prob_cal),
            obs_rate  = mean(outcome),
            n = n(),
            .groups = "drop") %>%
  filter(n >= 3)

p_cal <- ggplot(cal_df, aes(mean_pred, obs_rate)) +
  geom_abline(intercept = 0, slope = 1, linetype = "dashed",
              color = "grey60") +
  geom_point(aes(size = n), color = "#C73E1D", alpha = 0.85) +
  geom_line(color = "#C73E1D") +
  labs(title = "Calibration plot (Platt-scaled)",
       subtitle = sprintf("Brier = %.3f; calibration slope = %.3f",
                          brier_cal, slope_cal),
       x = "Predicted probability", y = "Observed rate",
       size = "N") +
  coord_fixed(xlim = c(0, 1), ylim = c(0, 1)) +
  theme_classic(base_size = 11)

ggsave("figures/Figure2/FigS3b_calibration_platt.pdf", p_cal,
       width = 5, height = 5)
ggsave("figures/Figure2/FigS3b_calibration_platt.png", p_cal,
       width = 5, height = 5, dpi = 300)

saveRDS(list(cal_model = cal_model, df = df,
             brier_raw = brier_raw, brier_cal = brier_cal,
             slope_raw = slope_raw, slope_cal = slope_cal),
        "results/Platt_calibration.rds")

cat("\n✅ Saved: results/Platt_calibration.rds + FigS3b\n")

# ============================================================
# DCA bootstrap CI（修正 net benefit 公式）
# ============================================================
rm(list = ls()); gc()
setwd("~/Desktop/sjfx3")
suppressPackageStartupMessages({
  library(tidyverse); library(dcurves)
})

platt <- readRDS("results/Platt_calibration.rds")
df <- platt$df

set.seed(123)
n_boot <- 1000
thresholds <- c(0.2, 0.3, 0.4)

# 正确的 net benefit 公式
calc_nb <- function(data, prob_col, th) {
  pred <- data[[prob_col]]
  obs  <- data$outcome
  n <- length(obs)
  # TP / n
  tp_n <- sum(pred >= th & obs == 1) / n
  # FP / n
  fp_n <- sum(pred >= th & obs == 0) / n
  # net benefit
  tp_n - fp_n * (th / (1 - th))
}

# Bootstrap
boot_res <- data.frame()
for (i in 1:n_boot) {
  idx <- sample(seq_len(nrow(df)), replace = TRUE)
  d <- df[idx, ]
  for (th in thresholds) {
    nb_raw <- calc_nb(d, "pred_prob", th)
    nb_cal <- calc_nb(d, "pred_prob_cal", th)
    boot_res <- rbind(boot_res, data.frame(
      iter = i, threshold = th,
      nb_raw = nb_raw, nb_cal = nb_cal,
      delta = nb_cal - nb_raw
    ))
  }
}

# 汇总
summary_boot <- boot_res %>%
  group_by(threshold) %>%
  summarise(
    NB_raw_mean   = mean(nb_raw),
    NB_raw_CI_low = quantile(nb_raw, 0.025),
    NB_raw_CI_high= quantile(nb_raw, 0.975),
    NB_cal_mean   = mean(nb_cal),
    NB_cal_CI_low = quantile(nb_cal, 0.025),
    NB_cal_CI_high= quantile(nb_cal, 0.975),
    Delta_mean    = mean(delta),
    Delta_CI_low  = quantile(delta, 0.025),
    Delta_CI_high = quantile(delta, 0.975),
    P_delta_sig   = mean(delta > 0),
    .groups = "drop"
  )

cat("=== DCA Bootstrap 结果（修正版）===\n")
print(summary_boot)
write.csv(summary_boot, "results/DCA_bootstrap_CI.csv", row.names = FALSE)

cat("\n=== 判读 ===\n")
for (i in 1:nrow(summary_boot)) {
  r <- summary_boot[i, ]
  crosses_zero <- r$Delta_CI_low <= 0 && r$Delta_CI_high >= 0
  cat(sprintf("Threshold %.1f: ΔNB = %.3f (95%% CI: %.3f to %.3f) — %s\n",
              r$threshold, r$Delta_mean,
              r$Delta_CI_low, r$Delta_CI_high,
              ifelse(crosses_zero, "跨 0，无显著差异", "有显著差异")))
}

# 可视化
boot_long <- boot_res %>%
  pivot_longer(c(nb_raw, nb_cal), names_to = "type", values_to = "nb") %>%
  mutate(type = ifelse(type == "nb_raw", "Uncalibrated", "Platt-scaled"))

p_boot <- ggplot(boot_long, aes(factor(threshold), nb, fill = type)) +
  geom_boxplot(alpha = 0.75, outlier.shape = NA) +
  scale_fill_manual(values = c("Uncalibrated" = "#2E86AB",
                               "Platt-scaled" = "#C73E1D")) +
  geom_hline(yintercept = 0, linetype = "dashed", color = "grey40") +
  labs(title = "DCA net benefit: uncalibrated vs Platt-scaled (1,000 bootstrap)",
       subtitle = "Bootstrap resampling; distributions overlap across thresholds",
       x = "Threshold probability", y = "Net benefit", fill = NULL) +
  theme_classic(base_size = 11) +
  theme(legend.position = "top")

ggsave("figures/Figure2/FigS3c_DCA_bootstrap.pdf", p_boot,
       width = 7, height = 4.5)
ggsave("figures/Figure2/FigS3c_DCA_bootstrap.png", p_boot,
       width = 7, height = 4.5, dpi = 300)

cat("\n✅ Saved: results/DCA_bootstrap_CI.csv + FigS3c\n")

# ============================================================
# Treat all / treat none 也做 bootstrap（加强 DCA 结论）
# ============================================================
rm(list = ls()); gc()
setwd("~/Desktop/sjfx3")
suppressPackageStartupMessages({library(tidyverse)})

platt <- readRDS("results/Platt_calibration.rds")
df <- platt$df

set.seed(123)
n_boot <- 1000
thresholds <- c(0.2, 0.3, 0.4)

calc_nb <- function(obs, pred, th) {
  n <- length(obs)
  tp_n <- sum(pred >= th & obs == 1) / n
  fp_n <- sum(pred >= th & obs == 0) / n
  tp_n - fp_n * (th / (1 - th))
}

# Treat all 的 NB（对所有样本都干预）
treat_all_nb <- function(obs, th) {
  mean(obs) - (1 - mean(obs)) * (th / (1 - th))
}

boot_res <- data.frame()
for (i in 1:n_boot) {
  idx <- sample(seq_len(nrow(df)), replace = TRUE)
  d <- df[idx, ]
  for (th in thresholds) {
    boot_res <- rbind(boot_res, data.frame(
      iter = i, threshold = th,
      nb_model = calc_nb(d$outcome, d$pred_prob, th),
      nb_treat_all = treat_all_nb(d$outcome, th),
      nb_treat_none = 0
    ))
  }
}

summary_boot2 <- boot_res %>%
  group_by(threshold) %>%
  summarise(
    Model_mean = mean(nb_model),
    Model_CI_low = quantile(nb_model, 0.025),
    Model_CI_high = quantile(nb_model, 0.975),
    TreatAll_mean = mean(nb_treat_all),
    TreatAll_CI_low = quantile(nb_treat_all, 0.025),
    TreatAll_CI_high = quantile(nb_treat_all, 0.975),
    .groups = "drop"
  )

cat("=== Bootstrap: Model vs Treat All ===\n")
print(summary_boot2)
write.csv(summary_boot2, "results/DCA_bootstrap_vs_treatall.csv",
          row.names = FALSE)

delta_summary <- boot_res %>%
  mutate(delta_model_vs_all = nb_model - nb_treat_all) %>%
  group_by(threshold) %>%
  summarise(
    Delta_mean = mean(delta_model_vs_all),
    Delta_CI_low = quantile(delta_model_vs_all, 0.025),
    Delta_CI_high = quantile(delta_model_vs_all, 0.975),
    P_gt_0 = mean(delta_model_vs_all > 0),
    .groups = "drop"
  )
print(delta_summary)

