    boot_res <- rbind(boot_res, data.frame(
      iter = i, threshold = th,
      nb_raw = calc_nb(d$outcome, d$pred_prob, th),          # 未校准
      nb_cal = calc_nb(d$outcome, d$pred_prob_cal, th),      # 校准后
      nb_treat_all = treat_all_nb(d$outcome, th),
      nb_treat_none = 0
    ))
  }
}

# ---- 1. 校准后模型 vs Treat all ----
res_cal_vs_all <- boot_res %>%
  mutate(delta = nb_cal - nb_treat_all) %>%
  group_by(threshold) %>%
  summarise(
    Delta_mean   = mean(delta),
    Delta_CI_low = quantile(delta, 0.025),
    Delta_CI_high= quantile(delta, 0.975),
    P_gt_0       = mean(delta > 0),
    .groups = "drop"
  )

cat("=== 校准后模型 vs Treat all ===\n")
print(res_cal_vs_all)

# ---- 2. 未校准模型 vs Treat all ----
res_raw_vs_all <- boot_res %>%
  mutate(delta = nb_raw - nb_treat_all) %>%
  group_by(threshold) %>%
  summarise(
    Delta_mean   = mean(delta),
    Delta_CI_low = quantile(delta, 0.025),
    Delta_CI_high= quantile(delta, 0.975),
    P_gt_0       = mean(delta > 0),
    .groups = "drop"
  )

cat("\n=== 未校准模型 vs Treat all ===\n")
print(res_raw_vs_all)

# ---- 3. 校准后 vs 未校准（配对）----
res_cal_vs_raw <- boot_res %>%
  mutate(delta = nb_cal - nb_raw) %>%
  group_by(threshold) %>%
  summarise(
    Delta_mean   = mean(delta),
    Delta_CI_low = quantile(delta, 0.025),
    Delta_CI_high= quantile(delta, 0.975),
    P_gt_0       = mean(delta > 0),
    .groups = "drop"
  )

cat("\n=== 校准后 vs 未校准 ===\n")
print(res_cal_vs_raw)

# ---- 4. 保存 ----
write.csv(res_cal_vs_all, "results/DCA_boot_cal_vs_treatall.csv", row.names = FALSE)
write.csv(res_raw_vs_all, "results/DCA_boot_raw_vs_treatall.csv", row.names = FALSE)
write.csv(res_cal_vs_raw, "results/DCA_boot_cal_vs_raw.csv", row.names = FALSE)

cat("\n✅ Saved: 3 个 CSV\n")

