# ============================================================
# Step 2: IL6R+ vs IL6R− Hep.4 空间邻近 HGF+ HSC 的选择性
# ============================================================
suppressPackageStartupMessages({
  library(Seurat); library(tidyverse); library(ggplot2)
})

# ---- 1. 定义 Hep.4 的 IL6R 分层 ----
col1 <- "RNA_nbclust_8b0a3ae1.8754.4ba9.8269.45e2cf2e855a_1_clusters"
celltype_vec <- cosmx1@meta.data[[col1]]
expr <- cosmx1[["RNA"]]$data
coords <- cosmx1@meta.data[, c("x_slide_mm", "y_slide_mm", "fov")]

hep4_idx <- which(celltype_vec == "Hep.4")
il6r_expr <- as.numeric(expr["IL6R", ])
il11ra_expr <- as.numeric(expr["IL11RA", ])

hep4_il6r_pos <- hep4_idx[il6r_expr[hep4_idx] > 0]
hep4_il6r_neg <- hep4_idx[il6r_expr[hep4_idx] == 0]
hep4_double_pos <- hep4_idx[il6r_expr[hep4_idx] > 0 &
                              il11ra_expr[hep4_idx] > 0]

cat(sprintf("Hep.4 total: %d\n", length(hep4_idx)))
cat(sprintf("  IL6R+: %d (%.1f%%)\n",
            length(hep4_il6r_pos), 100 * length(hep4_il6r_pos) / length(hep4_idx)))
cat(sprintf("  IL6R−: %d (%.1f%%)\n",
            length(hep4_il6r_neg), 100 * length(hep4_il6r_neg) / length(hep4_idx)))
cat(sprintf("  IL6R+IL11RA+ (double): %d (%.1f%%)\n",
            length(hep4_double_pos),
            100 * length(hep4_double_pos) / length(hep4_idx)))

# ---- 2. HGF+ HSC ----
stellate_idx <- which(celltype_vec == "Stellate.cells")
hgf_expr <- as.numeric(expr["HGF", ])
hgf_pos <- stellate_idx[hgf_expr[stellate_idx] > 0]
cat(sprintf("HGF+ HSC: %d\n", length(hgf_pos)))

# ---- 3. 距离函数 ----
compute_nn <- function(src_idx, tgt_idx, coords) {
  out <- rep(NA_real_, length(src_idx))
  for (f in unique(coords$fov)) {
    s <- src_idx[coords$fov[src_idx] == f]
    t <- tgt_idx[coords$fov[tgt_idx] == f]
    if (length(s) == 0 || length(t) == 0) next
    sc <- coords[s, ]; tc <- coords[t, ]
    for (i in seq_along(s)) {
      d <- sqrt((tc$x_slide_mm - sc$x_slide_mm[i])^2 +
                  (tc$y_slide_mm - sc$y_slide_mm[i])^2)
      out[which(src_idx == s[i])] <- min(d) * 1000  # µm
    }
  }
  out
}

# ---- 4. 关键分析：IL6R+ Hep.4 到 HGF+ HSC 的距离 vs IL6R− Hep.4 ----
d_il6r_pos <- compute_nn(hep4_il6r_pos, hgf_pos, coords)
d_il6r_neg <- compute_nn(hep4_il6r_neg, hgf_pos, coords)
d_double   <- compute_nn(hep4_double_pos, hgf_pos, coords)

cat(sprintf("\n=== 到最近 HGF+ HSC 的距离（中位数）===\n"))
cat(sprintf("IL6R+ Hep.4:  %.1f µm (n=%d)\n",
            median(d_il6r_pos, na.rm = TRUE), sum(!is.na(d_il6r_pos))))
cat(sprintf("IL6R− Hep.4:  %.1f µm (n=%d)\n",
            median(d_il6r_neg, na.rm = TRUE), sum(!is.na(d_il6r_neg))))
cat(sprintf("Double+ Hep.4: %.1f µm (n=%d)\n",
            median(d_double, na.rm = TRUE), sum(!is.na(d_double))))

# Wilcoxon
w1 <- wilcox.test(d_il6r_pos, d_il6r_neg)
cat(sprintf("\nIL6R+ vs IL6R−: Wilcoxon P = %.4e\n", w1$p.value))

# 效应量
cohens_d <- function(x, y) {
  (mean(x, na.rm=TRUE) - mean(y, na.rm=TRUE)) /
    sqrt((var(x, na.rm=TRUE) + var(y, na.rm=TRUE)) / 2)
}
cat(sprintf("Cohen's d = %.3f\n", cohens_d(d_il6r_pos, d_il6r_neg)))

# ---- 5. 置换检验 ----
set.seed(123)
n_perm <- 1000
perm_delta <- numeric(n_perm)
all_hep4_d <- c(d_il6r_pos, d_il6r_neg)
n_pos <- sum(!is.na(d_il6r_pos))
for (i in 1:n_perm) {
  shuf <- sample(all_hep4_d)
  perm_delta[i] <- median(shuf[1:n_pos], na.rm = TRUE) -
    median(shuf[(n_pos+1):length(shuf)], na.rm = TRUE)
}
obs_delta <- median(d_il6r_pos, na.rm=TRUE) - median(d_il6r_neg, na.rm=TRUE)
p_perm <- mean(abs(perm_delta) >= abs(obs_delta))
cat(sprintf("Observed Δmedian = %.1f µm\n", obs_delta))
cat(sprintf("Permutation P = %.4f\n", p_perm))

# ---- 6. 可视化 ----
plot_df <- rbind(
  data.frame(Group = "IL6R+ Hep.4", Distance = d_il6r_pos),
  data.frame(Group = "IL6R− Hep.4", Distance = d_il6r_neg)
)
plot_df <- plot_df[!is.na(plot_df$Distance), ]

p1 <- ggplot(plot_df, aes(Group, Distance, fill = Group)) +
  geom_violin(alpha = 0.5, scale = "width") +
  geom_boxplot(width = 0.2, outlier.shape = NA, alpha = 0.9) +
  scale_fill_manual(values = c("IL6R+ Hep.4" = "#C73E1D",
                               "IL6R− Hep.4" = "#2E86AB")) +
  coord_cartesian(ylim = c(0, 200)) +
  labs(title = "Distance from Hep.4 to nearest HGF+ HSC",
       subtitle = sprintf("Wilcoxon P = %.2e; Cohen's d = %.3f",
                          w1$p.value, cohens_d(d_il6r_pos, d_il6r_neg)),
       x = NULL, y = "Distance (µm)") +
  theme_classic(base_size = 11) +
  theme(legend.position = "none")

ggsave("figures/Figure2/Fig_Hep4_IL6R_stratification.pdf",
       p1, width = 6, height = 5)
ggsave("figures/Figure2/Fig_Hep4_IL6R_stratification.png",
       p1, width = 6, height = 5, dpi = 300)

# ---- 7. 保存 ----
saveRDS(list(
  hep4_il6r_pos = hep4_il6r_pos,
  hep4_il6r_neg = hep4_il6r_neg,
  hep4_double_pos = hep4_double_pos,
  d_il6r_pos = d_il6r_pos,
  d_il6r_neg = d_il6r_neg,
  d_double = d_double,
  wilcox_p = w1$p.value,
  cohens_d = cohens_d(d_il6r_pos, d_il6r_neg),
  perm_p = p_perm,
  obs_delta = obs_delta
), "results/Hep4_IL6R_stratification.rds")

cat("\n✅ Saved: results/Hep4_IL6R_stratification.rds\n")


# ============================================================
# 升级三：TFAP2A/TP53 活性与 HGF 表达的细胞内耦合
# 目的：在单细胞水平展示 HGF+ HSC 内部的调控逻辑
# ============================================================
rm(list = ls()); gc()
setwd("~/Desktop/sjfx3")
suppressPackageStartupMessages({
  library(Seurat); library(tidyverse); library(decoupleR)
  library(dorothea); library(ggplot2); library(patchwork)
})

# ---- 1. 加载 CosMx Slide1 ----
cosmx1 <- readRDS("data/GSM8855042_Slide1_SeuratObject.RDS")
col1 <- "RNA_nbclust_8b0a3ae1.8754.4ba9.8269.45e2cf2e855a_1_clusters"
celltype_vec <- cosmx1@meta.data[[col1]]
expr <- cosmx1[["RNA"]]$data

# ---- 2. 提取 HSC ----
stellate_idx <- which(celltype_vec == "Stellate.cells")
hsc_expr <- as.matrix(expr[, stellate_idx])
hsc_expr <- hsc_expr[rowSums(hsc_expr > 0) > ncol(hsc_expr) * 0.05, ]
cat(sprintf("HSC 子集: %d 基因 x %d 细胞\n",
            nrow(hsc_expr), ncol(hsc_expr)))

# ---- 3. 跑 decoupleR ULM（保存单细胞 TF 活性矩阵）----
data("dorothea_hs", package = "dorothea")
regulon <- dorothea_hs %>%
  dplyr::filter(confidence %in% c("A", "B", "C"))

cat("跑 decoupleR ULM...\n")
tf_act <- decoupleR::run_ulm(
  mat = hsc_expr,
  net = regulon,
  .source = "tf",
  .target = "target",
  .mor = "mor",
  minsize = 5
)

# 转宽表
tf_mat <- tf_act %>%
  dplyr::select(condition, source, score) %>%
  pivot_wider(names_from = source, values_from = score) %>%
  column_to_rownames("condition")
tf_mat <- tf_mat[colnames(hsc_expr), ]

cat(sprintf("TF 活性矩阵: %d 细胞 x %d TF\n",
            nrow(tf_mat), ncol(tf_mat)))

# ---- 4. HGF 表达 ----
hgf_expr_hsc <- as.numeric(expr["HGF", stellate_idx])
hgf_status <- ifelse(hgf_expr_hsc > 0, "HGF+", "HGF-")
cat(sprintf("HGF+ HSC: %d, HGF- HSC: %d\n",
            sum(hgf_status == "HGF+"), sum(hgf_status == "HGF-")))

# ---- 5. 关键：TFAP2A / TP53 活性 vs HGF 表达 ----
result_df <- data.frame(
  HGF = hgf_expr_hsc,
  TFAP2A = tf_mat[, "TFAP2A"],
  TP53 = tf_mat[, "TP53"],
  status = hgf_status
)
result_df$is_HGF_pos <- as.numeric(hgf_status == "HGF+")

cat("\n========== TF-HGF 耦合分析 ==========\n")

# 5.1 全 HSC 中的 Spearman 相关
ct_tfap2a <- cor.test(result_df$TFAP2A, result_df$HGF,
                      method = "spearman")
ct_tp53 <- cor.test(result_df$TP53, result_df$HGF,
                    method = "spearman")

cat(sprintf("TFAP2A vs HGF (all HSC): rho = %.3f, P = %.2e\n",
            ct_tfap2a$estimate, ct_tfap2a$p.value))
cat(sprintf("TP53   vs HGF (all HSC): rho = %.3f, P = %.2e\n",
            ct_tp53$estimate, ct_tp53$p.value))

# 5.2 HGF+ HSC vs HGF- HSC 的 TF 活性
w_tfap2a <- wilcox.test(TFAP2A ~ status, data = result_df)
w_tp53 <- wilcox.test(TP53 ~ status, data = result_df)

cat(sprintf("\nTFAP2A 活性 (HGF+ vs HGF-): median %.3f vs %.3f, P = %.2e\n",
            median(result_df$TFAP2A[result_df$status == "HGF+"]),
            median(result_df$TFAP2A[result_df$status == "HGF-"]),
            w_tfap2a$p.value))
cat(sprintf("TP53   活性 (HGF+ vs HGF-): median %.3f vs %.3f, P = %.2e\n",
            median(result_df$TP53[result_df$status == "HGF+"]),
            median(result_df$TP53[result_df$status == "HGF-"]),
            w_tp53$p.value))

# 5.3 二分类 logistic：TF 活性能否预测 HGF 阳性
lr_tfap2a <- glm(is_HGF_pos ~ TFAP2A, data = result_df, family = binomial)
lr_tp53 <- glm(is_HGF_pos ~ TP53, data = result_df, family = binomial)
cat(sprintf("\nLogistic TFAP2A -> HGF+: beta = %.3f, P = %.3e\n",
            coef(lr_tfap2a)[2], summary(lr_tfap2a)$coefficients[2, 4]))
cat(sprintf("Logistic TP53   -> HGF+: beta = %.3f, P = %.3e\n",
            coef(lr_tp53)[2], summary(lr_tp53)$coefficients[2, 4]))

# ---- 6. 可视化：双 panel ----
# Panel A: TFAP2A 活性 vs HGF 表达
df_long <- result_df %>%
  pivot_longer(c(TFAP2A, TP53),
               names_to = "TF", values_to = "Activity")

p_a <- ggplot(df_long, aes(HGF, Activity, color = status)) +
  geom_point(size = 0.4, alpha = 0.4) +
  geom_smooth(aes(group = 1), method = "lm", se = TRUE,
              color = "black", alpha = 0.15) +
  facet_wrap(~ TF, scales = "free_y") +
  scale_color_manual(values = c("HGF+" = "#C73E1D",
                                "HGF-" = "#2E86AB")) +
  labs(title = "TF activity vs HGF expression in single HSCs (CosMx Slide1)",
       subtitle = sprintf("TFAP2A: rho = %.3f; TP53: rho = %.3f",
                          ct_tfap2a$estimate, ct_tp53$estimate),
       x = "HGF expression", y = "TF activity (ULM score)",
       color = NULL) +
  theme_classic(base_size = 10) +
  theme(legend.position = "top",
        plot.title = element_text(face = "bold"))

ggsave("figures/Figure2/Fig_TF_HGF_coupling.pdf", p_a,
       width = 8, height = 4)
ggsave("figures/Figure2/Fig_TF_HGF_coupling.png", p_a,
       width = 8, height = 4, dpi = 300)

# ---- 7. 保存 ----
saveRDS(list(
  tf_mat = tf_mat,
  result_df = result_df,
  tfap2a_rho = ct_tfap2a$estimate,
  tfap2a_p = ct_tfap2a$p.value,
  tp53_rho = ct_tp53$estimate,
  tp53_p = ct_tp53$p.value,
  tfap2a_wilcox_p = w_tfap2a$p.value,
  tp53_wilcox_p = w_tp53$p.value
), "results/TF_HGF_coupling.rds")

cat("\n✅ Saved: results/TF_HGF_coupling.rds + Fig_TF_HGF_coupling\n")

# ============================================================
# P0-2: Hep.4 下游通路分析 (JAK/STAT + NF-kB)
# 数据源：CosMx Slide1（panel 覆盖足够）
# ============================================================
rm(list = ls()); gc()
setwd("~/Desktop/sjfx3")
suppressPackageStartupMessages({
  library(Seurat); library(tidyverse); library(ggplot2)
})

cosmx1 <- readRDS("data/GSM8855042_Slide1_SeuratObject.RDS")
col1 <- "RNA_nbclust_8b0a3ae1.8754.4ba9.8269.45e2cf2e855a_1_clusters"
celltype_vec <- cosmx1@meta.data[[col1]]
expr <- cosmx1[["RNA"]]$data
coords <- cosmx1@meta.data[, c("x_slide_mm", "y_slide_mm", "fov")]

hep4_idx <- which(celltype_vec == "Hep.4")
il6r_expr <- as.numeric(expr["IL6R", ])
il11ra_expr <- as.numeric(expr["IL11RA", ])

# Hep.4 分层
hep4_il6r_pos <- hep4_idx[il6r_expr[hep4_idx] > 0]
hep4_il6r_neg <- hep4_idx[il6r_expr[hep4_idx] == 0]

# ---- 1. JAK/STAT 通路评分 ----
jak_stat_genes <- c("JAK1", "JAK2", "TYK2", "STAT1", "STAT3",
                    "STAT5A", "STAT5B")
jak_stat_genes <- jak_stat_genes[jak_stat_genes %in% rownames(expr)]

# z-score
mat_z <- t(scale(t(expr[jak_stat_genes, , drop = FALSE])))
mat_z[is.na(mat_z)] <- 0
jak_stat_score <- colMeans(mat_z)

# ---- 2. NF-kB 通路评分 ----
nfkb_genes <- c("NFKB1", "RELA", "NFKBIA")
nfkb_genes <- nfkb_genes[nfkb_genes %in% rownames(expr)]
mat_z2 <- t(scale(t(expr[nfkb_genes, , drop = FALSE])))
mat_z2[is.na(mat_z2)] <- 0
nfkb_score <- colMeans(mat_z2)

# ---- 3. 比较 IL6R+ vs IL6R− Hep.4 的通路活性 ----
cat("========== Hep.4 通路活性 (IL6R+ vs IL6R−) ==========\n")

jak_stat_pos <- jak_stat_score[hep4_il6r_pos]
jak_stat_neg <- jak_stat_score[hep4_il6r_neg]
nfkb_pos <- nfkb_score[hep4_il6r_pos]
nfkb_neg <- nfkb_score[hep4_il6r_neg]

w_jak <- wilcox.test(jak_stat_pos, jak_stat_neg)
w_nfkb <- wilcox.test(nfkb_pos, nfkb_neg)

cat(sprintf("JAK/STAT: IL6R+ = %.3f, IL6R− = %.3f, P = %.2e\n",
            mean(jak_stat_pos), mean(jak_stat_neg), w_jak$p.value))
cat(sprintf("NF-κB:    IL6R+ = %.3f, IL6R− = %.3f, P = %.2e\n",
            mean(nfkb_pos), mean(nfkb_neg), w_nfkb$p.value))

# ---- 4. 关键：STAT3 单基因 vs IL6R ----
stat3_expr <- as.numeric(expr["STAT3", hep4_idx])
il6r_expr_hep4 <- as.numeric(expr["IL6R", hep4_idx])

ct_stat3 <- cor.test(stat3_expr, il6r_expr_hep4, method = "spearman")
cat(sprintf("\nSTAT3 vs IL6R in Hep.4: rho = %.3f, P = %.2e\n",
            ct_stat3$estimate, ct_stat3$p.value))

# ---- 5. 可视化 ----
df_viz <- rbind(
  data.frame(Group = "IL6R+", Pathway = "JAK/STAT",
             Score = jak_stat_pos),
  data.frame(Group = "IL6R−", Pathway = "JAK/STAT",
             Score = jak_stat_neg),
  data.frame(Group = "IL6R+", Pathway = "NF-κB",
             Score = nfkb_pos),
  data.frame(Group = "IL6R−", Pathway = "NF-κB",
             Score = nfkb_neg)
)
df_viz$Group <- factor(df_viz$Group, levels = c("IL6R−", "IL6R+"))

p_pw <- ggplot(df_viz, aes(Group, Score, fill = Group)) +
  geom_violin(alpha = 0.5, scale = "width") +
  geom_boxplot(width = 0.2, outlier.shape = NA, alpha = 0.9) +
  facet_wrap(~ Pathway, scales = "free_y") +
  scale_fill_manual(values = c("IL6R+" = "#C73E1D",
                               "IL6R−" = "#2E86AB")) +
  labs(title = "JAK/STAT and NF-κB activity in Hep.4 stratified by IL6R",
       subtitle = sprintf("JAK/STAT P = %.2e; NF-κB P = %.2e",
                          w_jak$p.value, w_nfkb$p.value),
       x = NULL, y = "Pathway score (z-mean)") +
  theme_classic(base_size = 11) +
  theme(legend.position = "none")

ggsave("figures/Figure2/Fig_Hep4_pathway_IL6R.pdf", p_pw,
       width = 7, height = 4)
ggsave("figures/Figure2/Fig_Hep4_pathway_IL6R.png", p_pw,
       width = 7, height = 4, dpi = 300)

