# ============================================================
# AUC bootstrap 置信区间
# ============================================================
rm(list = ls()); gc()
setwd("~/Desktop/sjfx3")
suppressPackageStartupMessages({
  library(pROC); library(tidyverse)
})

val <- readRDS("results/GSE49541_validation_unified_zscored.rds")
df <- data.frame(
  outcome = as.integer(val$group),
  pred = as.numeric(val$pred_prob)
)
df <- df[!is.na(df$outcome), ]

set.seed(123)
n_boot <- 2000
auc_boot <- numeric(n_boot)
for (i in 1:n_boot) {
  idx <- sample(seq_len(nrow(df)), replace = TRUE)
  d <- df[idx, ]
  if (length(unique(d$outcome)) < 2) next
  auc_boot[i] <- as.numeric(pROC::auc(pROC::roc(d$outcome, d$pred,
                                                quiet = TRUE)))
}

ci_boot <- quantile(auc_boot, c(0.025, 0.975), na.rm = TRUE)
cat(sprintf("Bootstrap AUC = %.3f (95%% CI: %.3f-%.3f)\n",
            mean(auc_boot, na.rm = TRUE), ci_boot[1], ci_boot[2]))

saveRDS(list(auc_boot = auc_boot, ci = ci_boot),
        "results/AUC_bootstrap.rds")

