# ---- 手动下载（浏览器操作）----
# ENCODE 肝 ATAC-seq：
#   1. 打开 https://www.encodeproject.org/
#   2. 搜索 "liver ATAC-seq human"
#   3. 筛选：Assay = ATAC-seq, Organism = Homo sapiens,
#      Biosample = liver
#   4. 选 1-2 个数据集，下载 "Peaks" (BED narrowPeak 格式)
#   5. 保存到 data/ATAC/

# ---- 分析（假设已下载）----
atac_files <- list.files("data/ATAC", pattern = "\\.bed$|\\.narrowPeak$",
                         full.names = TRUE)
cat(sprintf("ATAC files: %d\n", length(atac_files)))

# HGF 启动子区（hg38: chr7:81,699,000-81,702,000）
hgf_promoter <- GRanges(
  seqnames = "chr7",
  ranges = IRanges(start = 81699000, end = 81702000)
)

# 检查每个 ATAC 文件是否与 HGF 启动子重叠
check_overlap <- function(f) {
  peaks <- tryCatch(import(f), error = function(e) NULL)
  if (is.null(peaks)) return(NULL)
  peaks <- keepStandardChromosomes(peaks, pruning.mode = "coarse")
  hits <- findOverlaps(peaks, hgf_promoter)
  data.frame(
    File = basename(f),
    n_peaks = length(peaks),
    n_HGF_promoter = length(hits),
    HGF_open = length(hits) > 0
  )
}

atac_summary <- purrr::map_dfr(atac_files, check_overlap)
print(atac_summary)
write.csv(atac_summary, "results/HGF_promoter_ATAC.csv", row.names = FALSE)

cat(sprintf("\nHGF 启动子在肝组织中开放: %s\n",
            any(atac_summary$HGF_open)))

