# ============================================================
# F0–F4 补充分析：11-gene signature + IL6 环路 + 下游通路
# 数据源：GSE135251（n = 216, F0–F4）
# ============================================================
rm(list = ls()); gc()
setwd("~/Desktop/sjfx3")
suppressPackageStartupMessages({
  library(tidyverse); library(org.Hs.eg.db); library(clinfun)
})

dir.create("results", showWarnings = FALSE)
dir.create("figures/Figure2", showWarnings = FALSE, recursive = TRUE)

# ---- 1. 加载数据 ----
data <- readRDS("results/GSE135251_DEG_results.rds")
log_expr <- data$log_expr
stage <- data$fibro_stage

# Ensembl -> Symbol
sym <- mapIds(org.Hs.eg.db, keys = rownames(log_expr),
              column = "SYMBOL", keytype = "ENSEMBL", multiVals = "first")
valid <- !is.na(sym) & !duplicated(sym)
log_expr_sym <- log_expr[valid, ]; rownames(log_expr_sym) <- sym[valid]

# ---- 2. 定义基因集 ----
sig11 <- c("EYA2", "FERMT1", "PYROXD2", "EPB41L4A", "CHI3L1",
           "CNKSR1", "ILDR1", "GSN", "TMPRSS3", "ESRRG", "SULF2")

il6_ligands <- c("HGF", "IL6", "IL11", "LIF", "OSM", "CTF1")
il6_receptors <- c("IL6R", "IL11RA", "IL6ST", "OSMR", "LIFR")
jak_stat <- c("JAK1", "JAK2", "TYK2", "STAT1", "STAT3",
              "STAT5A", "STAT5B")
nfkb <- c("NFKB1", "RELA", "NFKBIA", "TNF", "IL1B", "IL6")

# ---- 3. 辅助函数：分期趋势检验 ----
run_trend <- function(expr_vec, stage) {
  kt <- kruskal.test(expr_vec ~ factor(stage))
  jt <- jonckheere.test(expr_vec, as.numeric(factor(stage)),
                        alternative = "increasing")
  sp <- cor.test(expr_vec, stage, method = "spearman")
  list(KW_P = kt$p.value, JT_P = jt$p.value,
       rho = as.numeric(sp$estimate),
       sp_P = sp$p.value,
       means = tapply(expr_vec, stage, mean))
}

# ============================================================
# Analysis 1: 11-gene signature 沿 F0–F4 趋势
# ============================================================
cat("\n========== 1. 11-gene signature 沿 F0–F4 ==========\n")

sig11_in <- intersect(sig11, rownames(log_expr_sym))
cat(sprintf("11-gene signature 可用: %d / 11\n", length(sig11_in)))

# z-score 平均打分
mat_z <- t(scale(t(log_expr_sym[sig11_in, , drop = FALSE])))
mat_z[is.na(mat_z)] <- 0
sig11_score <- colMeans(mat_z)

res_sig11 <- run_trend(sig11_score, stage)
cat(sprintf("Kruskal-Wallis P = %.3e\n", res_sig11$KW_P))
cat(sprintf("Jonckheere-Terpstra P = %.3e\n", res_sig11$JT_P))
cat(sprintf("Spearman rho = %.3f, P = %.3e\n",
            res_sig11$rho, res_sig11$sp_P))

cat("\n各分期平均 score:\n")
print(round(res_sig11$means, 3))

# ============================================================
# Analysis 2: 11 个基因各自的单基因趋势
# ============================================================
cat("\n========== 2. 11 个基因各自的单基因趋势 ==========\n")

single_gene_results <- data.frame()
for (g in sig11_in) {
  expr_g <- as.numeric(log_expr_sym[g, ])
  res <- run_trend(expr_g, stage)
  single_gene_results <- rbind(single_gene_results, data.frame(
    Gene = g,
    KW_P = res$KW_P,
    JT_P = res$JT_P,
    Spearman_rho = round(res$rho, 3),
    Spearman_P = res$sp_P,
    Mean_F0 = round(res$means["0"], 3),
    Mean_F1 = round(res$means["1"], 3),
    Mean_F2 = round(res$means["2"], 3),
    Mean_F3 = round(res$means["3"], 3),
    Mean_F4 = round(res$means["4"], 3)
  ))
}
single_gene_results <- single_gene_results[order(-single_gene_results$Spearman_rho), ]
print(single_gene_results)

write.csv(single_gene_results,
          "results/F0F4_11gene_individual_trends.csv",
          row.names = FALSE)

# ============================================================
# Analysis 3: IL6 家族配体-受体沿 F0–F4 趋势
# ============================================================
cat("\n========== 3. IL6 家族配体-受体沿 F0–F4 ==========\n")

il6_all <- c(il6_ligands, il6_receptors)
il6_in <- intersect(il6_all, rownames(log_expr_sym))
cat(sprintf("IL6 家族基因可用: %d / %d\n", length(il6_in), length(il6_all)))

il6_results <- data.frame()
for (g in il6_in) {
  expr_g <- as.numeric(log_expr_sym[g, ])
  res <- run_trend(expr_g, stage)
  il6_results <- rbind(il6_results, data.frame(
    Gene = g,
    Type = ifelse(g %in% il6_ligands, "Ligand", "Receptor"),
    JT_P = res$JT_P,
    Spearman_rho = round(res$rho, 3),
    Spearman_P = res$sp_P,
    Mean_F0 = round(res$means["0"], 3),
    Mean_F4 = round(res$means["4"], 3)
  ))
}
il6_results <- il6_results[order(-il6_results$Spearman_rho), ]
print(il6_results)

write.csv(il6_results,
          "results/F0F4_IL6_family_trends.csv",
          row.names = FALSE)

# ============================================================
# Analysis 4: JAK/STAT 和 NF-κB 通路沿 F0–F4 趋势
# ============================================================
cat("\n========== 4. 下游通路沿 F0–F4 ==========\n")

# JAK/STAT 通路
jak_in <- intersect(jak_stat, rownames(log_expr_sym))
mat_z_jak <- t(scale(t(log_expr_sym[jak_in, , drop = FALSE])))
mat_z_jak[is.na(mat_z_jak)] <- 0
jak_score <- colMeans(mat_z_jak)
res_jak <- run_trend(jak_score, stage)

# NF-κB 通路
nfkb_in <- intersect(nfkb, rownames(log_expr_sym))
mat_z_nfkb <- t(scale(t(log_expr_sym[nfkb_in, , drop = FALSE])))
mat_z_nfkb[is.na(mat_z_nfkb)] <- 0
nfkb_score <- colMeans(mat_z_nfkb)
res_nfkb <- run_trend(nfkb_score, stage)

cat(sprintf("JAK/STAT: JT P = %.3e, rho = %.3f, P = %.3e\n",
            res_jak$JT_P, res_jak$rho, res_jak$sp_P))
cat(sprintf("NF-κB:    JT P = %.3e, rho = %.3f, P = %.3e\n",
            res_nfkb$JT_P, res_nfkb$rho, res_nfkb$sp_P))

pathway_summary <- data.frame(
  Pathway = c("JAK/STAT", "NF-kB"),
  N_genes = c(length(jak_in), length(nfkb_in)),
  JT_P = c(res_jak$JT_P, res_nfkb$JT_P),
  Spearman_rho = c(round(res_jak$rho, 3), round(res_nfkb$rho, 3)),
  Spearman_P = c(res_jak$sp_P, res_nfkb$sp_P),
  Mean_F0 = c(round(res_jak$means["0"], 3), round(res_nfkb$means["0"], 3)),
  Mean_F4 = c(round(res_jak$means["4"], 3), round(res_nfkb$means["4"], 3))
)
print(pathway_summary)

write.csv(pathway_summary,
          "results/F0F4_downstream_pathways.csv",
          row.names = FALSE)

# ============================================================
# 可视化：4-panel Figure S12
# ============================================================
# Panel a: 11-gene signature 沿 F0-F4
df_a <- data.frame(Stage = stage, Score = sig11_score)

p_a <- ggplot(df_a, aes(factor(Stage), Score, fill = factor(Stage))) +
  geom_boxplot(alpha = 0.85, outlier.shape = NA) +
  geom_jitter(width = 0.2, size = 0.3, alpha = 0.25) +
  geom_smooth(aes(group = 1), method = "lm", se = TRUE,
