# 2026.10.12 补充分析：本地孟德尔随机化分析
# ============================================================
# ============================================================
# 本地 MR 分析：eQTLGen cis-eQTL (暴露) vs NAFLD GWAS (结局)
# ============================================================

library(data.table)
library(dplyr)
library(TwoSampleMR)

# ---- 1. 读取 eQTL 暴露数据（2MB 小文件，可直接读） ----
eqtl <- fread("data/MR/2019-12-11-cis-eQTLsFDR-ProbeLevel-CohortInfoRemoved-BonferroniAdded.txt.gz")
cat(sprintf("eQTL 总行数: %d\n", nrow(eqtl)))

# ---- 2. 筛选目标基因 ----
target_genes <- c("CHI3L1", "HGF", "SULF2", "IL6R", "IL11RA", "LIFR", "OSMR", "GSN")

# 如果 GeneSymbol 列名不对，用 Gene 列（Ensembl ID）也可以
eqtl_sub <- eqtl %>% filter(GeneSymbol %in% target_genes)
cat(sprintf("目标基因 SNP 数: %d\n", nrow(eqtl_sub)))
print(table(eqtl_sub$GeneSymbol))

# 严格筛选全基因组显著（P < 5e-8）
eqtl_sub <- eqtl_sub %>% filter(Pvalue < 5e-08)
cat(sprintf("P < 5e-8 后: %d\n", nrow(eqtl_sub)))
print(table(eqtl_sub$GeneSymbol))

# ---- 3. 从 Zscore 反推 Beta 和 SE ----
# 用 MAF = 0.25 近似（cis-eQTL 常见变异的典型范围）
MAF <- 0.25
eqtl_sub <- eqtl_sub %>%
  mutate(
    denom = sqrt(2 * MAF * (1 - MAF) * (NrSamples + Zscore^2)),
    Beta  = Zscore / denom,
    SE    = 1 / denom
  )

# ---- 4. 格式化为 TwoSampleMR 暴露格式 ----
exposure_dat <- format_data(
  as.data.frame(eqtl_sub),
  type = "exposure",
  snp_col = "SNP",
  beta_col = "Beta",
  se_col = "SE",
  effect_allele_col = "AssessedAllele",
  other_allele_col = "OtherAllele",
  pval_col = "Pvalue",
  phenotype_col = "GeneSymbol"
)
exposure_dat$exposure <- paste0(exposure_dat$exposure, " (eQTLGen)")

cat(sprintf("暴露数据: %d SNP, %d 基因\n",
            nrow(exposure_dat),
            length(unique(exposure_dat$exposure))))
# ---- 4b. 手动 cis-clumping（不依赖 PLINK 和参考面板）----
# 对每个基因：按 P 值排序，保留最显著的 SNP，
# 移除距离它 ±1 Mb 内的其他 SNP，重复直到没有 SNP 可保留

manual_cis_clump <- function(df, window = 1e6) {
  # df 需要列：SNP, Pvalue, SNPPos, SNPChr
  df <- df[order(df$Pvalue), ]
  keep <- c()
  while (nrow(df) > 0) {
    top <- df[1, ]
    keep <- c(keep, top$SNP)
    # 移除与 top 在同一染色体且距离 < window 的 SNP
    df <- df[!(df$SNPChr == top$SNPChr &
                 abs(df$SNPPos - top$SNPPos) < window), ]
  }
  keep
}

# 对每个基因分别做 clumping
exposure_clumped <- list()
for (gene in unique(eqtl_sub$GeneSymbol)) {
  sub <- eqtl_sub %>% filter(GeneSymbol == gene)
  keep_snps <- manual_cis_clump(sub, window = 1e6)   # 1 Mb 窗口
  exposure_clumped[[gene]] <- sub %>% filter(SNP %in% keep_snps)
  cat(sprintf("%s: %d SNP -> %d SNP\n",
              gene, nrow(sub), length(keep_snps)))
}

eqtl_sub_clumped <- do.call(rbind, exposure_clumped)

# 用 clumped 后的数据重新做 format_data
exposure_dat <- format_data(
  as.data.frame(eqtl_sub_clumped),
  type = "exposure",
  snp_col = "SNP",
  beta_col = "Beta",
  se_col = "SE",
  effect_allele_col = "AssessedAllele",
  other_allele_col = "OtherAllele",
  pval_col = "Pvalue",
  phenotype_col = "GeneSymbol"
)
exposure_dat$exposure <- paste0(exposure_dat$exposure, " (eQTLGen)")

cat(sprintf("Clumping 后暴露数据: %d SNP, %d 基因\n",
            nrow(exposure_dat),
            length(unique(exposure_dat$exposure))))
# ---- 5. 读取结局数据 (NAFLD GWAS) ----
outcome_dat <- read_outcome_data(
  snps = exposure_dat$SNP,
  filename = "data/MR/GCST90091033_buildGRCh37.tsv.gz",
  sep = "\t",
  snp_col = "variant_id",
  beta_col = "beta",
  se_col = "standard_error",
  effect_allele_col = "effect_allele",
  other_allele_col = "other_allele",
  eaf_col = "effect_allele_frequency",
  pval_col = "p_value"
)
outcome_dat$outcome <- "NAFLD (GCST90091033)"

cat(sprintf("结局数据匹配到: %d SNP\n", nrow(outcome_dat)))

# ---- 6. 数据协调 ----
dat <- harmonise_data(
  exposure_dat = exposure_dat,
  outcome_dat = outcome_dat,
  action = 2
)
dat <- dat[dat$mr_keep == TRUE, ]
cat(sprintf("协调后有效 SNP: %d\n", nrow(dat)))

# ---- 7. F 统计量 ----
dat$F_stat <- (dat$beta.exposure / dat$se.exposure)^2
cat(sprintf("平均 F 统计量: %.1f\n", mean(dat$F_stat)))
cat(sprintf("F < 10 的弱工具变量: %d\n", sum(dat$F_stat < 10)))

# ---- 8. MR 分析（单 SNP 用 Wald ratio）----
mr_results <- mr(
  dat,
  method_list = c("mr_wald_ratio",   # ← 关键：单 SNP 用 Wald ratio
                  "mr_ivw",          # 有多个 SNP 时会用到
                  "mr_egger_regression",
                  "mr_weighted_median")
)
mr_results_or <- generate_odds_ratios(mr_results)
print(mr_results_or)

# ---- 9. 敏感性分析 ----
heterogeneity <- mr_heterogeneity(dat)
pleiotropy   <- mr_pleiotropy_test(dat)
print(heterogeneity)
print(pleiotropy)

# ---- 10. 保存结果 ----
dir.create("results/MR", showWarnings = FALSE, recursive = TRUE)
write.csv(mr_results_or, "results/MR/MR_results.csv", row.names = FALSE)
write.csv(heterogeneity, "results/MR/MR_heterogeneity.csv", row.names = FALSE)
write.csv(pleiotropy,   "results/MR/MR_pleiotropy.csv", row.names = FALSE)
write.csv(dat,          "results/MR/MR_harmonised_data.csv", row.names = FALSE)

# ---- 11. 可视化 ----
p1 <- mr_scatter_plot(mr_results, dat)
ggsave("results/MR/MR_scatter.pdf", p1[[1]], width = 8, height = 6)

res_single <- mr_singlesnp(dat)
p2 <- mr_forest_plot(res_single)
ggsave("results/MR/MR_forest.pdf", p2[[1]], width = 8, height = 8)

p3 <- mr_funnel_plot(res_single)
ggsave("results/MR/MR_funnel.pdf", p3[[1]], width = 8, height = 6)

cat("\n分析完成，结果已保存到 results/MR/\n")

