# ---- 训练集：用 z-score 后的特征拟合 Firth 模型 ----
ml <- readRDS("results/Module1_ROC_results_zscored.rds")
X_z <- ml$X_z
y   <- ml$y
core_genes <- ml$core_genes

df_train <- data.frame(X_z[, core_genes, drop = FALSE], y = y)
fit_firth <- logistf(y ~ ., data = df_train)

cat("=== Firth 模型系数 ===\n")
