colnames(df_val) <- core_genes

pred_firth <- predict(fit_firth, newdata = df_val, type = "response")

keep <- !is.na(group_val)
roc_firth <- roc(group_val[keep], pred_firth[keep], quiet = TRUE)
auc_firth <- as.numeric(auc(roc_firth))
ci_firth  <- as.numeric(ci.auc(roc_firth))
brier_firth <- mean((pred_firth[keep] - group_val[keep])^2)

cal_model <- glm(group_val[keep] ~ qlogis(pred_firth[keep]),
                 family = binomial)
cal_slope_firth <- coef(cal_model)[2]
cal_intercept_firth <- coef(cal_model)[1]

cat(sprintf("\n=== Firth 校正外部验证 ===\n"))
