# 分箱
make_cal <- function(pred, obs, label) {
  df <- data.frame(pred = pred, obs = obs)
  df$bin <- cut(df$pred, breaks = seq(0, 1, 0.2), include.lowest = TRUE)
  df %>% group_by(bin) %>%
    summarise(mean_pred = mean(pred), obs_rate = mean(obs),
              n = n(), .groups = "drop") %>%
    filter(n >= 3) %>% mutate(Method = label)
}
cal_firth <- make_cal(df_cal$Firth, df_cal$outcome, "Firth")
cal_mle   <- make_cal(df_cal$MLE,   df_cal$outcome, "MLE")
cal_all <- rbind(cal_firth, cal_mle)

p_b <- ggplot(cal_all, aes(mean_pred, obs_rate, color = Method)) +
  geom_abline(intercept = 0, slope = 1, linetype = "dashed",
              color = "grey60") +
