# ============================================================
rm(list = ls()); gc()
setwd("~/Desktop/sjfx3")
suppressPackageStartupMessages({
  library(tidyverse); library(pROC); library(ggplot2)
  library(patchwork)
})

OUT <- "figures/Figure2"
