# ---- 1. 加载三份数据 ----
firth <- readRDS("results/Firth_validation.rds")
val   <- readRDS("results/GSE49541_validation.rds")
mle   <- readRDS("results/GSE49541_validation_unified_zscored.rds")

# ---- 2. 对齐样本 ----
group_val <- as.integer(val$group)
keep <- !is.na(group_val)

# Firth 和 MLE 的预测概率都是全样本长度
df <- data.frame(
  outcome = group_val[keep],
  pred_firth = as.numeric(firth$pred_firth)[keep],
  pred_mle   = as.numeric(mle$pred_prob)[keep]
)

cat(sprintf("分析样本: N = %d, 事件数 = %d (%.1f%%)\n",
            nrow(df), sum(df$outcome), 100 * mean(df$outcome)))

# ---- 3. 点估计 ----
compute_metrics <- function(obs, pred) {
  roc_i <- pROC::roc(obs, pred, quiet = TRUE)
  auc_i <- as.numeric(pROC::auc(roc_i))
  
  # Calibration slope (logistic recalibration on logit(p))
  logit_p <- qlogis(pmin(pmax(pred, 1e-10), 1 - 1e-10))
  cal_i <- glm(obs ~ logit_p, family = binomial)
  slope_i     <- unname(coef(cal_i)[2])
  intercept_i <- unname(coef(cal_i)[1])
  
  # Brier
  brier_i <- mean((pred - obs)^2)
  
  # O/E ratio
  oe_i <- sum(obs) / sum(pred)
  
  c(AUC = auc_i, Brier = brier_i,
    Cal_slope = slope_i, Cal_intercept = intercept_i,
    O_E_ratio = oe_i)
}

point_firth <- compute_metrics(df$outcome, df$pred_firth)
point_mle   <- compute_metrics(df$outcome, df$pred_mle)

cat("\n=== 点估计 ===\n")
cat("Firth:\n"); print(round(point_firth, 3))
cat("\nMLE:\n");   print(round(point_mle, 3))

# ---- 4. Bootstrap (2,000 次) ----
set.seed(123)
n_boot <- 2000
boot_firth <- matrix(NA, n_boot, 5,
                     dimnames = list(NULL,
                                     c("AUC", "Brier", "Cal_slope",
                                       "Cal_intercept", "O_E_ratio")))
boot_mle <- boot_firth

for (i in 1:n_boot) {
  if (i %% 500 == 0) cat(sprintf("  Bootstrap %d / %d\n", i, n_boot))
  idx <- sample(seq_len(nrow(df)), replace = TRUE)
  d <- df[idx, ]
  
  # 跳过只有一类结果的 Bootstrap 样本
  if (length(unique(d$outcome)) < 2) next
  
  boot_firth[i, ] <- tryCatch(
    compute_metrics(d$outcome, d$pred_firth),
    error = function(e) rep(NA, 5)
  )
  boot_mle[i, ] <- tryCatch(
    compute_metrics(d$outcome, d$pred_mle),
    error = function(e) rep(NA, 5)
  )
}

# ---- 5. 汇总 ----
summarize_boot <- function(boot_mat, point, label) {
  ci <- apply(boot_mat, 2, quantile, probs = c(0.025, 0.975),
              na.rm = TRUE)
  data.frame(
    Method = label,
    Metric = colnames(boot_mat),
    Point = round(point, 3),
    Boot_mean = round(apply(boot_mat, 2, mean, na.rm = TRUE), 3),
    CI_low  = round(ci[1, ], 3),
    CI_high = round(ci[2, ], 3),
    stringsAsFactors = FALSE
  )
}

summary_firth <- summarize_boot(boot_firth, point_firth, "Firth")
summary_mle   <- summarize_boot(boot_mle,   point_mle,   "MLE")
summary_all <- rbind(summary_firth, summary_mle)

