# ============================================================
# A1_epv_and_parsimony.R
# 目的：
#   (1) 报告 EPV 并做 bootstrap 稳定性
#   (2) CHI3L1 单基因 vs 11 基因的正式 DeLong 比较
#   (3) 反应 Rashomon effect（多模型同性能）
# ============================================================
# A1 修正版：正确加载验证集表达矩阵
# ============================================================
rm(list = ls()); gc()
setwd("~/Desktop/sjfx3")
suppressPackageStartupMessages({
  library(tidyverse); library(pROC); library(org.Hs.eg.db)
})

dir.create("results/revision", showWarnings = FALSE, recursive = TRUE)

# ---------- 先做字段体检 ----------
cat("=== 检查文件字段 ===\n")
val_unified <- readRDS("results/GSE49541_validation_unified_zscored.rds")
cat("GSE49541_validation_unified_zscored.rds 字段:\n")
print(names(val_unified))

val_raw <- readRDS("results/GSE49541_validation.rds")
cat("\nGSE49541_validation.rds 字段:\n")
print(names(val_raw))

# ---------- 用正确文件加载 expr_gene + group ----------
# expr_gene 在 GSE49541_validation.rds 里
expr_val  <- as.matrix(val_raw$expr_gene)
group_val <- val_raw$group

# pred_prob / ci / auc 在 unified_zscored 里
pred_val  <- as.numeric(val_unified$pred_prob)

cat(sprintf("\nexpr_val:  %d 基因 × %d 样本\n", nrow(expr_val), ncol(expr_val)))
cat(sprintf("group_val: %d (events = %d)\n",
            length(group_val), sum(group_val == 1, na.rm = TRUE)))
cat(sprintf("pred_val:  %d\n", length(pred_val)))

# ---------- 训练集 ----------
data <- readRDS("results/GSE135251_DEG_results.rds")
log_expr <- data$log_expr
y_train  <- as.numeric(data$fibro_stage >= 2)

sym <- mapIds(org.Hs.eg.db, keys = rownames(log_expr),
              column = "SYMBOL", keytype = "ENSEMBL", multiVals = "first")
valid <- !is.na(sym) & !duplicated(sym)
log_expr_sym <- as.matrix(log_expr[valid, ])
rownames(log_expr_sym) <- sym[valid]

sig11 <- c("EYA2","FERMT1","PYROXD2","EPB41L4A","CHI3L1",
           "CNKSR1","ILDR1","GSN","TMPRSS3","ESRRG","SULF2")

# 检查 11 基因是否都在两个数据集里
cat("\n=== 基因可用性 ===\n")
cat("在训练集:", paste(intersect(sig11, rownames(log_expr_sym)), collapse = ", "), "\n")
cat("在验证集:", paste(intersect(sig11, rownames(expr_val)), collapse = ", "), "\n")

# ---------- 预测函数 ----------
fit_predict <- function(genes, train_expr, train_y, test_expr) {
  genes <- genes[genes %in% rownames(train_expr) & genes %in% rownames(test_expr)]
  if (length(genes) == 0) return(rep(NA, ncol(test_expr)))
  
  X_tr <- t(train_expr[genes, , drop = FALSE]); colnames(X_tr) <- genes
  X_tr_z <- scale(X_tr)
  mu  <- attr(X_tr_z, "scaled:center")
  sdv <- attr(X_tr_z, "scaled:scale")
  X_tr_z[is.na(X_tr_z)] <- 0
  
  df_tr <- as.data.frame(X_tr_z); df_tr$y <- train_y
  m <- glm(y ~ ., data = df_tr, family = binomial)
  
  X_te <- t(test_expr[genes, , drop = FALSE]); colnames(X_te) <- genes
  X_te_z <- scale(X_te, center = mu, scale = sdv)
  X_te_z[is.na(X_te_z)] <- 0
  predict(m, newdata = as.data.frame(X_te_z), type = "response")
}

pred_11  <- fit_predict(sig11,        log_expr_sym, y_train, expr_val)
pred_chi <- fit_predict("CHI3L1",     log_expr_sym, y_train, expr_val)

keep <- !is.na(group_val)
roc_11  <- roc(group_val[keep],  pred_11[keep],  quiet = TRUE)
roc_chi <- roc(group_val[keep],  pred_chi[keep], quiet = TRUE)

cat(sprintf("\nAUC (11-gene) = %.3f (%.3f-%.3f)\n",
            auc(roc_11), ci.auc(roc_11)[1], ci.auc(roc_11)[3]))
cat(sprintf("AUC (CHI3L1)  = %.3f (%.3f-%.3f)\n",
            auc(roc_chi), ci.auc(roc_chi)[1], ci.auc(roc_chi)[3]))

# ---------- DeLong 检验 ----------
dl <- roc.test(roc_11, roc_chi, method = "delong")
cat(sprintf("\nDeLong P = %.3f\n", dl$p.value))

# ---------- Bootstrap AUC 差值 ----------
set.seed(123)
n_boot <- 2000
delta_boot <- numeric(n_boot)
for (i in 1:n_boot) {
  idx <- sample(which(keep), replace = TRUE)
  if (length(unique(group_val[idx])) < 2) { delta_boot[i] <- NA; next }
  a1 <- as.numeric(auc(roc(group_val[idx], pred_11[idx],  quiet = TRUE)))
  a2 <- as.numeric(auc(roc(group_val[idx], pred_chi[idx], quiet = TRUE)))
  delta_boot[i] <- a1 - a2
}
ci_delta <- quantile(delta_boot, c(0.025, 0.975), na.rm = TRUE)
cat(sprintf("ΔAUC (11-gene − CHI3L1) = %.3f (95%% CI: %.3f to %.3f)\n",
            mean(delta_boot, na.rm = TRUE), ci_delta[1], ci_delta[2]))

# ---------- 保存 ----------
saveRDS(list(
  auc_11 = as.numeric(auc(roc_11)),
  auc_chi = as.numeric(auc(roc_chi)),
  delong_p = dl$p.value,
  delta_CI = ci_delta,
  pred_11 = pred_11, pred_chi = pred_chi
), "results/revision/A1_parsimony.rds")

cat("\n✅ 修复完成\n")

