# ------------------------------------------------------------
# 1. 患者映射
# ------------------------------------------------------------
add_patient <- function(obj, celltype_col, x_cutoff = 5) {
  fov_x <- obj@meta.data %>%
    group_by(fov) %>%
    summarise(x_center = mean(x_slide_mm), .groups = "drop") %>%
    mutate(patient = ifelse(x_center < x_cutoff, "P_A", "P_B"))
  obj@meta.data$patient <- fov_x$patient[match(obj@meta.data$fov, fov_x$fov)]
  obj
}

cosmx1 <- readRDS("data/GSM8855042_Slide1_SeuratObject.RDS")
cosmx2 <- readRDS("data/GSM8855043_Slide2_SeuratObject.RDS")

cosmx1 <- add_patient(cosmx1,
                      "RNA_nbclust_8b0a3ae1.8754.4ba9.8269.45e2cf2e855a_1_clusters")
cosmx2 <- add_patient(cosmx2,
                      "RNA_nbclust_ee1320c5.9f48.455c.b54e.1fbfd34347ab_1_clusters")

# ------------------------------------------------------------
# 2. 抽取核心变量
# ------------------------------------------------------------
extract_core <- function(obj, celltype_col, slide_label) {
  ct     <- obj@meta.data[[celltype_col]]
  expr   <- obj[["RNA"]]$data
  coords <- obj@meta.data[, c("x_slide_mm","y_slide_mm","fov","patient")]
  coords$celltype <- ct
  coords$HGF     <- as.numeric(expr["HGF", ])
  coords$IL6R    <- as.numeric(expr["IL6R", ])
  coords$slide   <- slide_label
  coords
}

df1 <- extract_core(cosmx1,
                    "RNA_nbclust_8b0a3ae1.8754.4ba9.8269.45e2cf2e855a_1_clusters", "S1")
df2 <- extract_core(cosmx2,
                    "RNA_nbclust_ee1320c5.9f48.455c.b54e.1fbfd34347ab_1_clusters", "S2")
df_all <- rbind(df1, df2)
df_all$patient_uid <- paste(df_all$slide, df_all$patient, sep = "_")
rm(cosmx1, cosmx2); gc()

# ------------------------------------------------------------
# 3. 距离计算
# ------------------------------------------------------------
stellate <- df_all[df_all$celltype == "Stellate.cells", ]
hgf_pos  <- stellate[stellate$HGF > 0, ]
hep4     <- df_all[df_all$celltype == "Hep.4", ]

compute_nn <- function(hep4_df, hgf_df) {
  hep4_df$dist_to_HGFpos_HSC <- NA_real_
  for (f in unique(hep4_df$fov)) {
    h_idx <- which(hep4_df$fov == f)
    g_idx <- which(hgf_df$fov  == f)
    if (length(h_idx) == 0 || length(g_idx) == 0) next
    h_coord <- hep4_df[h_idx, c("x_slide_mm","y_slide_mm")]
    g_coord <- hgf_df[g_idx,  c("x_slide_mm","y_slide_mm")]
    d <- sapply(seq_len(nrow(h_coord)), function(i) {
      sqrt((g_coord$x_slide_mm - h_coord$x_slide_mm[i])^2 +
             (g_coord$y_slide_mm - h_coord$y_slide_mm[i])^2)
    })
    hep4_df$dist_to_HGFpos_HSC[h_idx] <- apply(d, 2, min) * 1000
  }
  hep4_df
}

hep4 <- compute_nn(hep4, hgf_pos)
hep4$IL6R_pos    <- as.numeric(hep4$IL6R > 0)
hep4$dist_scaled <- as.numeric(scale(hep4$dist_to_HGFpos_HSC))

cat(sprintf("Hep.4: %d (IL6R+ %d, IL6R− %d)\n",
            nrow(hep4), sum(hep4$IL6R_pos == 1), sum(hep4$IL6R_pos == 0)))
cat(sprintf("FOV: %d, 患者: %d\n",
            length(unique(hep4$fov)),
            length(unique(hep4$patient_uid))))

# ------------------------------------------------------------
# 4. 报告函数：从 summary 里抽纯数值
# ------------------------------------------------------------
extract_lmer <- function(model, term, label) {
  ct <- summary(model)$coefficients
  beta <- ct[term, "Estimate"]
  se   <- ct[term, "Std. Error"]
  tval <- ct[term, "t value"]
  pval <- ct[term, "Pr(>|t|)"]
  df   <- if ("df" %in% colnames(ct)) ct[term, "df"] else NA
  
  ci_low  <- beta - 1.96 * se
  ci_high <- beta + 1.96 * se
  
  cat(sprintf("  [%s] beta = %+.4f, SE = %.4f, t = %+.3f, df = %.1f, P = %.3e\n",
              label, beta, se, tval, df, pval))
  cat(sprintf("  [%s] 95%% CI: [%+.4f, %+.4f]\n", label, ci_low, ci_high))
  
  # 只返回 data.frame，不返回模型
  list(
    row = data.frame(
      Model = label, Term = term,
      Beta = round(beta, 4), SE = round(se, 4),
      t_value = round(tval, 3),
      df = if (is.na(df)) NA else round(df, 1),
      CI_low = round(ci_low, 4), CI_high = round(ci_high, 4),
      P_value = format(pval, scientific = TRUE, digits = 3),
      P_method = "Satterthwaite",
      Sig = ifelse(pval < 0.05, "YES", "NO"),
      stringsAsFactors = FALSE
    ),
    nums = list(beta = beta, se = se, t = tval, df = df, p = pval,
                ci_low = ci_low, ci_high = ci_high)
  )
}

# ------------------------------------------------------------
# 5. 四个模型
# ------------------------------------------------------------
cat("\n========== 混合效应模型 ==========\n")

naive_t <- t.test(dist_to_HGFpos_HSC ~ IL6R_pos, data = hep4)
cat(sprintf("\n[Naive cell-level t-test] P = %.3e\n", naive_t$p.value))

cat("\n--- FOV random effect ---\n")
m_fov <- lmer(dist_scaled ~ IL6R_pos + (1 | fov),
              data = hep4, REML = FALSE)
res_fov <- extract_lmer(m_fov, "IL6R_pos", "FOV")

cat("\n--- Patient random effect ---\n")
m_pat <- lmer(dist_scaled ~ IL6R_pos + (1 | patient_uid),
              data = hep4, REML = FALSE)
res_pat <- extract_lmer(m_pat, "IL6R_pos", "Patient")

cat("\n--- FOV nested in Patient ---\n")
m_nest <- lmer(dist_scaled ~ IL6R_pos + (1 | patient_uid/fov),
               data = hep4, REML = FALSE)
res_nest <- extract_lmer(m_nest, "IL6R_pos", "Patient/FOV")

# ------------------------------------------------------------
# 6. 患者级聚合
# ------------------------------------------------------------
patient_agg <- hep4 %>%
  group_by(patient_uid, IL6R_pos) %>%
  summarise(median_dist = median(dist_to_HGFpos_HSC, na.rm = TRUE),
            .groups = "drop") %>%
  pivot_wider(names_from = IL6R_pos, values_from = median_dist,
              names_prefix = "IL6R_") %>%
  mutate(delta = IL6R_1 - IL6R_0)

cat("\n--- 患者级汇总 ---\n")
print(as.data.frame(patient_agg))

wilcox_p <- NA_real_
if (nrow(patient_agg) >= 3 && all(!is.na(patient_agg$delta))) {
  w <- wilcox.test(patient_agg$IL6R_1, patient_agg$IL6R_0, paired = TRUE)
  wilcox_p <- w$p.value
  cat(sprintf("Patient-level paired Wilcoxon P = %.3f (n = %d)\n",
              w$p.value, nrow(patient_agg)))
}

# ------------------------------------------------------------
# 7. FOV 聚类稳健 SE
# ------------------------------------------------------------
cat("\n--- FOV 聚类稳健 SE ---\n")
lm_fit <- lm(dist_scaled ~ IL6R_pos, data = hep4)
cl_se  <- vcovCL(lm_fit, cluster = hep4$fov)
ct_cl  <- coeftest(lm_fit, vcov = cl_se)
print(ct_cl)

# ------------------------------------------------------------
# 8. 汇总
# ------------------------------------------------------------
summary_tab <- rbind(res_fov$row, res_pat$row, res_nest$row)
extra_tab <- data.frame(
  Model    = c("Naive t-test (cell-level)", "FOV cluster-robust SE"),
  Term     = "IL6R_pos",
  Beta     = c(NA, round(ct_cl["IL6R_pos","Estimate"], 4)),
  SE       = c(NA, round(ct_cl["IL6R_pos","Std. Error"], 4)),
  t_value  = c(NA, round(ct_cl["IL6R_pos","t value"], 3)),
  df       = NA,
  CI_low   = NA, CI_high = NA,
  P_value  = c(
    format(naive_t$p.value, scientific = TRUE, digits = 3),
    format(ct_cl["IL6R_pos", "Pr(>|t|)"], scientific = TRUE, digits = 3)
  ),
  P_method = c("t-test", "cluster-robust"),
  Sig      = c(
    ifelse(naive_t$p.value < 0.05, "YES", "NO"),
    ifelse(ct_cl["IL6R_pos", "Pr(>|t|)"] < 0.05, "YES", "NO")
  ),
  stringsAsFactors = FALSE
)
summary_tab <- rbind(summary_tab, extra_tab)

cat("\n========== 汇总 ==========\n")
print(summary_tab)
write.csv(summary_tab,
          "results/revision/A3_spatial_mixed_models.csv",
          row.names = FALSE)

# ------------------------------------------------------------
# 9. 保存：只保存数值，不保存 lmerMod 对象
# ------------------------------------------------------------
results_to_save <- list(
