# ---- 复用 A3 的 df_all（这里重建一次）----
add_patient <- function(obj, celltype_col, x_cutoff = 5) {
  fov_x <- obj@meta.data %>%
    group_by(fov) %>%
    summarise(x_center = mean(x_slide_mm), .groups = "drop") %>%
    mutate(patient = ifelse(x_center < x_cutoff, "P_A", "P_B"))
  obj@meta.data$patient <- fov_x$patient[match(obj@meta.data$fov, fov_x$fov)]
  obj
}

