hep4     <- df_all[df_all$celltype == "Hep.4", ]

compute_nn_hsc_to_hep4 <- function(hsc_df, hep4_df) {
  hsc_df$dist_to_Hep4 <- NA_real_
  for (f in unique(hsc_df$fov)) {
    h_idx <- which(hsc_df$fov == f)
    g_idx <- which(hep4_df$fov == f)
    if (length(h_idx) == 0 || length(g_idx) == 0) next
    h_coord <- hsc_df[h_idx, c("x_slide_mm","y_slide_mm")]
    g_coord <- hep4_df[g_idx, c("x_slide_mm","y_slide_mm")]
    d <- sapply(seq_len(nrow(h_coord)), function(i) {
      sqrt((g_coord$x_slide_mm - h_coord$x_slide_mm[i])^2 +
             (g_coord$y_slide_mm - h_coord$y_slide_mm[i])^2)
    })
    hsc_df$dist_to_Hep4[h_idx] <- apply(d, 2, min) * 1000
  }
  hsc_df
}

stellate <- compute_nn_hsc_to_hep4(stellate, hep4)
stellate$HGF_pos    <- as.numeric(stellate$HGF > 0)
stellate$dist_scaled <- as.numeric(scale(stellate$dist_to_Hep4))

cat(sprintf("HSC: %d (HGF+ %d, HGF− %d)\n",
            nrow(stellate),
            sum(stellate$HGF_pos == 1),
            sum(stellate$HGF_pos == 0)))
cat(sprintf("FOV: %d, 患者: %d\n",
            length(unique(stellate$fov)),
            length(unique(stellate$patient_uid))))

# ---- 报告函数（同 A3）----
extract_lmer <- function(model, term, label) {
  ct <- summary(model)$coefficients
  beta <- ct[term, "Estimate"]; se <- ct[term, "Std. Error"]
  tval <- ct[term, "t value"];  pval <- ct[term, "Pr(>|t|)"]
  df   <- if ("df" %in% colnames(ct)) ct[term, "df"] else NA
  ci_low  <- beta - 1.96 * se; ci_high <- beta + 1.96 * se
  
  cat(sprintf("  [%s] beta = %+.4f, SE = %.4f, t = %+.3f, df = %.1f, P = %.3e\n",
              label, beta, se, tval, df, pval))
  cat(sprintf("  [%s] 95%% CI: [%+.4f, %+.4f]\n", label, ci_low, ci_high))
  
  list(
    row = data.frame(
      Model = label, Term = term,
      Beta = round(beta, 4), SE = round(se, 4),
      t_value = round(tval, 3),
      df = if (is.na(df)) NA else round(df, 1),
      CI_low = round(ci_low, 4), CI_high = round(ci_high, 4),
      P_value = format(pval, scientific = TRUE, digits = 3),
      Sig = ifelse(pval < 0.05, "YES", "NO"),
      stringsAsFactors = FALSE
    ),
    nums = list(beta = beta, se = se, t = tval, df = df, p = pval,
                ci_low = ci_low, ci_high = ci_high)
  )
}

