# 检查 stage 与 log_expr 是否对齐
if (length(stage) != ncol(log_expr)) {
  stop("stage 长度与 log_expr 列数不匹配，请检查")
}

# ---------- 2. Ensembl -> Symbol ----------
sym <- mapIds(org.Hs.eg.db, keys = rownames(log_expr),
              column = "SYMBOL", keytype = "ENSEMBL", multiVals = "first")

valid <- !is.na(sym) & !duplicated(sym)
log_expr_sym <- as.matrix(log_expr[valid, ])
rownames(log_expr_sym) <- sym[valid]

cat(sprintf("\nSymbol 映射后: %d 基因\n", nrow(log_expr_sym)))

# ---------- 3. 检查 11 基因 ----------
sig11 <- c("EYA2","FERMT1","PYROXD2","EPB41L4A","CHI3L1",
           "CNKSR1","ILDR1","GSN","TMPRSS3","ESRRG","SULF2")

present <- intersect(sig11, rownames(log_expr_sym))
missing <- setdiff(sig11, rownames(log_expr_sym))

cat(sprintf("\n11 基因可用: %d / 11\n", length(present)))
if (length(missing) > 0) {
  cat("缺失:", paste(missing, collapse = ", "), "\n")
}
cat("使用基因:", paste(present, collapse = ", "), "\n")

if (length(present) < 5) {
  stop("可用基因太少 (<5)，无法计算 signature")
}

# ---------- 4. Signature 打分（z-mean）----------
mat_z <- t(scale(t(log_expr_sym[present, , drop = FALSE])))
mat_z[is.na(mat_z)] <- 0
sig_score <- colMeans(mat_z)

cat(sprintf("\nsig_score: 长度 %d, 范围 %.3f ~ %.3f\n",
            length(sig_score), min(sig_score), max(sig_score)))

# 确认长度对齐
stopifnot(length(sig_score) == length(stage))

# ---------- 5. 亚组索引 ----------
f01 <- which(stage <= 1)
f2  <- which(stage == 2)
f34 <- which(stage >= 3)

cat(sprintf("\n亚组大小: F0-F1 = %d, F2 = %d, F3-F4 = %d\n",
            length(f01), length(f2), length(f34)))

# ---------- 6. 亚组分析函数 ----------
subset_analysis <- function(idx_neg, idx_pos, label, score_vec) {
  if (length(idx_neg) < 5 || length(idx_pos) < 5) {
    cat(sprintf("  [跳过] %s: 组内样本不足 (neg=%d, pos=%d)\n",
                label, length(idx_neg), length(idx_pos)))
    return(NULL)
  }
  idx <- c(idx_neg, idx_pos)
  y   <- c(rep(0, length(idx_neg)), rep(1, length(idx_pos)))
  roc_i <- roc(y, score_vec[idx], quiet = TRUE)
  ci_i  <- as.numeric(ci.auc(roc_i))
  cat(sprintf("  [完成] %s: AUC = %.3f (%.3f-%.3f)\n",
              label, as.numeric(auc(roc_i)), ci_i[1], ci_i[3]))
  data.frame(
    Comparison = label,
    N          = length(idx),
    Events     = length(idx_pos),
    AUC        = round(as.numeric(auc(roc_i)), 3),
    CI_low     = round(ci_i[1], 3),
    CI_high    = round(ci_i[3], 3),
    stringsAsFactors = FALSE
  )
}

cat("\n========== 亚组分析 ==========\n")
res_list <- list(
  subset_analysis(f01, f2,         "F0-F1 vs F2 (indeterminate upper)", sig_score),
  subset_analysis(f2,  f34,        "F2 vs F3-F4 (indeterminate lower)", sig_score),
  subset_analysis(f01, f34,        "F0-F1 vs F3-F4 (mimics GSE49541)",  sig_score),
  subset_analysis(f01, c(f2, f34), "F0-F1 vs F2-F4 (primary training)", sig_score)
)
res_tbl <- do.call(rbind, res_list[!sapply(res_list, is.null)])

print(res_tbl)
write.csv(res_tbl, "results/revision/A2_indeterminate_subset.csv",
          row.names = FALSE)

# ---------- 7. ROC 曲线可视化 ----------
pdf("figures/Figure2/FigureS18_indeterminate_range.pdf",
    width = 8, height = 6)
par(mfrow = c(2, 2))
subset_list <- list(
  list(neg = f01, pos = f2,         title = "F0-F1 vs F2"),
  list(neg = f2,  pos = f34,        title = "F2 vs F3-F4"),
  list(neg = f01, pos = f34,        title = "F0-F1 vs F3-F4"),
  list(neg = f01, pos = c(f2, f34), title = "F0-F1 vs F2-F4")
)
for (s in subset_list) {
  idx <- c(s$neg, s$pos)
  y   <- c(rep(0, length(s$neg)), rep(1, length(s$pos)))
  if (length(unique(y)) < 2) {
    plot.new()
    title(main = sprintf("%s\n(insufficient samples)", s$title))
    next
  }
  r_i <- roc(y, sig_score[idx], quiet = TRUE)
  pROC::plot.roc(r_i, col = "#C73E1D", lwd = 2,
                 main = sprintf("%s\nAUC = %.3f",
                                s$title,
                                as.numeric(pROC::auc(r_i))))
  abline(0, 1, lty = 2, col = "grey60")
  abline(0, 1, lty = 2, col = "grey60")
}
dev.off()

cat("\n✅ A2 完成\n")
cat("输出: results/revision/A2_indeterminate_subset.csv\n")
cat("     figures/Figure2/FigureS18_indeterminate_range.pdf\n")

