suppressPackageStartupMessages({
  library(Seurat); library(tidyverse)
})

dir.create("results/revision", showWarnings = FALSE, recursive = TRUE)

# ---------- 1. 读数据 ----------
sc <- readRDS("results/GSE202379_seurat_clean.rds")
cat(sprintf("总细胞: %d\n", ncol(sc)))

# 注释列确认
cat(sprintf("cell.annotation 唯一值:\n"))
print(table(sc@meta.data$cell.annotation))

# ---------- 2. 抽 Stellate ----------
stellate_cells <- colnames(sc)[sc@meta.data$cell.annotation == "Stellate"]
cat(sprintf("\nStellate 细胞: %d\n", length(stellate_cells)))

sc_sub <- subset(sc, cells = stellate_cells)
rm(sc); gc()
cat(sprintf("子集后: %d 细胞\n", ncol(sc_sub)))

# ---------- 3. HGF+/HGF- 分层 ----------
# 确保用的是 normalized data layer
DefaultAssay(sc_sub) <- "RNA"
hgf_expr <- as.numeric(sc_sub[["RNA"]]$data["HGF", ])

cat(sprintf("\nHGF 表达: 中位数 %.3f, 最大 %.3f\n",
            median(hgf_expr), max(hgf_expr)))
cat(sprintf("HGF > 0 的细胞: %d (%.1f%%)\n",
            sum(hgf_expr > 0),
            100 * mean(hgf_expr > 0)))

sc_sub$hgf_status <- ifelse(hgf_expr > 0, "HGF_pos", "HGF_neg")
cat(sprintf("HGF+ %d, HGF- %d\n",
            sum(sc_sub$hgf_status == "HGF_pos"),
            sum(sc_sub$hgf_status == "HGF_neg")))

# 检查组大小
if (sum(sc_sub$hgf_status == "HGF_pos") < 20 ||
    sum(sc_sub$hgf_status == "HGF_neg") < 20) {
  stop("HGF+/− 组细胞数不足，无法跑 FindMarkers")
}

# ---------- 4. FindMarkers ----------
Idents(sc_sub) <- sc_sub$hgf_status

cat("\n跑 FindMarkers...\n")
deg_sc <- FindMarkers(sc_sub,
                      ident.1 = "HGF_pos",
                      ident.2 = "HGF_neg",
                      logfc.threshold = 0,
                      min.pct = 0.05,
                      verbose = FALSE)
deg_sc$gene <- rownames(deg_sc)

cat(sprintf("DEG 总数: %d\n", nrow(deg_sc)))
cat(sprintf("显著 (p_adj < 0.05): %d\n",
            sum(deg_sc$p_val_adj < 0.05)))

# ---------- 5. 与 16 基因比对 ----------
sig16 <- read.csv("results/signature_HGFpos_up.csv")$gene
cat(sprintf("\n16-gene signature: %d\n", length(sig16)))

overlap <- intersect(sig16, rownames(deg_sc))
cat(sprintf("在 scRNA 中可检测: %d / %d\n",
            length(overlap), length(sig16)))

if (length(overlap) > 0) {
  df_cmp <- data.frame(
    gene = overlap,
    scRNA_log2FC = round(deg_sc[overlap, "avg_log2FC"], 3),
    scRNA_p_adj  = signif(deg_sc[overlap, "p_val_adj"], 3),
    direction_consistent = deg_sc[overlap, "avg_log2FC"] > 0,
    stringsAsFactors = FALSE
  )
  df_cmp <- df_cmp[order(-df_cmp$scRNA_log2FC), ]
  print(df_cmp)
  
  n_consistent <- sum(df_cmp$direction_consistent)
  cat(sprintf("\n=== 方向一致: %d / %d (%.1f%%) ===\n",
              n_consistent, nrow(df_cmp),
              100 * n_consistent / nrow(df_cmp)))
  
  # 保存
  write.csv(df_cmp,
            "results/revision/A4_scRNA_validation_16genes.csv",
            row.names = FALSE)
  cat("✅ 已保存: results/revision/A4_scRNA_validation_16genes.csv\n")
  
  # 额外：显著方向一致的基因数
  n_sig_consistent <- sum(df_cmp$direction_consistent &
                            df_cmp$scRNA_p_adj < 0.05)
  cat(sprintf("显著且方向一致 (p_adj<0.05): %d / %d\n",
              n_sig_consistent, nrow(df_cmp)))
} else {
  cat("⚠️ 16 基因在 scRNA 中无交集\n")
}

rm(sc_sub); gc()
cat("\n✅ A4 scRNA 完成\n")

