# A5: GSE130970 诊断
# ============================================================
gse130_path <- "results/GSE130970_validation.rds"

if (file.exists(gse130_path)) {
  gse130 <- readRDS(gse130_path)
  cat(sprintf("GSE130970: AUC = %.3f (%.3f-%.3f), N = %d, events = %d\n",
              gse130$auc, gse130$ci[1], gse130$ci[3],
              gse130$n, gse130$events))
  
  cat("\n预测概率分布:\n"); print(summary(gse130$pred_prob))
  
  # 校准
  cal_model <- glm(gse130$group ~ qlogis(gse130$pred_prob),
                   family = binomial)
  cat(sprintf("\n校准斜率: %.3f\n", coef(cal_model)[2]))
  cat(sprintf("校准截距: %.3f\n", coef(cal_model)[1]))
  
  # 分位层
  df <- data.frame(
    pred    = as.numeric(gse130$pred_prob),
    outcome = as.integer(gse130$group)
  )
  df$quartile <- ntile(df$pred, 4)
  
  q_summary <- df %>%
    group_by(quartile) %>%
    summarise(n = n(), mean_pred = mean(pred),
              obs_rate = mean(outcome), .groups = "drop")
  cat("\n分位层分析:\n"); print(as.data.frame(q_summary))
  
  # Platt 校准
  if (file.exists("results/Module1_cv_fixed.rds") &&
      file.exists("results/Module1_ROC_results_zscored.rds")) {
    train_cv <- readRDS("results/Module1_cv_fixed.rds")
    train_y  <- readRDS("results/Module1_ROC_results_zscored.rds")$y
    
    platt_train <- data.frame(
      y = as.integer(train_y),
      p = as.numeric(train_cv$cv_pred)
    )
    platt_train$logit_p <- qlogis(pmin(pmax(platt_train$p, 1e-10),
                                       1 - 1e-10))
    platt <- glm(y ~ logit_p, data = platt_train, family = binomial)
    
    df$logit_p  <- qlogis(pmin(pmax(df$pred, 1e-10), 1 - 1e-10))
    df$pred_cal <- predict(platt, newdata = df, type = "response")
    
    roc_cal <- pROC::roc(df$outcome, df$pred_cal, quiet = TRUE)
    cat(sprintf("\nPlatt 校准后 AUC = %.3f (原始 %.3f)\n",
                as.numeric(pROC::auc(roc_cal)), gse130$auc))
  }
  
  gse130_auc_str <- sprintf("%.3f", gse130$auc)
  gse130_n       <- gse130$n
  gse130_events  <- gse130$events
  gse130_erate   <- mean(gse130$group, na.rm = TRUE)
} else {
  cat("⚠️ GSE130970 结果不存在\n")
  gse130_auc_str <- NA; gse130_n <- NA
  gse130_events <- NA; gse130_erate <- NA
}

