target_genes <- c("EYA2","FERMT1","PYROXD2","EPB41L4A","CHI3L1",
                  "CNKSR1","ILDR1","GSN","TMPRSS3","ESRRG","SULF2")

eqtl_sub <- eqtl %>% filter(GeneSymbol %in% target_genes, Pvalue < 5e-08)
cat(sprintf("P < 5e-8 后: %d SNP\n", nrow(eqtl_sub)))
print(table(eqtl_sub$GeneSymbol))

# ---- 3. 手动 cis-clumping（1 Mb）----
manual_cis_clump <- function(df, window = 1e6) {
  df <- df[order(df$Pvalue), ]
  keep <- c()
  while (nrow(df) > 0) {
    top <- df[1, ]
    keep <- c(keep, top$SNP)
    df <- df[!(df$SNPChr == top$SNPChr &
                 abs(df$SNPPos - top$SNPPos) < window), ]
  }
  keep
}

exposure_list <- list()
for (gene in unique(eqtl_sub$GeneSymbol)) {
  sub <- eqtl_sub %>% filter(GeneSymbol == gene)
  keep_snps <- manual_cis_clump(sub, 1e6)
  exposure_list[[gene]] <- sub %>% filter(SNP %in% keep_snps)
}

eqtl_clumped <- do.call(rbind, exposure_list)
cat(sprintf("Clumping 后: %d SNP\n", nrow(eqtl_clumped)))

# ---- 4. 反推 Beta/SE ----
MAF <- 0.25
eqtl_clumped <- eqtl_clumped %>%
  mutate(
    denom = sqrt(2 * MAF * (1 - MAF) * (NrSamples + Zscore^2)),
    Beta  = Zscore / denom,
    SE    = 1 / denom
  )

# ---- 5. 格式化暴露 ----
exposure_dat <- format_data(
  as.data.frame(eqtl_clumped),
  type = "exposure",
  snp_col = "SNP",
  beta_col = "Beta",
  se_col = "SE",
  effect_allele_col = "AssessedAllele",
  other_allele_col = "OtherAllele",
  pval_col = "Pvalue",
  phenotype_col = "GeneSymbol"
)
exposure_dat$exposure <- paste0(exposure_dat$exposure, " (eQTLGen)")

