)
outcome_dat$outcome <- "NAFLD (GCST90091033)"

# ---- 7. Harmonize + MR ----
dat <- harmonise_data(exposure_dat, outcome_dat, action = 2)
dat <- dat[dat$mr_keep == TRUE, ]

# 只保留单 SNP（Wald ratio）
dat_single <- dat %>%
  group_by(exposure) %>%
  filter(n() == 1) %>%
  ungroup() %>%
  as.data.frame()

cat(sprintf("\n单 SNP 可用于 Wald ratio 的基因数: %d\n",
            length(unique(dat_single$exposure))))

mr_results <- mr(dat_single, method_list = "mr_wald_ratio")
mr_results_or <- generate_odds_ratios(mr_results)

# ---- 8. 多重检验校正 ----
mr_results_or$P_bonferroni <- p.adjust(mr_results_or$pval, method = "bonferroni")
mr_results_or$P_BH <- p.adjust(mr_results_or$pval, method = "BH")
mr_results_or <- mr_results_or[order(mr_results_or$pval), ]

print(mr_results_or[, c("exposure", "nsnp", "or", "or_lci95",
                        "or_uci95", "pval", "P_bonferroni", "P_BH")])

