d_neg <- compute_dist(hgf_neg, hep4)

ks <- ks.test(d_pos, d_neg, alternative = "less")
cat(sprintf("\nKS test (HGF+ < HGF-): D = %.3f, P = %.3e\n",
            ks$statistic, ks$p.value))

cohens_d <- function(x, y) {
  (mean(x, na.rm=TRUE) - mean(y, na.rm=TRUE)) /
    sqrt((var(x, na.rm=TRUE) + var(y, na.rm=TRUE)) / 2)
}
cat(sprintf("Cohen's d = %.3f\n", cohens_d(d_pos, d_neg)))

