# ============================================================
# 5. Ripley's K（自己实现，无 spatstat 依赖）
# ============================================================
# 公式：K(r) = (A / n^2) * sum_i sum_{j != i} I(d_ij <= r) * edge_correction
# 简化版用翻译（translation）边界校正：
#   K(r) = (A / n^2) * sum_i sum_{j != i} I(d_ij <= r) / w_ij
# 其中 w_ij 是点 i 的边界权重（权重=1 表示圆形完全在窗口内）
# 或者直接用 Ripley 各向同性校正

ripleys_K <- function(x, y, r_seq, win_x, win_y) {
  n <- length(x)
  if (n < 5) return(NULL)
  area <- diff(win_x) * diff(win_y)
  
  # 计算所有点对距离
  d_mat <- as.matrix(dist(cbind(x, y)))
  
  # 简单边界校正：边界权重 = 圆形在窗口内的比例
  # 用各向同性校正近似
  w_mat <- matrix(1, n, n)
  for (i in 1:n) {
    d_left   <- x[i] - win_x[1]
    d_right  <- win_x[2] - x[i]
    d_bottom <- y[i] - win_y[1]
    d_top    <- win_y[2] - y[i]
    d_min <- min(d_left, d_right, d_bottom, d_top)
    # 对超出边界的对权重为 (pi * r^2) 的分数
    for (j in 1:n) {
      if (i == j) { w_mat[i, j] <- 0; next }
      r <- d_mat[i, j]
      if (r > d_min) {
        # 近似权重
        frac <- d_min / r
        w_mat[i, j] <- max(frac, 0.1)
      }
    }
  }
  
  L_vals <- sapply(r_seq, function(r) {
    I_mat <- (d_mat <= r) * (d_mat > 0)
    K <- sum(I_mat / w_mat) * area / (n * (n - 1))
    sqrt(K / pi) - r
  })
  data.frame(r_um = r_seq * 1000, L = L_vals)
}

# 对每个患者每个 FOV 计算
ripley_res <- data.frame()

for (p in patients) {
  for (f in unique(hgf_pos$fov[hgf_pos$patient_uid == p])) {
    s <- hgf_pos[hgf_pos$patient_uid == p & hgf_pos$fov == f, ]
    if (nrow(s) < 30) next
    
    win_x <- range(s$x_slide_mm)
    win_y <- range(s$y_slide_mm)
    if (diff(win_x) < 0.02 || diff(win_y) < 0.02) next
    
    r_max <- min(diff(win_x), diff(win_y)) / 3
    r_seq <- seq(0.005, r_max, length.out = 20)
    
    L_df <- ripleys_K(s$x_slide_mm, s$y_slide_mm, r_seq, win_x, win_y)
    if (is.null(L_df)) next
    L_df$Patient <- p
    L_df$FOV <- f
    ripley_res <- rbind(ripley_res, L_df)
  }
}

if (nrow(ripley_res) > 0) {
  peak_L <- ripley_res %>%
    group_by(Patient, FOV) %>%
    summarise(peak_L = max(L, na.rm = TRUE), .groups = "drop") %>%
    group_by(Patient) %>%
    summarise(mean_peak_L = round(mean(peak_L, na.rm = TRUE), 4),
              n_FOV = n(), .groups = "drop")
  cat("\n=== Ripley's K 聚类分析（HGF+ HSC）===\n")
  print(as.data.frame(peak_L))
  write.csv(as.data.frame(peak_L),
            "results/supplement/P01_ripley_HGFpos_HSC.csv",
            row.names = FALSE)
  
  p_ripley <- ggplot(ripley_res, aes(r_um, L, color = Patient)) +
    geom_line(stat = "summary", fun = "mean", linewidth = 1) +
    geom_hline(yintercept = 0, linetype = "dashed", color = "grey40") +
    labs(title = "Ripley's L function for HGF+ HSCs",
         subtitle = "L > 0 indicates spatial clustering",
         x = "Distance r (µm)", y = "L(r)", color = NULL) +
    theme_classic(base_size = 11) +
    theme(plot.title = element_text(face = "bold"),
          legend.position = "top")
  ggsave("figures/Figure2/FigS25_ripley_HGFpos.pdf",
         p_ripley, width = 7, height = 5)
