# ============================================================
# 6. 交叉相关（HGF+ HSC 与 IL6R+ Hep.4）
# ============================================================
cross_corr_res <- data.frame()

for (p in patients) {
  for (f in unique(hgf_pos$fov[hgf_pos$patient_uid == p])) {
    hsc <- hgf_pos[hgf_pos$patient_uid == p & hgf_pos$fov == f, ]
    hep <- hep4_il6r[hep4_il6r$patient_uid == p & hep4_il6r$fov == f, ]
    if (nrow(hsc) < 10 || nrow(hep) < 10) next
    
    grid_size <- 0.05
    x_range <- range(c(hsc$x_slide_mm, hep$x_slide_mm))
    y_range <- range(c(hsc$y_slide_mm, hep$y_slide_mm))
    
    x_bins <- seq(x_range[1], x_range[2], by = grid_size)
    y_bins <- seq(y_range[1], y_range[2], by = grid_size)
    
    if (length(x_bins) < 3 || length(y_bins) < 3) next
    
    hsc_grid <- as.vector(table(cut(hsc$x_slide_mm, x_bins),
                                cut(hsc$y_slide_mm, y_bins)))
    hep_grid <- as.vector(table(cut(hep$x_slide_mm, x_bins),
                                cut(hep$y_slide_mm, y_bins)))
    
    if (length(hsc_grid) == length(hep_grid) &&
        length(hsc_grid) > 10 &&
        sd(hsc_grid) > 0 && sd(hep_grid) > 0) {
      ct <- cor.test(hsc_grid, hep_grid, method = "pearson")
      cross_corr_res <- rbind(cross_corr_res, data.frame(
        Patient = p, FOV = f,
        Pearson_r = round(as.numeric(ct$estimate), 3),
        P_value = ct$p.value,
        N_grid = length(hsc_grid)
      ))
    }
  }
}

if (nrow(cross_corr_res) > 0) {
  cat("\n=== 交叉相关（HGF+ HSC vs IL6R+ Hep.4）===\n")
  summary_cc <- cross_corr_res %>%
    group_by(Patient) %>%
    summarise(mean_r = round(mean(Pearson_r, na.rm = TRUE), 3),
              n_FOV = n(), .groups = "drop")
  print(as.data.frame(summary_cc))
  write.csv(as.data.frame(summary_cc),
            "results/supplement/P01_cross_correlation.csv",
            row.names = FALSE)
}

