#   logfc.threshold = 0.25
#   min.pct = 0.1
#   return.object = FALSE

# 检查 HGF 和 MET 是否达到 over-expression 阈值
cat("\n=== over-expression 阈值检查 ===\n")
for (g in c("HGF", "MET")) {
