  pct_global <- mean(x > 0)
  cat(sprintf("\n[%s]\n", g))
  cat(sprintf("  global pos rate: %.3f\n", pct_global))
  # 至少要在某细胞类型达到 10% 阳性
  ct_pos <- tapply(x > 0, ct, mean)
  cat(sprintf("  某细胞类型最高阳性率: %.3f (%s)\n",
              max(ct_pos), names(ct_pos)[which.max(ct_pos)]))
