# ============================================================
# P0-2b: 手动 LR scoring 验证 HGF-MET 耦合
# 不依赖 CellChat 的严格阈值
# ============================================================
rm(list = ls()); gc()
setwd("~/Desktop/sjfx3")
suppressPackageStartupMessages({
  library(Seurat); library(tidyverse); library(ggplot2)
})

dir.create("results/supplement", showWarnings = FALSE, recursive = TRUE)
dir.create("figures/Figure2", showWarnings = FALSE, recursive = TRUE)

# ============================================================
# 1. 加载数据
# ============================================================
cat("加载 CosMx Slide1...\n")
cosmx1 <- readRDS("data/GSM8855042_Slide1_SeuratObject.RDS")
col1 <- "RNA_nbclust_8b0a3ae1.8754.4ba9.8269.45e2cf2e855a_1_clusters"
ct   <- cosmx1@meta.data[[col1]]
expr <- cosmx1[["RNA"]]$data

# 关键细胞群
hsc_idx      <- which(ct == "Stellate.cells")
hgf_expr_all <- as.numeric(expr["HGF", ])
hgf_pos_idx  <- hsc_idx[hgf_expr_all[hsc_idx] > 0]
hgf_neg_idx  <- hsc_idx[hgf_expr_all[hsc_idx] == 0]

hep4_idx     <- which(ct == "Hep.4")
met_expr_all <- as.numeric(expr["MET", ])
hep4_met_pos <- hep4_idx[met_expr_all[hep4_idx] > 0]
hep4_met_neg <- hep4_idx[met_expr_all[hep4_idx] == 0]

cat(sprintf("HGF+ HSC: %d, HGF- HSC: %d\n",
            length(hgf_pos_idx), length(hgf_neg_idx)))
cat(sprintf("MET+ Hep.4: %d, MET- Hep.4: %d\n",
            length(hep4_met_pos), length(hep4_met_neg)))

# ============================================================
# 2. 核心 LR score：HGF 在 sender × MET 在 receiver
# ============================================================
hgf_sender <- as.numeric(expr["HGF", hgf_pos_idx])
met_receiver <- as.numeric(expr["MET", hep4_idx])

# LR score = 平均配体表达 × 平均受体表达
lr_score <- mean(hgf_sender) * mean(met_receiver)
cat(sprintf("\nHGF-MET LR score: %.4f\n", lr_score))
cat(sprintf("  mean HGF in HGF+ HSC: %.3f\n", mean(hgf_sender)))
cat(sprintf("  mean MET in Hep.4:    %.3f\n", mean(met_receiver)))

# ============================================================
# 3. Permutation test（打乱 HGF+ HSC 标签）
# ============================================================
set.seed(123)
n_perm <- 1000
null_scores <- numeric(n_perm)
n_hgf_pos <- length(hgf_pos_idx)
n_hsc_total <- length(hsc_idx)

cat("\nRunning permutation test (1,000 iterations)...\n")
for (i in 1:n_perm) {
  # 从所有 HSC 中随机抽取 n_hgf_pos 个作为"伪 HGF+"
  fake_pos <- sample(hsc_idx, n_hgf_pos)
  fake_hgf <- as.numeric(expr["HGF", fake_pos])
  # 用相同的 Hep.4 MET 表达
  null_scores[i] <- mean(fake_hgf) * mean(met_receiver)
}

p_perm <- mean(null_scores >= lr_score)
cat(sprintf("\n=== Permutation 结果 ===\n"))
cat(sprintf("Observed LR score: %.4f\n", lr_score))
cat(sprintf("Null mean:         %.4f\n", mean(null_scores)))
cat(sprintf("Null SD:           %.4f\n", sd(null_scores)))
cat(sprintf("Permutation P:     %.4f\n", p_perm))

# ============================================================
# 4. 对比：HGF- HSC 的 LR score
# ============================================================
hgf_neg_sender <- as.numeric(expr["HGF", hgf_neg_idx])
lr_score_neg <- mean(hgf_neg_sender) * mean(met_receiver)
cat(sprintf("\nHGF- HSC 的 LR score: %.4f\n", lr_score_neg))
cat(sprintf("HGF+ / HGF- 比值:    %.2f\n",
            lr_score / max(lr_score_neg, 1e-10)))

# ============================================================
# 5. 其他 IL6 家族配体-受体对
# ============================================================
# 配体（HSC 高表达） × 受体（Hep.4 高表达）
lr_pairs <- list(
  c("HGF",   "MET"),
  c("LIF",   "LIFR"),
  c("LIF",   "IL6ST"),
  c("OSM",   "OSMR"),
  c("OSM",   "IL6ST"),
  c("IL6",   "IL6R"),
  c("IL6",   "IL6ST"),
  c("IL11",  "IL11RA")
)

cat("\n=== 其他 IL6 家族配体-受体 LR scores ===\n")
lr_results <- data.frame()

for (pair in lr_pairs) {
  lig <- pair[1]; rec <- pair[2]
  if (!(lig %in% rownames(expr)) || !(rec %in% rownames(expr))) {
    cat(sprintf("%-8s-%s: 不在 panel\n", lig, rec))
    next
  }
  
  lig_pos <- as.numeric(expr[lig, hgf_pos_idx])
  lig_neg <- as.numeric(expr[lig, hgf_neg_idx])
  rec_expr <- as.numeric(expr[rec, hep4_idx])
  
  s_pos <- mean(lig_pos) * mean(rec_expr)
  s_neg <- mean(lig_neg) * mean(rec_expr)
  
  # permutation（简化，只跑 200 次）
  set.seed(123)
  null_s <- numeric(200)
  for (i in 1:200) {
    fake_pos <- sample(hsc_idx, n_hgf_pos)
    null_s[i] <- mean(as.numeric(expr[lig, fake_pos])) * mean(rec_expr)
  }
  p_val <- mean(null_s >= s_pos)
  
  cat(sprintf("%-6s-%-8s: HGF+ = %.4f, HGF- = %.4f, ratio = %.2f, P = %.4f\n",
              lig, rec, s_pos, s_neg,
              s_pos / max(s_neg, 1e-10), p_val))
  
  lr_results <- rbind(lr_results, data.frame(
    Ligand = lig, Receptor = rec,
    LR_HGFpos = round(s_pos, 4),
    LR_HGFneg = round(s_neg, 4),
    Ratio = round(s_pos / max(s_neg, 1e-10), 2),
    P_perm = p_val
  ))
}

print(lr_results)
write.csv(lr_results,
          "results/supplement/P02b_LR_scores_IL6_family.csv",
          row.names = FALSE)

# ============================================================
# 6. 空间验证：MET+ Hep.4 vs MET- Hep.4 到 HGF+ HSC 的距离
# ============================================================
coords <- cosmx1@meta.data[, c("x_slide_mm","y_slide_mm","fov")]

compute_nn <- function(src_idx, tgt_idx) {
  out <- rep(NA_real_, length(src_idx))
  for (f in unique(coords$fov)) {
    s <- src_idx[coords$fov[src_idx] == f]
    t <- tgt_idx[coords$fov[tgt_idx] == f]
    if (length(s) == 0 || length(t) == 0) next
    sc <- coords[s, ]; tc <- coords[t, ]
    for (i in seq_along(s)) {
      d <- sqrt((tc$x_slide_mm - sc$x_slide_mm[i])^2 +
                  (tc$y_slide_mm - sc$y_slide_mm[i])^2)
      out[which(src_idx == s[i])] <- min(d) * 1000
    }
  }
  out
}

cat("\n=== 空间验证 ===\n")
d_met_pos <- compute_nn(hep4_met_pos, hgf_pos_idx)
d_met_neg <- compute_nn(hep4_met_neg, hgf_pos_idx)

cat(sprintf("MET+ Hep.4 → HGF+ HSC: median = %.1f µm\n",
            median(d_met_pos, na.rm = TRUE)))
cat(sprintf("MET- Hep.4 → HGF+ HSC: median = %.1f µm\n",
            median(d_met_neg, na.rm = TRUE)))

w <- wilcox.test(d_met_pos, d_met_neg)
cat(sprintf("Wilcoxon P = %.4e\n", w$p.value))

cohens_d <- function(x, y) {
  (mean(x, na.rm=TRUE) - mean(y, na.rm=TRUE)) /
    sqrt((var(x, na.rm=TRUE) + var(y, na.rm=TRUE)) / 2)
}
cat(sprintf("Cohen's d = %.3f\n", cohens_d(d_met_pos, d_met_neg)))

# ============================================================
# 7. 可视化：LR score 对比
# ============================================================
lr_plot <- rbind(
