)
lr_plot$Group <- factor(lr_plot$Group,
                        levels = c("HGF- HSC → Hep.4",
                                   "HGF+ HSC → Hep.4"))

p_lr <- ggplot(lr_plot, aes(Group, Score, fill = Group)) +
  geom_col(alpha = 0.9, width = 0.6) +
  geom_text(aes(label = sprintf("%.4f", Score)),
            vjust = -0.5, size = 4) +
  scale_fill_manual(values = c("HGF+ HSC → Hep.4" = "#C73E1D",
                               "HGF- HSC → Hep.4" = "#2E86AB")) +
  labs(title = "HGF-MET ligand-receptor score",
       subtitle = sprintf("Permutation P = %.4f, %d iterations",
                          p_perm, n_perm),
       x = NULL, y = "LR score (mean HGF × mean MET)") +
  theme_classic(base_size = 11) +
  theme(legend.position = "none",
        plot.title = element_text(face = "bold")) +
  coord_cartesian(ylim = c(0, max(lr_score, lr_score_neg) * 1.3))

ggsave("figures/Figure2/FigS28_HGF_MET_LR_score.pdf",
       p_lr, width = 6, height = 4.5)
ggsave("figures/Figure2/FigS28_HGF_MET_LR_score.png",
       p_lr, width = 6, height = 4.5, dpi = 300)

# 空间距离 violin
dist_df <- rbind(
  data.frame(Group = "MET+ Hep.4", Distance = d_met_pos),
  data.frame(Group = "MET- Hep.4", Distance = d_met_neg)
)
dist_df <- dist_df[!is.na(dist_df$Distance), ]

p_dist <- ggplot(dist_df, aes(Group, Distance, fill = Group)) +
