cat("固定效应: dist_scaled ~ HGF_pos\n")
cat("随机效应: (1|fov), (1|patient_uid), (1|patient_uid/fov)\n\n")

# 模型 1: FOV 随机效应
m1 <- lmer(dist_scaled ~ HGF_pos + (1 | fov),
           data = stellate, REML = FALSE)
cat("=== 模型 1: (1|FOV) ===\n")
print(summary(m1)$coefficients)

# 手动 95% CI（用 Wald）
coef_tab <- summary(m1)$coefficients
beta <- coef_tab["HGF_pos", "Estimate"]
se   <- coef_tab["HGF_pos", "Std. Error"]
pval <- coef_tab["HGF_pos", "Pr(>|t|)"]
df   <- coef_tab["HGF_pos", "df"]
ci_l <- beta - 1.96 * se
ci_u <- beta + 1.96 * se

cat(sprintf("\n[FOV] beta = %.4f (95%% CI: %.4f to %.4f), t = %.3f, df = %.1f, P = %.3e\n",
            beta, ci_l, ci_u, coef_tab["HGF_pos", "t value"], df, pval))

# 模型 2: Patient 随机效应
m2 <- lmer(dist_scaled ~ HGF_pos + (1 | patient_uid),
           data = stellate, REML = FALSE)
coef_tab <- summary(m2)$coefficients
beta2 <- coef_tab["HGF_pos", "Estimate"]
se2   <- coef_tab["HGF_pos", "Std. Error"]
pval2 <- coef_tab["HGF_pos", "Pr(>|t|)"]
df2   <- coef_tab["HGF_pos", "df"]

cat(sprintf("\n[Patient] beta = %.4f (95%% CI: %.4f to %.4f), t = %.3f, df = %.1f, P = %.3e\n",
            beta2, beta2 - 1.96*se2, beta2 + 1.96*se2,
            coef_tab["HGF_pos", "t value"], df2, pval2))

# 模型 3: Patient/FOV 嵌套
m3 <- lmer(dist_scaled ~ HGF_pos + (1 | patient_uid/fov),
           data = stellate, REML = FALSE)
coef_tab <- summary(m3)$coefficients
beta3 <- coef_tab["HGF_pos", "Estimate"]
se3   <- coef_tab["HGF_pos", "Std. Error"]
pval3 <- coef_tab["HGF_pos", "Pr(>|t|)"]
df3   <- coef_tab["HGF_pos", "df"]

cat(sprintf("\n[Patient/FOV] beta = %.4f (95%% CI: %.4f to %.4f), t = %.3f, df = %.1f, P = %.3e\n",
            beta3, beta3 - 1.96*se3, beta3 + 1.96*se3,
            coef_tab["HGF_pos", "t value"], df3, pval3))

# ---------- 3. 患者级汇总（4 例）----------
cat("\n========== 患者级汇总 ===========\n")
patient_agg <- stellate %>%
  group_by(patient_uid, HGF_pos) %>%
  summarise(median_dist = median(dist_to_Hep4, na.rm = TRUE),
            .groups = "drop") %>%
  pivot_wider(names_from = HGF_pos, values_from = median_dist,
              names_prefix = "HGF_") %>%
  mutate(delta = HGF_1 - HGF_0)

print(as.data.frame(patient_agg))

# 患者级方向一致性
n_neg <- sum(patient_agg$delta < 0, na.rm = TRUE)
binom_p <- binom.test(n_neg, nrow(patient_agg), p = 0.5,
                      alternative = "greater")$p.value
cat(sprintf("\n方向一致性: %d / %d 患者 HGF+ 更近\n", n_neg, nrow(patient_agg)))
cat(sprintf("Binomial test P = %.4f\n", binom_p))

w <- wilcox.test(patient_agg$HGF_1, patient_agg$HGF_0, paired = TRUE)
cat(sprintf("Paired Wilcoxon P = %.4f (n=4, 功效不足)\n", w$p.value))

# ---------- 4. 保存 ----------
saveRDS(list(
  m1_beta = beta, m1_ci = c(ci_l, ci_u), m1_p = pval,
  m2_beta = beta2, m2_p = pval2,
  m3_beta = beta3, m3_p = pval3,
  patient_agg = patient_agg,
  binom_p = binom_p,
  wilcox_p = w$p.value
), "results/supplement/P03_mixed_model_full.rds")


# ============================================================
# P0-4: CellChat 结果深度/细胞数诊断
# ============================================================
rm(list = ls()); gc()
setwd("~/Desktop/sjfx3")
suppressPackageStartupMessages({
  library(Seurat); library(tidyverse)
})

cosmx1 <- readRDS("data/GSM8855042_Slide1_SeuratObject.RDS")
col1 <- "RNA_nbclust_8b0a3ae1.8754.4ba9.8269.45e2cf2e855a_1_clusters"
ct <- cosmx1@meta.data[[col1]]
expr <- cosmx1[["RNA"]]$data

hsc_idx <- which(ct == "Stellate.cells")
hgf_expr <- as.numeric(expr["HGF", hsc_idx])
hgf_pos_idx <- hsc_idx[hgf_expr > 0]
hgf_neg_idx <- hsc_idx[hgf_expr == 0]

ncount <- cosmx1@meta.data$nCount_RNA
nfeat  <- cosmx1@meta.data$nFeature_RNA

cat("========== HGF+ vs HGF- HSC 深度诊断 ==========\n\n")

for (g in c("nCount", "nFeature")) {
  v <- if (g == "nCount") ncount else nfeat
  pos <- v[hgf_pos_idx]; neg <- v[hgf_neg_idx]
  w <- wilcox.test(pos, neg)
  cat(sprintf("[%s]\n", g))
  cat(sprintf("  HGF+ (n=%d): median=%.0f, mean=%.0f\n",
              length(pos), median(pos), mean(pos)))
  cat(sprintf("  HGF- (n=%d): median=%.0f, mean=%.0f\n",
              length(neg), median(neg), mean(neg)))
  cat(sprintf("  Wilcoxon P = %.3e\n\n", w$p.value))
}

# 下采样到相同细胞数 + 相同深度分位
set.seed(123)
n_match <- min(length(hgf_pos_idx), length(hgf_neg_idx))

# 方法 1：随机下采样
pos_ds1 <- sample(hgf_pos_idx, n_match)
neg_ds1 <- sample(hgf_neg_idx, n_match)

# 方法 2：深度分层匹配（按 nCount 分位）
ncount_pos <- ncount[hgf_pos_idx]
ncount_neg <- ncount[hgf_neg_idx]
breaks <- quantile(c(ncount_pos, ncount_neg), probs = seq(0, 1, 0.2))

# 每个分位内匹配
pos_ds2 <- c(); neg_ds2 <- c()
for (i in 1:5) {
  pos_in <- hgf_pos_idx[ncount_pos >= breaks[i] & ncount_pos < breaks[i+1]]
  neg_in <- hgf_neg_idx[ncount_neg >= breaks[i] & ncount_neg < breaks[i+1]]
  n <- min(length(pos_in), length(neg_in))
  if (n > 5) {
    pos_ds2 <- c(pos_ds2, sample(pos_in, n))
    neg_ds2 <- c(neg_ds2, sample(neg_in, n))
  }
}

cat("=== 下采样对比 ===\n")
cat(sprintf("随机下采样: HGF+ n=%d, HGF- n=%d\n",
            length(pos_ds1), length(neg_ds1)))
cat(sprintf("  nCount median: %.0f vs %.0f\n",
            median(ncount[pos_ds1]), median(ncount[neg_ds1])))

cat(sprintf("\n深度分层匹配: HGF+ n=%d, HGF- n=%d\n",
            length(pos_ds2), length(neg_ds2)))
cat(sprintf("  nCount median: %.0f vs %.0f\n",
            median(ncount[pos_ds2]), median(ncount[neg_ds2])))

# 深度匹配后重新计算 HGF-MET LR score
lr_score_pos <- mean(as.numeric(expr["HGF", pos_ds2])) *
  mean(as.numeric(expr["MET", which(ct == "Hep.4")]))
lr_score_neg <- mean(as.numeric(expr["HGF", neg_ds2])) *
  mean(as.numeric(expr["MET", which(ct == "Hep.4")]))

cat(sprintf("\n=== 深度匹配后 LR score ===\n"))
cat(sprintf("HGF+ HSC: %.4f\n", lr_score_pos))
cat(sprintf("HGF- HSC: %.4f\n", lr_score_neg))
cat(sprintf("差异仍然存在: %s\n",
            ifelse(lr_score_pos > lr_score_neg * 10, "✅ 是", "❌ 否")))

saveRDS(list(
  n_match = n_match,
  ncount_pos_median = median(ncount[hgf_pos_idx]),
  ncount_neg_median = median(ncount[hgf_neg_idx]),
  depth_matched_pos_median = median(ncount[pos_ds2]),
  depth_matched_neg_median = median(ncount[neg_ds2]),
  lr_score_pos = lr_score_pos,
  lr_score_neg = lr_score_neg
), "results/supplement/P04_depth_matching.rds")


# ============================================================
# P0-4b FIXED: 正确的深度匹配 permutation
# 关键：pool 里保留所有 HSC（不排除 HGF+）
# ============================================================
rm(list = ls()); gc()
setwd("~/Desktop/sjfx3")
suppressPackageStartupMessages({
  library(Seurat); library(tidyverse)
})

cosmx1 <- readRDS("data/GSM8855042_Slide1_SeuratObject.RDS")
col1 <- "RNA_nbclust_8b0a3ae1.8754.4ba9.8269.45e2cf2e855a_1_clusters"
ct <- cosmx1@meta.data[[col1]]
expr <- cosmx1[["RNA"]]$data

hsc_idx <- which(ct == "Stellate.cells")
hgf_expr <- as.numeric(expr["HGF", hsc_idx])
hgf_pos_idx <- hsc_idx[hgf_expr > 0]

ncount <- cosmx1@meta.data$nCount_RNA
met_mean <- mean(as.numeric(expr["MET", which(ct == "Hep.4")]))

obs_lr <- mean(as.numeric(expr["HGF", hgf_pos_idx])) * met_mean
cat(sprintf("Observed LR score: %.4f\n", obs_lr))

# 分层
quintiles <- quantile(ncount[hsc_idx], probs = seq(0, 1, 0.2))
hsc_layers <- findInterval(ncount[hsc_idx], quintiles)
hsc_layer_map <- setNames(hsc_layers, hsc_idx)
hsc_by_layer  <- split(hsc_idx, hsc_layers)
hgfpos_layers <- hsc_layer_map[as.character(hgf_pos_idx)]
hgfpos_by_layer <- split(hgf_pos_idx, hgfpos_layers)

# ★ 关键修复：pool 里保留所有 HSC（不 setdiff）
set.seed(123)
n_perm <- 200
null_lr_depth <- numeric(n_perm)

for (i in 1:n_perm) {
  fake_cells <- unlist(lapply(names(hgfpos_by_layer), function(l) {
    pos_in_layer <- hgfpos_by_layer[[l]]
    pool <- hsc_by_layer[[l]]                # ← 不 setdiff！
    sample(pool, length(pos_in_layer), replace = TRUE)
  }))
  null_lr_depth[i] <- mean(as.numeric(expr["HGF", fake_cells])) * met_mean
}

cat(sprintf("\n=== 深度匹配 permutation (FIXED) ===\n"))
cat(sprintf("Null mean: %.4f\n", mean(null_lr_depth)))
cat(sprintf("Null SD:   %.4f\n", sd(null_lr_depth)))
cat(sprintf("P value:   %.4f\n", mean(null_lr_depth >= obs_lr)))

# ---------- 对比：不匹配深度的随机 null ----------
set.seed(123)
n_pos <- length(hgf_pos_idx)
null_lr_random <- numeric(n_perm)
for (i in 1:n_perm) {
  fake <- sample(hsc_idx, n_pos, replace = TRUE)
  null_lr_random[i] <- mean(as.numeric(expr["HGF", fake])) * met_mean
}

cat(sprintf("\n=== 随机抽样（不匹配深度）===\n"))
cat(sprintf("Null mean: %.4f\n", mean(null_lr_random)))
cat(sprintf("P value:   %.4f\n", mean(null_lr_random >= obs_lr)))

# ---------- 对比：HGF+ HSC 内部 shuffle ----------
# 这个才是真正检验"HGF+ HSC 的 HGF 分布是否与随机 HSC 一致"
set.seed(123)
null_lr_shuffle <- numeric(n_perm)
for (i in 1:n_perm) {
  # 从所有 HSC 随机抽 n_pos，不排除任何细胞
  fake <- sample(hsc_idx, n_pos, replace = FALSE)
  null_lr_shuffle[i] <- mean(as.numeric(expr["HGF", fake])) * met_mean
}
cat(sprintf("\n=== 无放回随机抽样 ===\n"))
cat(sprintf("Null mean: %.4f\n", mean(null_lr_shuffle)))
cat(sprintf("P value:   %.4f\n", mean(null_lr_shuffle >= obs_lr)))

saveRDS(list(
  obs_lr = obs_lr,
  null_depth_matched = null_lr_depth,
  null_random = null_lr_random,
  null_shuffle = null_lr_shuffle,
  p_depth_matched = mean(null_lr_depth >= obs_lr),
  p_random = mean(null_lr_random >= obs_lr)
), "results/supplement/P04c_corrected_null.rds")

