# ============================================================
# CRITICAL TEST 2 v2: 分位数匹配
# ============================================================
rm(list = ls()); gc()
setwd("~/Desktop/sjfx3")
suppressPackageStartupMessages({
  library(Seurat); library(tidyverse)
})

cosmx1 <- readRDS("data/GSM8855042_Slide1_SeuratObject.RDS")
col1 <- "RNA_nbclust_8b0a3ae1.8754.4ba9.8269.45e2cf2e855a_1_clusters"
ct <- cosmx1@meta.data[[col1]]
expr <- cosmx1[["RNA"]]$data

hsc_idx <- which(ct == "Stellate.cells")
hgf_expr <- as.numeric(expr["HGF", hsc_idx])
hgf_pos_idx <- hsc_idx[hgf_expr > 0]
hgf_neg_idx <- hsc_idx[hgf_expr == 0]

ncount <- cosmx1@meta.data$nCount_RNA

# ---------- 分位数匹配 ----------
set.seed(123)

# HGF+ 每个细胞的深度分位
pos_quantile <- rank(ncount[hgf_pos_idx], ties.method = "average") /
  length(hgf_pos_idx)

# HGF- 按深度排序
neg_sorted <- hgf_neg_idx[order(ncount[hgf_neg_idx])]
n_neg <- length(neg_sorted)

# 每个 HGF+ 匹配到 HGF- 中分位最接近的细胞
matched_neg <- sapply(pos_quantile, function(q) {
  target_idx <- ceiling(q * n_neg)
  target_idx <- max(1, min(n_neg, target_idx))
  neg_sorted[target_idx]
})

# 去重（多个 HGF+ 可能匹配到同一个 HGF-）
# 若无重复则保留，有重复则抖动
if (any(duplicated(matched_neg))) {
  matched_neg <- sample(neg_sorted, length(hgf_pos_idx), replace = FALSE)
}

cat("========== 分位数匹配结果 ==========\n")
cat(sprintf("HGF+ nCount:       median=%.0f, mean=%.0f\n",
            median(ncount[hgf_pos_idx]), mean(ncount[hgf_pos_idx])))
cat(sprintf("匹配后 HGF- nCount: median=%.0f, mean=%.0f\n",
            median(ncount[matched_neg]), mean(ncount[matched_neg])))
cat(sprintf("匹配质量 Wilcoxon P = %.3e\n",
            wilcox.test(ncount[hgf_pos_idx], ncount[matched_neg])$p.value))

# 分布重叠检查
overlap_range <- c(max(min(ncount[hgf_pos_idx]), min(ncount[matched_neg])),
                   min(max(ncount[hgf_pos_idx]), max(ncount[matched_neg])))
cat(sprintf("\n分布重叠区间: [%.0f, %.0f]\n", overlap_range[1], overlap_range[2]))
cat(sprintf("HGF+ 在重叠区间比例: %.1f%%\n",
            100 * mean(ncount[hgf_pos_idx] >= overlap_range[1] &
                         ncount[hgf_pos_idx] <= overlap_range[2])))
cat(sprintf("HGF- 在重叠区间比例: %.1f%%\n",
            100 * mean(ncount[matched_neg] >= overlap_range[1] &
                         ncount[matched_neg] <= overlap_range[2])))

# ---------- 重跑 FindMarkers ----------
matched_cells <- colnames(cosmx1)[c(hgf_pos_idx, matched_neg)]
sub <- subset(cosmx1, cells = matched_cells)
sub$grp <- c(rep("HGF_pos", length(hgf_pos_idx)),
             rep("HGF_neg", length(matched_neg)))

Idents(sub) <- sub$grp
deg_matched <- FindMarkers(sub, ident.1 = "HGF_pos", ident.2 = "HGF_neg",
                           logfc.threshold = 0, min.pct = 0.05,
                           test.use = "wilcox",
                           verbose = FALSE)
deg_matched$gene <- rownames(deg_matched)

# ---------- 检查 16 基因 ----------
sig16 <- read.csv("results/signature_HGFpos_up.csv")$gene
overlap <- intersect(sig16, rownames(deg_matched))

if (length(overlap) > 0) {
  df_check <- data.frame(
    gene = overlap,
    matched_log2FC = round(deg_matched[overlap, "avg_log2FC"], 3),
    matched_p_adj = signif(deg_matched[overlap, "p_val_adj"], 3),
    direction = ifelse(deg_matched[overlap, "avg_log2FC"] > 0, "up", "down")
  )
  df_check <- df_check[order(-df_check$matched_log2FC), ]
  print(df_check)
  
  n_up <- sum(df_check$direction == "up")
  n_sig_up <- sum(df_check$direction == "up" & df_check$matched_p_adj < 0.05)
  
  cat(sprintf("\n=== 分位匹配后 16 基因方向一致: %d/16 ===\n", n_up))
  cat(sprintf("=== 显著上调 (FDR<0.05): %d/16 ===\n", n_sig_up))
  
  if (n_sig_up >= 12) {
    cat("✅ 分子身份独立于深度\n")
  } else if (n_sig_up >= 8) {
    cat("⚠️ 部分保留\n")
  } else {
    cat("❌ 分子身份主要由深度驱动\n")
  }
}

saveRDS(list(
  matched_log2FC = deg_matched,
  df_check = if (exists("df_check")) df_check else NULL,
  matched_neg_ncount_median = median(ncount[matched_neg]),
  hgf_pos_ncount_median = median(ncount[hgf_pos_idx])
), "results/supplement/P05_quantile_matched.rds")

cat("\n✅ 完成\n")


# ============================================================
# CRITICAL TEST 2 v3: Pseudobulk + FOV 协变量
# ============================================================
rm(list = ls()); gc()
setwd("~/Desktop/sjfx3")
suppressPackageStartupMessages({
  library(Seurat); library(tidyverse); library(edgeR); library(limma)
})

cosmx1 <- readRDS("data/GSM8855042_Slide1_SeuratObject.RDS")
col1 <- "RNA_nbclust_8b0a3ae1.8754.4ba9.8269.45e2cf2e855a_1_clusters"
ct <- cosmx1@meta.data[[col1]]
counts <- GetAssayData(cosmx1, assay = "RNA", layer = "counts")
expr   <- cosmx1[["RNA"]]$data

hsc_idx <- which(ct == "Stellate.cells")
hgf_expr <- as.numeric(expr["HGF", hsc_idx])
hgf_pos_idx <- hsc_idx[hgf_expr > 0]
hgf_neg_idx <- hsc_idx[hgf_expr == 0]

fov_vec <- cosmx1@meta.data$fov
ncount_vec <- cosmx1@meta.data$nCount_RNA

fovs <- sort(unique(fov_vec[ hsc_idx ]))

# ---------- 按 FOV 聚合 ----------
# 每个 FOV 生成两列：HGF+ pseudobulk 和 HGF- pseudobulk
mat_pos <- matrix(0, nrow = nrow(counts), ncol = length(fovs),
                  dimnames = list(rownames(counts), paste0("FOV", fovs, "_pos")))
mat_neg <- mat_pos

fov_ncount_pos <- numeric(length(fovs))
fov_ncount_neg <- numeric(length(fovs))
valid_fovs <- c()

for (i in seq_along(fovs)) {
  f <- fovs[i]
  p <- hgf_pos_idx[fov_vec[hgf_pos_idx] == f]
  n <- hgf_neg_idx[fov_vec[hgf_neg_idx] == f]
  if (length(p) < 5 || length(n) < 5) next
  
  mat_pos[, i] <- Matrix::rowSums(counts[, p, drop = FALSE])
  mat_neg[, i] <- Matrix::rowSums(counts[, n, drop = FALSE])
  fov_ncount_pos[i] <- mean(ncount_vec[p])
  fov_ncount_neg[i] <- mean(ncount_vec[n])
  valid_fovs <- c(valid_fovs, i)
}

mat_pos <- mat_pos[, valid_fovs]
mat_neg <- mat_neg[, valid_fovs]
n_pos_vec <- fov_ncount_pos[valid_fovs]
n_neg_vec <- fov_ncount_neg[valid_fovs]

cat(sprintf("有效 FOV 对: %d\n", length(valid_fovs)))
cat(sprintf("HGF+ FOV 平均 nCount: %.0f\n", mean(n_pos_vec)))
cat(sprintf("HGF- FOV 平均 nCount: %.0f\n", mean(n_neg_vec)))

# ---------- Limma 差异分析（配对 + nCount 协变量）----------
mat_all <- cbind(mat_pos, mat_neg)
group <- factor(c(rep("pos", ncol(mat_pos)), rep("neg", ncol(mat_neg))),
                levels = c("neg", "pos"))
pair <- factor(rep(seq_along(valid_fovs), 2))
mean_ncount <- c(n_pos_vec, n_neg_vec)

# 过滤低表达基因
keep <- rowSums(mat_all >= 5) >= 3
mat_all <- mat_all[keep, ]
mean_ncount <- mean_ncount  # 保持不变

dge <- DGEList(counts = mat_all)
dge <- calcNormFactors(dge)

# ★ 关键：用 nCount 作为协变量
design <- model.matrix(~ group + pair + scale(mean_ncount))
# 移除共线性
design <- design[, !duplicated(t(design))]

v <- voom(dge, design, plot = FALSE)
fit <- lmFit(v, design)
fit <- eBayes(fit)

# 提取 group 效应
tt <- topTable(fit, coef = "grouppos", number = Inf, sort.by = "P")
tt$gene <- rownames(tt)

# ---------- 检查 16 基因 ----------
sig16 <- read.csv("results/signature_HGFpos_up.csv")$gene
overlap <- intersect(sig16, rownames(tt))

if (length(overlap) > 0) {
  df_check <- data.frame(
    gene = overlap,
    log2FC = round(tt[overlap, "logFC"], 3),
    p_adj = signif(tt[overlap, "adj.P.Val"], 3),
    direction = ifelse(tt[overlap, "logFC"] > 0, "up", "down")
  )
  df_check <- df_check[order(-df_check$log2FC), ]
  print(df_check)
  
  n_up <- sum(df_check$direction == "up")
  n_sig_up <- sum(df_check$direction == "up" & df_check$p_adj < 0.05)
  
  cat(sprintf("\n=== FOV-pseudobulk + nCount 协变量后 16 基因方向一致: %d/16 ===\n", n_up))
  cat(sprintf("=== 显著上调 (FDR<0.05): %d/16 ===\n", n_sig_up))
}

saveRDS(list(
  tt = tt,
  df_check = if (exists("df_check")) df_check else NULL,
  n_fov_pairs = length(valid_fovs)
), "results/supplement/P05_pseudobulk_ncount_covariate.rds")

cat("\n✅ 完成\n")

