# ============================================================
# Figure S17: Depth-matched validation of the 16-gene HGF+ HSC signature
# Panel a: Quantile-matched comparison
# Panel b: FOV pseudobulk + nCount covariate
# Panel c: scRNA-seq independent validation
# ============================================================
rm(list = ls()); gc()
setwd("~/Desktop/sjfx3")

# ---------- 0. 依赖 ----------
required <- c("tidyverse", "ggplot2", "patchwork")
for (p in required) {
  if (!requireNamespace(p, quietly = TRUE)) {
    install.packages(p, type = "binary",
                     repos = "https://cloud.r-project.org")
  }
}
suppressPackageStartupMessages({
  library(tidyverse); library(ggplot2); library(patchwork)
})

dir.create("figures/Figure2", showWarnings = FALSE, recursive = TRUE)

# ============================================================
# 1. 读三个数据源
# ============================================================
cat("=== 读取数据 ===\n")

qa <- readRDS("results/supplement/P05_quantile_matched.rds")
df_a <- qa$df_check
cat(sprintf("Panel a (quantile-matched): %d genes\n", nrow(df_a)))

pb <- readRDS("results/supplement/P05_pseudobulk_ncount_covariate.rds")
df_b <- pb$df_check
cat(sprintf("Panel b (pseudobulk): %d genes\n", nrow(df_b)))

sc_csv <- "results/revision/A4_scRNA_validation_16genes.csv"
if (file.exists(sc_csv)) {
  df_c <- read.csv(sc_csv)
  cat(sprintf("Panel c (scRNA): %d genes\n", nrow(df_c)))
} else {
  cat("⚠️ 未找到 scRNA 验证结果\n")
  df_c <- NULL
}

# ============================================================
# 2. 统一 16 基因顺序
# ============================================================
sig16 <- read.csv("results/signature_HGFpos_up.csv")$gene
cat(sprintf("\n16 基因 signature: %d\n", length(sig16)))

df_a <- df_a[df_a$gene %in% sig16, ]
df_b <- df_b[df_b$gene %in% sig16, ]

missing_a <- setdiff(sig16, df_a$gene)
missing_b <- setdiff(sig16, df_b$gene)
cat(sprintf("Panel a 缺失: %d (%s)\n", length(missing_a),
            paste(missing_a, collapse = ", ")))
cat(sprintf("Panel b 缺失: %d (%s)\n", length(missing_b),
            paste(missing_b, collapse = ", ")))

if (length(missing_a) > 0) {
  df_a <- rbind(df_a, data.frame(
    gene = missing_a,
    matched_log2FC = NA,
    matched_p_adj = NA,
    direction = NA
  ))
}
if (length(missing_b) > 0) {
  df_b <- rbind(df_b, data.frame(
    gene = missing_b,
    log2FC = NA,
    p_adj = NA,
    direction = NA
  ))
}

df_a$gene <- factor(df_a$gene, levels = sig16)
df_b$gene <- factor(df_b$gene, levels = sig16)
df_a <- df_a[order(df_a$gene), ]
df_b <- df_b[order(df_b$gene), ]

# ============================================================
# 3. Panel a: Quantile-matched
# ============================================================
n_up_a <- sum(df_a$direction == "up", na.rm = TRUE)
n_sig_a <- sum(df_a$direction == "up" & df_a$matched_p_adj < 0.05,
               na.rm = TRUE)

df_a$fill_group <- ifelse(is.na(df_a$matched_log2FC), "NA",
                          ifelse(df_a$matched_log2FC > 0, "Up", "Down"))

p_a <- ggplot(df_a, aes(gene, matched_log2FC, fill = fill_group)) +
  geom_col(alpha = 0.9) +
  geom_hline(yintercept = 0, color = "grey40") +
  scale_fill_manual(values = c("Up" = "#C73E1D",
                               "Down" = "#2E86AB",
                               "NA" = "grey80"),
                    na.value = "grey80") +
  coord_flip() +
  labs(title = "Quantile-matched depth control",
       subtitle = sprintf("%d/16 concordant; %d/16 significant (FDR<0.05)",
                          n_up_a, n_sig_a),
       x = NULL, y = "log2FC (HGF+ vs depth-matched HGF-)") +
  theme_classic(base_size = 10) +
  theme(legend.position = "none",
        plot.title = element_text(face = "bold", size = 10),
        plot.subtitle = element_text(size = 8, color = "grey30"),
        axis.text.y = element_text(size = 8))

# ============================================================
# 4. Panel b: Pseudobulk + nCount covariate
# ============================================================
n_up_b <- sum(df_b$direction == "up", na.rm = TRUE)
n_sig_b <- sum(df_b$direction == "up" & df_b$p_adj < 0.05, na.rm = TRUE)

df_b$fill_group <- ifelse(is.na(df_b$log2FC), "NA",
                          ifelse(df_b$log2FC > 0, "Up", "Down"))

p_b <- ggplot(df_b, aes(gene, log2FC, fill = fill_group)) +
  geom_col(alpha = 0.9) +
  geom_hline(yintercept = 0, color = "grey40") +
  scale_fill_manual(values = c("Up" = "#C73E1D",
                               "Down" = "#2E86AB",
                               "NA" = "grey80"),
                    na.value = "grey80") +
  coord_flip() +
  labs(title = "FOV pseudobulk + nCount covariate",
       subtitle = sprintf("%d/16 concordant; %d/16 significant (FDR<0.05)",
                          n_up_b, n_sig_b),
       x = NULL, y = "log2FC (pseudobulk)") +
  theme_classic(base_size = 10) +
  theme(legend.position = "none",
        plot.title = element_text(face = "bold", size = 10),
        plot.subtitle = element_text(size = 8, color = "grey30"),
        axis.text.y = element_text(size = 8))

# ============================================================
# 5. Panel c: scRNA independent validation
# ============================================================
if (!is.null(df_c) && nrow(df_c) > 0) {
  df_c <- df_c[df_c$gene %in% sig16, ]
  df_c$gene <- factor(df_c$gene, levels = sig16)
  df_c <- df_c[order(df_c$gene), ]
  
  n_up_c <- sum(df_c$direction_consistent, na.rm = TRUE)
  n_sig_c <- sum(df_c$direction_consistent & df_c$scRNA_p_adj < 0.05,
                 na.rm = TRUE)
  
  df_c$fill_group <- ifelse(df_c$scRNA_log2FC > 0, "Up", "Down")
  
  p_c <- ggplot(df_c, aes(gene, scRNA_log2FC, fill = fill_group)) +
    geom_col(alpha = 0.9) +
    geom_hline(yintercept = 0, color = "grey40") +
    scale_fill_manual(values = c("Up" = "#C73E1D",
                                 "Down" = "#2E86AB")) +
    coord_flip() +
    labs(title = "scRNA-seq independent validation",
         subtitle = sprintf("%d/16 concordant; %d/16 significant (FDR<0.05)",
                            n_up_c, n_sig_c),
         x = NULL, y = "log2FC (HGF+ vs HGF- HSC, scRNA)") +
    theme_classic(base_size = 10) +
    theme(legend.position = "none",
          plot.title = element_text(face = "bold", size = 10),
          plot.subtitle = element_text(size = 8, color = "grey30"),
          axis.text.y = element_text(size = 8))
} else {
  p_c <- ggplot() +
    theme_void() +
    annotate("text", 0, 0, label = "scRNA data not available")
}

# ============================================================
# 6. 拼图 + 保存为 FigureS17
# ============================================================
figS17 <- (p_a | p_b | p_c) +
  plot_annotation(
    title = "Depth-matched validation of the 16-gene HGF+ HSC signature",
    subtitle = paste0("Direction of effect is preserved across all three ",
                      "depth-control strategies"),
    tag_levels = "a"
  ) &
  theme(
    plot.title = element_text(face = "bold", size = 12),
    plot.subtitle = element_text(size = 9, color = "grey30"),
    plot.tag = element_text(size = 12, face = "bold")
  )

# ★ 关键：保存为 FigureS17
ggsave("figures/Figure2/FigureS17_depth_matched_validation.pdf",
