# ============================================================
# 1. 数据准备
# ============================================================
gse130 <- readRDS("results/GSE130970_validation.rds")
cat(sprintf("GSE130970: AUC = %.3f (%.3f-%.3f), N = %d, events = %d\n",
            gse130$auc, gse130$ci[1], gse130$ci[3],
