# ============================================================
# P0-1_L1_EPV_analysis.R（EPV/样本量分析）
# ============================================================
rm(list = ls()); gc()
setwd("~/Desktop/sjfx3")
suppressPackageStartupMessages({
  library(tidyverse); library(pROC); library(pwr)
  library(ggplot2); library(patchwork)
})

dir.create("results/revision", showWarnings = FALSE, recursive = TRUE)

# ---------- 1. EPV 计算 ----------
n_events <- 32; n_predictors <- 11
EPV <- n_events / n_predictors
cat(sprintf("EPV = %d / %d = %.2f\n", n_events, n_predictors, EPV))

# ---------- 2. Riley 2020 最小样本量 ----------
Riley_min_n <- function(n_predictors, expected_R2 = 0.15,
                        shrinkage = 0.9, prevalence = 0.44) {
  p <- n_predictors
  n1 <- p / ((shrinkage - 1) * log(1 - expected_R2 / shrinkage))
  n2 <- p / (0.05^2) + 2
  n3 <- 100
  for (i in 1:50) {
    E <- n3 * prevalence
    n3_new <- 1.96^2 * p / (0.1^2 * E * (1 - prevalence)) + 2
    if (abs(n3_new - n3) < 1) break
    n3 <- n3_new
  }
  list(n_total_min = ceiling(max(n1, n2, n3)),
       n_events_min = ceiling(max(n1, n2, n3) * prevalence),
       n1 = ceiling(n1), n2 = ceiling(n2), n3 = ceiling(n3))
}
riley <- Riley_min_n(11)

# ---------- 3. 5000次bootstrap ----------
val <- readRDS("results/GSE49541_validation_unified_zscored.rds")
df <- data.frame(outcome = as.integer(val$group),
                 pred    = as.numeric(val$pred_prob))
df <- df[!is.na(df$outcome), ]

set.seed(123)
n_boot <- 5000
auc_boot <- numeric(n_boot); slope_boot <- numeric(n_boot)
for (i in 1:n_boot) {
  idx <- sample(seq_len(nrow(df)), replace = TRUE)
  d <- df[idx, ]
  if (length(unique(d$outcome)) < 2) next
  tryCatch({
    auc_boot[i] <- as.numeric(pROC::auc(pROC::roc(d$outcome, d$pred, quiet = TRUE)))
    slope_boot[i] <- coef(glm(outcome ~ qlogis(pmin(pmax(pred,1e-10),1-1e-10)),
                              data = d, family = binomial))[2]
  }, error = function(e) NULL)
}

# ---------- 4. 检出力 ----------
power_calc <- pwr.p.test(h = ES.h(0.784, 0.5), sig.level = 0.05,
                         n = nrow(df))$power

# ---------- 5. Leave-one-out ----------
auc_loo <- sapply(1:nrow(df), function(i) {
  d <- df[-i, ]
  as.numeric(pROC::auc(pROC::roc(d$outcome, d$pred, quiet = TRUE)))
})

# ---------- 6. 保存 ----------
saveRDS(list(EPV = EPV, riley = riley,
             auc_boot = auc_boot, slope_boot = slope_boot,
             power = power_calc, auc_loo = auc_loo),
        "results/revision/L1_EPV_analysis.rds")

cat(sprintf("\n✅ P0-1 完成: EPV=%.2f, Riley min_n=%d, power=%.3f\n",
            EPV, riley$n_total_min, power_calc))

# ============================================================
# P0-2_A1_MuSiC_deconvolution.R
# 目的: 用 GSE202379 scRNA-seq 作为参考，对 GSE135251 bulk 做反卷积
#       验证 HSC 比例是否随纤维化分期增加
# 输入: results/GSE202379_seurat_clean.rds
#       results/GSE135251_DEG_results.rds
# 输出: results/revision/A1_deconvolution.rds
#       figures/Figure2/FigureS25_MuSiC_HSC_proportion.pdf/png
# ============================================================
rm(list = ls()); gc()
setwd("~/Desktop/sjfx3")
# 确保 BiocManager 就绪
if (!requireNamespace("BiocManager", quietly = TRUE))
  install.packages("BiocManager", repos = "https://cloud.r-project.org")


# ---------- 0. 提高内存上限 (Mac 可到 64GB，Linux 可更高) ----------
cat(sprintf("默认 mem.maxVSize: %.1f GB\n",
            mem.maxVSize() / 1024^3))

# 尝试提高到 48 GB（根据你的机器调整；Mac 16GB 内存可设 32GB swap）
