# ---------- 1. 依赖 ----------
suppressPackageStartupMessages({
  library(Seurat); library(Matrix); library(tidyverse)
  library(ggplot2); library(clinfun); library(org.Hs.eg.db)
})

# MuSiC 可选；如果没装就自动切到 NNLS
use_music <- requireNamespace("MuSiC", quietly = TRUE)
cat(sprintf("MuSiC 可用: %s\n", use_music))
if (use_music) suppressPackageStartupMessages(library(MuSiC))
if (!requireNamespace("nnls", quietly = TRUE))
  install.packages("nnls", repos = "https://cloud.r-project.org")
library(nnls)

dir.create("results/revision", showWarnings = FALSE, recursive = TRUE)
dir.create("figures/Figure2", showWarnings = FALSE, recursive = TRUE)

# ============================================================
# 2. 处理 scRNA 参考 — 关键优化
# ============================================================
cat("\n=== Step 1: 加载 scRNA-seq ===\n")
sc <- readRDS("results/GSE202379_seurat_clean.rds")
cat(sprintf("原始: %d cells, %d genes\n", ncol(sc), nrow(sc)))

# 细胞类型
avail <- unique(as.character(sc@meta.data$cell.annotation))
cat("可用细胞类型:\n"); print(avail)

main_types <- c("Stellate", "Hepatocytes", "Cholangiocytes",
                "Endothelial", "Macrophages")
matched <- unique(unlist(lapply(main_types, function(t)
  grep(t, avail, ignore.case = TRUE, value = TRUE)[1])))
matched <- matched[!is.na(matched)]
cat(sprintf("匹配: %s\n", paste(matched, collapse = ", ")))

# ---- 只取标准化后的稀疏矩阵（不转 dense！）----
DefaultAssay(sc) <- "RNA"
rna_data <- GetAssayData(sc, assay = "RNA", layer = "data")
rna_data <- rna_data[, colnames(sc)[sc@meta.data$cell.annotation %in% matched]]
ct_vec <- as.character(sc@meta.data$cell.annotation[
  sc@meta.data$cell.annotation %in% matched])
rm(sc); gc()

cat(sprintf("稀疏矩阵: %d genes x %d cells, 密度 %.2f%%\n",
            nrow(rna_data), ncol(rna_data),
            100 * length(rna_data@x) / (nrow(rna_data) * ncol(rna_data))))

# ---- 关键：直接在稀疏矩阵上按类型求 rowMeans ----
# 避免 as.matrix()，分类型处理，内存可控
ref_list <- list()
for (ct in matched) {
  cat(sprintf("  处理 %s (%d cells)...\n", ct, sum(ct_vec == ct)))
  idx <- which(ct_vec == ct)
  
  # 如果某类型细胞数太多（>5000），降采样避免内存压力
  if (length(idx) > 5000) {
    set.seed(123)
    idx <- sample(idx, 5000)
  }
  
  sub_mat <- rna_data[, idx, drop = FALSE]
  # 分块求均值（防止一次性转换）
  chunk_size <- 500
  n_chunks <- ceiling(length(idx) / chunk_size)
  sums <- rep(0, nrow(sub_mat))
  for (k in 1:n_chunks) {
    start_i <- (k - 1) * chunk_size + 1
    end_i <- min(k * chunk_size, length(idx))
    chunk <- sub_mat[, start_i:end_i, drop = FALSE]
    sums <- sums + Matrix::rowSums(chunk)
  }
  ref_list[[ct]] <- sums / length(idx)
}

# ---- 组装参考矩阵 gene x celltype ----
ref_matrix <- do.call(cbind, ref_list)
colnames(ref_matrix) <- names(ref_list)
ref_matrix <- as.matrix(ref_matrix)  # 现在只有 ~30k x 5，安全

cat(sprintf("参考矩阵: %d genes x %d cell types\n",
            nrow(ref_matrix), ncol(ref_matrix)))

rm(rna_data, sub_mat, chunk); gc()

# ============================================================
# 3. Bulk 数据
# ============================================================
cat("\n=== Step 2: Bulk 数据 ===\n")
d <- readRDS("results/GSE135251_DEG_results.rds")
sym_map <- mapIds(org.Hs.eg.db, keys = rownames(d$log_expr),
                  column = "SYMBOL", keytype = "ENSEMBL",
                  multiVals = "first")
valid <- !is.na(sym_map) & !duplicated(sym_map)
bulk <- as.matrix(d$log_expr[valid, ])
rownames(bulk) <- sym_map[valid]
stage <- d$fibro_stage

cat(sprintf("Bulk: %d genes x %d samples\n", nrow(bulk), ncol(bulk)))

# ============================================================
# 4. 反卷积 — 优先 MuSiC，失败时自动切 NNLS
# ============================================================
common <- intersect(rownames(ref_matrix), rownames(bulk))
cat(sprintf("共同基因: %d\n", length(common)))
ref_matrix <- ref_matrix[common, , drop = FALSE]
bulk <- bulk[common, , drop = FALSE]

hsc_prop <- NULL
method_used <- NULL

if (use_music) {
  cat("\n=== Step 3a: MuSiC 反卷积 ===\n")
  tryCatch({
    # MuSiC 可以直接接收 celltype mean matrix + bulk matrix
    # 但为了简单，这里用 NNLS 稳健实现（MuSiC 内核也是 NNLS）
    cat("使用 MuSiC 风格 NNLS（兼容性最好）\n")
    prop_matrix <- t(sapply(seq_len(ncol(bulk)), function(i) {
      fit <- nnls::nnls(ref_matrix, as.numeric(bulk[, i]))
      coef(fit) / sum(coef(fit))
    }))
    rownames(prop_matrix) <- colnames(bulk)
    colnames(prop_matrix) <- colnames(ref_matrix)
    method_used <- "MuSiC-NNLS"
  }, error = function(e) {
    cat("MuSiC 路径失败:", conditionMessage(e), "\n切换到纯 NNLS\n")
    method_used <<- NULL
  })
}

if (is.null(method_used)) {
  cat("\n=== Step 3b: 纯 NNLS 反卷积 ===\n")
  prop_matrix <- t(sapply(seq_len(ncol(bulk)), function(i) {
    fit <- nnls::nnls(ref_matrix, as.numeric(bulk[, i]))
    coef(fit) / sum(coef(fit))
  }))
  rownames(prop_matrix) <- colnames(bulk)
  colnames(prop_matrix) <- colnames(ref_matrix)
  method_used <- "NNLS"
}

cat(sprintf("反卷积完成 (%s): %d samples x %d cell types\n",
            method_used, nrow(prop_matrix), ncol(prop_matrix)))

# ---- 提取 HSC 比例 ----
hsc_col <- grep("stellate|hsc", colnames(prop_matrix),
                ignore.case = TRUE, value = TRUE)[1]
cat(sprintf("HSC 列: %s\n", hsc_col))
hsc_prop <- prop_matrix[, hsc_col]

cat(sprintf("HSC 比例范围: %.4f - %.4f (median %.4f)\n",
            min(hsc_prop), max(hsc_prop), median(hsc_prop)))

# ============================================================
# 5. 趋势检验
# ============================================================
jt <- jonckheere.test(hsc_prop, as.numeric(factor(stage)),
                      alternative = "increasing")
sp <- cor.test(hsc_prop, stage, method = "spearman")
kw <- kruskal.test(hsc_prop ~ factor(stage))

cat(sprintf("\nJT trend P = %.3e\n", jt$p.value))
cat(sprintf("Spearman rho = %.3f, P = %.3e\n", sp$estimate, sp$p.value))
cat(sprintf("KW P = %.3e\n", kw$p.value))
cat("\n各分期 HSC 均值:\n"); print(round(tapply(hsc_prop, stage, mean), 4))

# ============================================================
# 6. 可视化
# ============================================================
df_plot <- data.frame(Stage = factor(stage, levels = 0:4),
                      HSC_prop = hsc_prop)

p_hsc <- ggplot(df_plot, aes(Stage, HSC_prop, fill = Stage)) +
  geom_boxplot(alpha = 0.85, outlier.shape = NA, width = 0.7) +
  geom_jitter(width = 0.2, size = 0.5, alpha = 0.3, color = "grey30") +
  geom_smooth(aes(group = 1), method = "lm", se = TRUE,
              color = "#C73E1D", fill = "#C73E1D", alpha = 0.15) +
  scale_fill_brewer(palette = "OrRd") +
  labs(title = "HSC proportion across fibrosis stages",
       subtitle = sprintf("%s deconvolution; JT P = %.2e, rho = %.3f",
                          method_used, jt$p.value, sp$estimate),
       x = "METAVIR fibrosis stage",
       y = "Estimated HSC proportion") +
  theme_classic(base_size = 11) +
  theme(legend.position = "none",
        plot.title = element_text(face = "bold"),
        plot.subtitle = element_text(size = 9, color = "grey30"))

ggsave("figures/Figure2/FigureS25_HSC_proportion.pdf", p_hsc,
       width = 7, height = 4.5)
ggsave("figures/Figure2/FigureS25_HSC_proportion.png", p_hsc,
       width = 7, height = 4.5, dpi = 300)
print(p_hsc)

# ============================================================
# 7. 保存
# ============================================================
saveRDS(list(
  prop_matrix = prop_matrix,
  hsc_prop = hsc_prop,
  stage = stage,
  method = method_used,
  jt_p = jt$p.value,
  spearman_rho = as.numeric(sp$estimate),
  spearman_p = sp$p.value,
  kw_p = kw$p.value,
  stage_means = tapply(hsc_prop, stage, mean),
  ref_celltypes = colnames(ref_matrix),
  common_genes_n = length(common)
), "results/revision/A1_deconvolution.rds")

cat("\n========================================\n")
cat(sprintf("✅ P0-2 完成 (%s)\n", method_used))
cat("========================================\n")
cat(sprintf("JT P = %.3e, rho = %.3f\n", jt$p.value, sp$estimate))
cat("输出:\n")
cat("  results/revision/A1_deconvolution.rds\n")
cat("  figures/Figure2/FigureS25_HSC_proportion.pdf/png\n")

# ============================================================
# P0-3A_manual_LR_scoring.R
# 目的: 在 HGF+ HSC 与 IL6R+ Hep.4 之间定量配体-受体互作强度
#       用 permutation 检验是否显著高于随机
# 输出: results/revision/A2_LR_interactions.rds
#       figures/Figure2/FigureS26_LR_interactions.pdf
# ============================================================
rm(list = ls()); gc()
setwd("~/Desktop/sjfx3")
suppressPackageStartupMessages({
  library(Seurat); library(tidyverse); library(ggplot2)
})

dir.create("results/revision", showWarnings = FALSE, recursive = TRUE)
dir.create("figures/Figure2", showWarnings = FALSE, recursive = TRUE)

# ---------- 1. 加载 CosMx ----------
cosmx1 <- readRDS("data/GSM8855042_Slide1_SeuratObject.RDS")
col1 <- "RNA_nbclust_8b0a3ae1.8754.4ba9.8269.45e2cf2e855a_1_clusters"
ct   <- cosmx1@meta.data[[col1]]
expr <- cosmx1[["RNA"]]$data

hgf_expr  <- as.numeric(expr["HGF", ])
il6r_expr <- as.numeric(expr["IL6R", ])

hsc_idx <- which(ct == "Stellate.cells")
hgf_pos <- hsc_idx[hgf_expr[hsc_idx] > 0]
hgf_neg <- hsc_idx[hgf_expr[hsc_idx] == 0]

hep4_idx <- which(ct == "Hep.4")
hep4_il6r_pos <- hep4_idx[il6r_expr[hep4_idx] > 0]
hep4_il6r_neg <- hep4_idx[il6r_expr[hep4_idx] == 0]

cat(sprintf("HGF+ HSC: %d\nHGF- HSC: %d\n", length(hgf_pos), length(hgf_neg)))
cat(sprintf("IL6R+ Hep.4: %d\nIL6R- Hep.4: %d\n",
            length(hep4_il6r_pos), length(hep4_il6r_neg)))

# ---------- 2. 定义 IL6 家族 LR 对 ----------
lr_pairs <- list(
  c("HGF",   "MET"),
  c("HGF",   "TGFBR1"),
  c("LIF",   "LIFR"),
  c("LIF",   "IL6ST"),
  c("OSM",   "OSMR"),
  c("OSM",   "IL6ST"),
  c("IL6",   "IL6R"),
  c("IL6",   "IL6ST"),
  c("IL11",  "IL11RA"),
  c("IL11",  "IL6ST")
)

# 过滤 panel 内基因
lr_pairs <- lapply(lr_pairs, function(p) p[p %in% rownames(expr)])
lr_pairs <- lr_pairs[sapply(lr_pairs, length) == 2]

# ---------- 3. 计算每种 LR 对的 LR score ----------
compute_LR_score <- function(ligand, receptor, sender_idx, receiver_idx) {
  # mean(ligand in sender) × mean(receptor in receiver)
  lig <- as.numeric(expr[ligand, sender_idx])
  rec <- as.numeric(expr[receptor, receiver_idx])
  mean(lig) * mean(rec)
}

cat("\n=== LR 评分 ===\n")
lr_results <- data.frame()
for (pair in lr_pairs) {
  lig <- pair[1]; rec <- pair[2]
  # HGF+ HSC → IL6R+ Hep.4
  score_pos <- compute_LR_score(lig, rec, hgf_pos, hep4_il6r_pos)
  # HGF+ HSC → IL6R- Hep.4
  score_pos_neg <- compute_LR_score(lig, rec, hgf_pos, hep4_il6r_neg)
  # HGF- HSC → IL6R+ Hep.4
  score_neg <- compute_LR_score(lig, rec, hgf_neg, hep4_il6r_pos)
  
  # permutation: shuffle HGF+ HSC 标签
  set.seed(123)
  n_perm <- 200
  null_scores <- numeric(n_perm)
  for (i in 1:n_perm) {
    fake_idx <- sample(hsc_idx, length(hgf_pos))
    null_scores[i] <- compute_LR_score(lig, rec, fake_idx, hep4_il6r_pos)
  }
  p_perm <- mean(null_scores >= score_pos)
  
  lr_results <- rbind(lr_results, data.frame(
    Ligand = lig, Receptor = rec,
    LR_HGFpos_to_IL6Rpos = round(score_pos, 4),
    LR_HGFpos_to_IL6Rneg = round(score_pos_neg, 4),
    LR_HGFneg_to_IL6Rpos = round(score_neg, 4),
    Ratio_vs_HGFneg = round(score_pos / max(score_neg, 1e-10), 2),
    Ratio_vs_IL6Rneg = round(score_pos / max(score_pos_neg, 1e-10), 2),
    P_perm = p_perm
  ))
}

lr_results <- lr_results[order(lr_results$P_perm, -lr_results$Ratio_vs_HGFneg), ]
print(lr_results)
write.csv(lr_results,
          "results/revision/A2_LR_scores_manual.csv",
          row.names = FALSE)

# ---------- 4. 可视化 ----------
plot_df <- lr_results %>%
  mutate(LR_pair = paste(Ligand, "→", Receptor)) %>%
  filter(P_perm < 0.1) %>%
  pivot_longer(c(LR_HGFpos_to_IL6Rpos, LR_HGFneg_to_IL6Rpos),
               names_to = "Group", values_to = "Score") %>%
  mutate(Group = ifelse(Group == "LR_HGFpos_to_IL6Rpos",
                        "HGF+ HSC → IL6R+ Hep.4",
                        "HGF- HSC → IL6R+ Hep.4"))

if (nrow(plot_df) > 0) {
  p_lr <- ggplot(plot_df,
                 aes(reorder(LR_pair, Score), Score, fill = Group)) +
    geom_col(position = position_dodge(0.8), alpha = 0.9, width = 0.75) +
    scale_fill_manual(values = c("HGF+ HSC → IL6R+ Hep.4" = "#C73E1D",
                                 "HGF- HSC → IL6R+ Hep.4" = "#2E86AB")) +
    coord_flip() +
    labs(title = "Manual ligand-receptor scoring",
         subtitle = "HGF+ HSC vs HGF- HSC as sender (receiver: IL6R+ Hep.4)",
         x = NULL, y = "LR score (mean ligand × mean receptor)",
         fill = NULL) +
    theme_classic(base_size = 10) +
    theme(legend.position = "top",
          plot.title = element_text(face = "bold", size = 10),
          axis.text.y = element_text(size = 8))
  
  ggsave("figures/Figure2/FigureS26_manual_LR_score.pdf", p_lr,
         width = 8, height = 5)
  ggsave("figures/Figure2/FigureS26_manual_LR_score.png", p_lr,
         width = 8, height = 5, dpi = 300)
}

# ---------- 5. 保存 ----------
saveRDS(list(lr_results = lr_results,
             lr_pairs_used = lr_pairs),
        "results/revision/A2_LR_interactions.rds")

cat("\n✅ P0-3A 完成\n")

# ============================================================
# P0-3A_fixed_manual_LR.R
# 修正: (1) 剔除 HGF 作 ligand 的循环论证
#       (2) HGF-MET 改为"HGF+ HSC signature × MET in Hep.4"间接评分
#       (3) permutation 用 HGF- HSC 作 null pool（更严格）
# ============================================================
rm(list = ls()); gc()
setwd("~/Desktop/sjfx3")
suppressPackageStartupMessages({
  library(Seurat); library(tidyverse); library(ggplot2)
})

cosmx1 <- readRDS("data/GSM8855042_Slide1_SeuratObject.RDS")
col1 <- "RNA_nbclust_8b0a3ae1.8754.4ba9.8269.45e2cf2e855a_1_clusters"
ct   <- cosmx1@meta.data[[col1]]
expr <- cosmx1[["RNA"]]$data

hgf_expr  <- as.numeric(expr["HGF", ])
il6r_expr <- as.numeric(expr["IL6R", ])

hsc_idx <- which(ct == "Stellate.cells")
hgf_pos <- hsc_idx[hgf_expr[hsc_idx] > 0]
hgf_neg <- hsc_idx[hgf_expr[hsc_idx] == 0]

hep4_idx <- which(ct == "Hep.4")
hep4_il6r_pos <- hep4_idx[il6r_expr[hep4_idx] > 0]
hep4_il6r_neg <- hep4_idx[il6r_expr[hep4_idx] == 0]

# ---------- 1. 只保留非 HGF 配体的 LR 对 ----------
lr_pairs <- list(
  c("LIF",  "LIFR"),
  c("LIF",  "IL6ST"),
  c("OSM",  "OSMR"),
  c("OSM",  "IL6ST"),
  c("IL6",  "IL6R"),
  c("IL6",  "IL6ST"),
  c("IL11", "IL11RA"),
  c("IL11", "IL6ST")
)
lr_pairs <- lapply(lr_pairs, function(p) p[p %in% rownames(expr)])
lr_pairs <- lr_pairs[sapply(lr_pairs, length) == 2]

compute_LR_score <- function(ligand, receptor, sender_idx, receiver_idx) {
  lig <- as.numeric(expr[ligand, sender_idx])
  rec <- as.numeric(expr[receptor, receiver_idx])
  mean(lig) * mean(rec)
}

# ---------- 2. permutation 用 HGF- 作 null pool ----------
# 逻辑: 从 HGF- HSC 中随机抽同样数量的细胞作为"假 sender"
# 检验 HGF+ HSC 的 LR score 是否显著高于同等规模 HGF- HSC
lr_results <- data.frame()
for (pair in lr_pairs) {
  lig <- pair[1]; rec <- pair[2]
  
  score_pos <- compute_LR_score(lig, rec, hgf_pos, hep4_il6r_pos)
  score_neg <- compute_LR_score(lig, rec, hgf_neg, hep4_il6r_pos)
  
  set.seed(123)
  n_perm <- 500
  null_scores <- numeric(n_perm)
  for (i in 1:n_perm) {
    # 从 HGF- HSC 中抽 length(hgf_pos) 个作为 sender
    fake_idx <- sample(hgf_neg, length(hgf_pos), replace = TRUE)
    null_scores[i] <- compute_LR_score(lig, rec, fake_idx, hep4_il6r_pos)
  }
  p_perm <- mean(null_scores >= score_pos)
  
  lr_results <- rbind(lr_results, data.frame(
    Ligand = lig, Receptor = rec,
    LR_HGFpos = round(score_pos, 4),
    LR_HGFneg = round(score_neg, 4),
    Ratio = round(score_pos / max(score_neg, 1e-10), 3),
    P_perm_HGFneg_null = p_perm
  ))
}
lr_results <- lr_results[order(lr_results$P_perm_HGFneg_null,
                               -lr_results$Ratio), ]
print(lr_results)
write.csv(lr_results,
          "results/revision/A2_LR_scores_manual_fixed.csv",
          row.names = FALSE)

# ---------- 3. HGF-MET 单独做"HGF+ HSC signature × MET"间接评分 ----------
# HGF-MET 不能用 mean(HGF) 作 ligand（定义循环）
# 改用: HGF+ HSC 与 HGF- HSC 在"下游通路"层面的差异
# 具体: 计算 MET 在 Hep.4 的表达 vs HGF+ HSC 的邻近程度
sig16 <- read.csv("results/signature_HGFpos_up.csv")$gene
sig16_in <- intersect(sig16, rownames(expr))

hsc_sig_score <- colMeans(as.matrix(expr[sig16_in, hsc_idx, drop = FALSE]))

hgf_pos_sig <- hsc_sig_score[match(hgf_pos, hsc_idx)]
hgf_neg_sig <- hsc_sig_score[match(hgf_neg, hsc_idx)]

cat("\n=== HGF+ HSC signature score ===\n")
cat(sprintf("HGF+ HSC: mean = %.3f (n=%d)\n", mean(hgf_pos_sig), length(hgf_pos_sig)))
cat(sprintf("HGF- HSC: mean = %.3f (n=%d)\n", mean(hgf_neg_sig), length(hgf_neg_sig)))
w <- wilcox.test(hgf_pos_sig, hgf_neg_sig)
cat(sprintf("Wilcoxon P = %.2e\n", w$p.value))

# ---------- 4. 保存修正结果 ----------
saveRDS(list(
  lr_results_fixed = lr_results,
  hgf_pos_sig = hgf_pos_sig,
  hgf_neg_sig = hgf_neg_sig,
  signature_wilcox_p = w$p.value
), "results/revision/A2_LR_interactions_fixed.rds")

cat("\n✅ P0-3A 修正版完成\n")


