# ---------- 3. 获取 PWM ----------
get_pwm <- function(tf_name) {
  tryCatch({
    getMatrixSet(JASPAR2020,
                 opts = list(species = 9606,
                             name = tf_name,
                             all_versions = FALSE))
  }, error = function(e) {
    cat(sprintf("⚠️ %s PWM 获取失败: %s\n", tf_name, conditionMessage(e)))
    NULL
  })
}

# ---------- 4. Motif 扫描函数 ----------
scan_tf <- function(pwm_list, seq, tf_name, min_score = "80%") {
  if (is.null(pwm_list) || length(pwm_list) == 0) return(NULL)
  hits <- list()
  for (i in seq_along(pwm_list)) {
    h <- tryCatch(
      searchSeq(pwm_list[[i]], seq,
                seqname = "HGF_promoter",
                min.score = min_score,
                strand = "*"),
      error = function(e) NULL
    )
    if (!is.null(h) && length(h) > 0) {
      df <- as.data.frame(h)
      df$TF <- tf_name
      df$Motif_name <- pwm_list[[i]]@name
      hits[[i]] <- df
    }
  }
  if (length(hits) == 0) return(NULL)
  do.call(rbind, hits)
}

# ---------- 5. 扫描目标 TF ----------
target_tfs <- c("TFAP2A", "TP53", "TFAP2C", "TFAP2B", "SP3", "STAT1")

hits_all <- list()
for (tf in target_tfs) {
  cat(sprintf("Scanning %s...\n", tf))
  pwm <- get_pwm(tf)
  hits_all[[tf]] <- scan_tf(pwm, hgf_seq, tf, min_score = "80%")
}

hits_df <- do.call(rbind, hits_all)

# 如果 80% 无 hits，降到 75%
if (is.null(hits_df) || nrow(hits_df) == 0) {
  cat("\n⚠️ 80% 阈值无 hits，降低到 75%\n")
  for (tf in target_tfs) {
    pwm <- get_pwm(tf)
    hits_all[[tf]] <- scan_tf(pwm, hgf_seq, tf, min_score = "75%")
  }
  hits_df <- do.call(rbind, hits_all)
}

# ---------- 6. 输出 summary ----------
if (!is.null(hits_df) && nrow(hits_df) > 0) {
  cat("\n=== Motif hits ===\n")
  hit_summary <- hits_df %>%
    group_by(TF) %>%
    summarise(n_hits = n(),
              min_pval = signif(min(p.value), 3),
              max_score = round(max(absScore), 1),
              .groups = "drop")
  print(hit_summary)
  write.csv(hits_df,
            "results/revision/B3_motif_hits_full.csv",
            row.names = FALSE)
} else {
  cat("\n❌ 75% 阈值下仍无 hits\n")
}

# ---------- 7. 可视化 ----------
if (!is.null(hits_df) && nrow(hits_df) > 0) {
  TSS <- 81700000
  hits_df$RelPos <- start(hits_df) + 81698000 - TSS
  hits_df$TF <- factor(hits_df$TF, levels = target_tfs)
  
  p_motif <- ggplot(hits_df, aes(RelPos / 1000, absScore, color = TF)) +
    geom_segment(aes(xend = RelPos / 1000, yend = 0),
                 linewidth = 1.2, alpha = 0.7) +
    geom_point(size = 3, alpha = 0.9) +
    geom_vline(xintercept = 0, linetype = "dashed",
               color = "grey40") +
    annotate("text", x = 0, y = max(hits_df$absScore) * 0.95,
             label = "TSS", color = "grey40", size = 3, hjust = -0.1) +
    scale_color_manual(values = c(
      "TFAP2A" = "#C73E1D", "TP53" = "#2E86AB",
      "TFAP2C" = "#F18F01", "TFAP2B" = "#3B8EA5",
      "SP3" = "#A23B72", "STAT1" = "#7F7F7F"
    )) +
    labs(title = "JASPAR motif hits in HGF promoter (hg38)",
         subtitle = sprintf("Chr7:81,698-81,702 kb; %d hits total",
                            nrow(hits_df)),
         x = "Position relative to TSS (kb)",
         y = "Motif score", color = "TF") +
    theme_classic(base_size = 10) +
    theme(plot.title = element_text(face = "bold"),
          legend.position = "top")
  
  ggsave("figures/Figure2/FigureS29_TF_motif_HGF.pdf", p_motif,
         width = 9, height = 4.5)
  ggsave("figures/Figure2/FigureS29_TF_motif_HGF.png", p_motif,
         width = 9, height = 4.5, dpi = 300)
  print(p_motif)
}

# ---------- 8. 保存 ----------
