# ---------- 3. 用极低阈值探测（60%）----------
cat("\n=== 60% 阈值探测 ===\n")
probe_hits <- function(tf, min_score) {
  pwm <- getMatrixSet(JASPAR2020,
                      opts = list(species = 9606, name = tf,
                                  all_versions = FALSE))
  if (length(pwm) == 0) return(0)
  total <- 0
  for (i in seq_along(pwm)) {
    h <- tryCatch(
      searchSeq(pwm[[i]], hgf_seq, seqname = "HGF_promoter",
                min.score = min_score, strand = "*"),
      error = function(e) NULL
    )
    if (!is.null(h)) total <- total + length(h)
  }
  total
}

thresholds <- c("90%", "85%", "80%", "75%", "70%", "65%", "60%")
probe_tab <- data.frame()
for (tf in c("TFAP2A", "TP53", "TFAP2C", "TFAP2B", "SP3", "STAT1")) {
  row <- sapply(thresholds, function(th) probe_hits(tf, th))
  probe_tab <- rbind(probe_tab,
                     data.frame(TF = tf, t(row), check.names = FALSE))
}
colnames(probe_tab) <- c("TF", paste0("thr_", gsub("%", "", thresholds)))
print(probe_tab)
write.csv(probe_tab, "results/revision/B3_threshold_probe.csv",
          row.names = FALSE)

