cat("\n=== 反向互补序列 (60% 阈值) ===\n")
probe_rc <- function(tf, seq) {
  pwm <- getMatrixSet(JASPAR2020,
                      opts = list(species = 9606, name = tf,
                                  all_versions = FALSE))
  if (length(pwm) == 0) return(0)
  total <- 0
