    h <- tryCatch(
      searchSeq(pwm[[i]], seq, seqname = "HGF_promoter_rc",
                min.score = "60%", strand = "*"),
      error = function(e) NULL
    )
    if (!is.null(h)) total <- total + length(h)
  }
  total
}
for (tf in c("TFAP2A", "TP53")) {
