# ---------- 1. 下载 HGF 启动子 ----------
ucsc_url <- paste0(
  "https://api.genome.ucsc.edu/getData/sequence?",
  "genome=hg38&chrom=chr7&start=81698000&end=81702000"
)
res <- GET(ucsc_url, timeout(30))
hgf_dna <- toupper(fromJSON(content(res, "text", encoding = "UTF-8"))$dna)
cat(sprintf("HGF promoter: %d bp\n", nchar(hgf_dna)))

# ---------- 2. 从 PFMatrix 手工构造 PWM 数值矩阵 ----------
build_pwm_matrix <- function(tf_name) {
  pwm_pf <- tryCatch(
    getMatrixSet(JASPAR2020,
                 opts = list(species = 9606, name = tf_name,
                             all_versions = FALSE))[[1]],
    error = function(e) NULL
  )
  if (is.null(pwm_pf)) return(NULL)
  
  # 用官方访问器获取计数矩阵
  mat <- Matrix(pwm_pf)              # PFM: A/C/G/T x 位置
  cat(sprintf("  %s: PFM %d x %d, 行名: %s\n",
              tf_name, nrow(mat), ncol(mat),
              paste(rownames(mat), collapse = ",")))
  
  # 确保 4 行都是 A/C/G/T
  required <- c("A", "C", "G", "T")
  if (!all(required %in% rownames(mat))) {
    # 补齐缺失的碱基（某些矩阵可能只列了 4 行但顺序不同）
    mat_full <- matrix(0.25, 4, ncol(mat),
                       dimnames = list(required, colnames(mat)))
    for (r in intersect(required, rownames(mat))) {
      mat_full[r, ] <- mat[r, ]
    }
    mat <- mat_full
  }
  mat <- mat[required, , drop = FALSE]   # 强制按 A/C/G/T 排序
  
  # 加伪计数避免除零
  mat <- mat + 0.25
  
  # 归一化为概率矩阵（每列和 = 1）
  pwm_num <- sweep(mat, 2, colSums(mat), "/")
  
  return(pwm_num)
}

# ---------- 3. 测试 TP53 ----------
cat("\n=== 构造 TP53 PWM ===\n")
pwm_tp53 <- build_pwm_matrix("TP53")
print(round(pwm_tp53, 3))

# ---------- 4. matchPWM ----------
cat("\n=== matchPWM 扫描 ===\n")
hgf_str <- DNAString(hgf_dna)
hgf_rc  <- reverseComplement(hgf_str)

hits_fwd <- matchPWM(pwm_tp53, hgf_str,
                     min.score = "60%", with.score = TRUE)
cat(sprintf("HGF + strand @60%%: %d hits\n", length(hits_fwd)))

hits_rc  <- matchPWM(pwm_tp53, hgf_rc,
                     min.score = "60%", with.score = TRUE)
cat(sprintf("HGF - strand @60%%: %d hits\n", length(hits_rc)))

# 随机对照
set.seed(123)
random_seq <- DNAString(paste(sample(c("A","C","G","T"), 4000,
                                     replace = TRUE), collapse = ""))
hits_random <- matchPWM(pwm_tp53, random_seq,
                        min.score = "60%", with.score = TRUE)
cat(sprintf("Random seq @60%%:  %d hits\n", length(hits_random)))

# ---------- 5. 判定 ----------
cat("\n=== 判定 ===\n")
if (length(hits_random) == 0) {
  cat("❌ Random 也 0 hits → matchPWM 环境有问题\n")
} else if (length(hits_fwd) + length(hits_rc) == 0) {
  cat("⚠️ Random 有 hits 但 HGF 无 → 生物学结果\n")
} else {
  cat(sprintf("✅ HGF 有 hits (fwd=%d, rc=%d)\n",
              length(hits_fwd), length(hits_rc)))
}

# ---------- 6. 批量扫描所有 TF ----------
cat("\n\n=== 批量扫描全部 TF ===\n")
target_tfs <- c("TFAP2A", "TP53", "TFAP2C", "TFAP2B", "SP3", "STAT1")
thresholds <- c("80%", "70%", "60%", "50%")

scan_tab <- data.frame()
for (tf in target_tfs) {
  pwm_num <- build_pwm_matrix(tf)
  if (is.null(pwm_num)) {
    cat(sprintf("%-8s: PWM 构造失败\n", tf))
    next
  }
  
  row <- data.frame(TF = tf)
  for (th in thresholds) {
    n_fwd <- tryCatch(
      length(matchPWM(pwm_num, hgf_str, min.score = th,
                      with.score = FALSE)),
      error = function(e) NA
    )
    n_rc <- tryCatch(
      length(matchPWM(pwm_num, hgf_rc, min.score = th,
                      with.score = FALSE)),
      error = function(e) NA
    )
    row[[paste0("t", gsub("%", "", th), "_fwd")]] <- n_fwd
    row[[paste0("t", gsub("%", "", th), "_rc")]]  <- n_rc
    row[[paste0("t", gsub("%", "", th), "_tot")]] <- n_fwd + n_rc
  }
  scan_tab <- rbind(scan_tab, row)
}

print(scan_tab)
write.csv(scan_tab,
          "results/revision/B3_matchPWM_scan.csv",
          row.names = FALSE)

cat("\n✅ 诊断完成\n")
