# ---------- 2. PWM 构造（复用之前的函数） ----------
build_pwm_matrix <- function(tf_name) {
  pwm_pf <- tryCatch(
    getMatrixSet(JASPAR2020,
                 opts = list(species = 9606, name = tf_name,
                             all_versions = FALSE))[[1]],
    error = function(e) NULL
  )
  if (is.null(pwm_pf)) return(NULL)
  mat <- Matrix(pwm_pf)
  required <- c("A", "C", "G", "T")
  if (!all(required %in% rownames(mat))) {
    mat_full <- matrix(0.25, 4, ncol(mat),
                       dimnames = list(required, colnames(mat)))
    for (r in intersect(required, rownames(mat))) {
      mat_full[r, ] <- mat[r, ]
    }
    mat <- mat_full
  }
  mat <- mat[required, , drop = FALSE]
  mat <- mat + 0.25
  pwm_num <- sweep(mat, 2, colSums(mat), "/")
  return(pwm_num)
}

# ---------- 3. 生成 100 条随机序列作为背景 ----------
set.seed(123)
n_random <- 100
random_seqs <- lapply(1:n_random, function(i) {
  DNAString(paste(sample(c("A","C","G","T"), nchar(hgf_dna),
                         replace = TRUE), collapse = ""))
})

# ---------- 4. 每个 TF × 每个阈值 做富集分析 ----------
# 用 Fisher 精确检验：
#   observed = HGF hits (fwd + rc)
#   expected = mean random hits
#   用矩阵: 2x2 = [HGF hits, HGF non-hits; Random mean hits, Random non-hits]

target_tfs <- c("TFAP2A", "TP53", "TFAP2C", "TFAP2B", "SP3", "STAT1")
thresholds <- c("80%", "75%", "70%", "65%", "60%")
seq_len <- nchar(hgf_dna)

enrich_tab <- data.frame()

for (tf in target_tfs) {
  cat(sprintf("\n=== %s ===\n", tf))
  pwm_num <- build_pwm_matrix(tf)
  if (is.null(pwm_num)) next
  
  for (th in thresholds) {
    # HGF 观察值
    n_hgf_fwd <- tryCatch(
      length(matchPWM(pwm_num, hgf_str, min.score = th,
                      with.score = FALSE)),
      error = function(e) 0
    )
    n_hgf_rc <- tryCatch(
      length(matchPWM(pwm_num, hgf_rc, min.score = th,
                      with.score = FALSE)),
      error = function(e) 0
    )
    n_hgf <- n_hgf_fwd + n_hgf_rc
    
    # 随机背景：100 条随机序列
    n_random_hits <- sapply(random_seqs, function(rs) {
      n_fwd <- length(matchPWM(pwm_num, rs, min.score = th,
                               with.score = FALSE))
      n_rc <- length(matchPWM(pwm_num, reverseComplement(rs),
                              min.score = th, with.score = FALSE))
      n_fwd + n_rc
    })
    
    # Fisher 检验：HGF vs 随机
    # 用观察值 vs 随机均值（作为期望）
    mean_random <- mean(n_random_hits)
    # 因为 HGF 是 1 条序列，random 是 100 条，做单样本检验
    # 更合理：把 HGF 的 hits 数与随机分布比较，用经验 p 值
    p_emp <- (sum(n_random_hits >= n_hgf) + 1) / (n_random + 1)
    
    # 富集倍数
    fold <- n_hgf / max(mean_random, 0.01)
    
    enrich_tab <- rbind(enrich_tab, data.frame(
      TF = tf, Threshold = th,
      HGF_hits = n_hgf,
      Random_mean = round(mean_random, 1),
      Random_max = max(n_random_hits),
      Fold_enrichment = round(fold, 2),
      P_empirical = round(p_emp, 4)
    ))
  }
}

print(enrich_tab)
write.csv(enrich_tab,
          "results/revision/B3_motif_enrichment.csv",
          row.names = FALSE)

# ---------- 5. 筛选显著富集的 TF ----------
cat("\n\n=== 显著富集 (P < 0.05) ===\n")
sig_enrich <- enrich_tab %>%
  filter(P_empirical < 0.05) %>%
  arrange(P_empirical)
print(sig_enrich)

# ---------- 6. 选择最佳阈值 ----------
# 找出每个 TF 满足以下条件的最高阈值：
#   - HGF_hits >= 2（至少 2 个位点才可信）
#   - Fold_enrichment >= 2（至少 2 倍富集）
#   - P_empirical < 0.05
best_thresholds <- enrich_tab %>%
  filter(HGF_hits >= 2,
         Fold_enrichment >= 2,
         P_empirical < 0.05) %>%
  group_by(TF) %>%
  slice_max(order_by = as.numeric(gsub("%", "", Threshold)),
            n = 1) %>%
  ungroup()

cat("\n=== 最佳阈值 ===\n")
print(best_thresholds)
write.csv(best_thresholds,
          "results/revision/B3_best_thresholds.csv",
          row.names = FALSE)

# ---------- 7. 可视化：热图 ----------
plot_df <- enrich_tab %>%
  mutate(Threshold = factor(Threshold,
                            levels = c("80%", "75%", "70%", "65%", "60%")))

p_heat <- ggplot(plot_df, aes(Threshold, TF, fill = -log10(P_empirical))) +
  geom_tile(color = "white") +
  geom_text(aes(label = sprintf("%d\n(%.1fx)",
                                HGF_hits, Fold_enrichment)),
            size = 2.5, color = "black") +
  scale_fill_gradient(low = "white", high = "#C73E1D",
                      name = "-log10(P)") +
  labs(title = "Motif enrichment in HGF promoter",
       subtitle = "Numbers = HGF hits (fold enrichment vs 100 random sequences)",
       x = "Threshold", y = NULL) +
  theme_minimal(base_size = 10) +
  theme(plot.title = element_text(face = "bold"),
        panel.grid = element_blank())

ggsave("figures/Figure2/FigureS29_motif_enrichment_heatmap.pdf", p_heat,
       width = 8, height = 4)
ggsave("figures/Figure2/FigureS29_motif_enrichment_heatmap.png", p_heat,
       width = 8, height = 4, dpi = 300)
print(p_heat)

# ---------- 8. 保存 ----------
saveRDS(list(
  enrich_tab = enrich_tab,
  sig_enrich = sig_enrich,
  best_thresholds = best_thresholds
), "results/revision/B3_motif_background.rds")

cat("\n✅ P1-5 背景校正完成\n")

