# ---------- Bulk 数据 ----------
d <- readRDS("results/GSE135251_DEG_results.rds")
sym_map <- mapIds(org.Hs.eg.db, keys = rownames(d$log_expr),
                  column = "SYMBOL", keytype = "ENSEMBL",
                  multiVals = "first")
valid <- !is.na(sym_map) & !duplicated(sym_map)
log_expr <- as.matrix(d$log_expr[valid, ])
rownames(log_expr) <- sym_map[valid]
stage <- d$fibro_stage

cat(sprintf("Bulk: %d genes x %d samples\n",
            nrow(log_expr), ncol(log_expr)))

for (nm in names(pathway_list)) {
  genes_in <- intersect(pathway_list[[nm]], rownames(log_expr))
  cat(sprintf("%-20s: %d / %d\n",
              nm, length(genes_in), length(pathway_list[[nm]])))
  pathway_list[[nm]] <- genes_in
}
pathway_list <- pathway_list[sapply(pathway_list, length) >= 5]

# ---------- GSVA ----------
gsva_par <- gsvaParam(
  exprData = log_expr,
  geneSets = pathway_list,
  kcdf = "Gaussian"          # 你的数据是 log 后的连续值，保持 Gaussian 即可
)

# 2. 运行 GSVA
cat("\nRunning GSVA...\n")
gsva_res <- gsva(gsva_par, verbose = FALSE)
# ---------- 趋势检验 ----------
trend_results <- map_dfr(rownames(gsva_res), function(pw) {
  x <- as.numeric(gsva_res[pw, ])
  jt <- jonckheere.test(x, as.numeric(factor(stage)),
                        alternative = "increasing")
  sp <- cor.test(x, stage, method = "spearman")
  kw <- kruskal.test(x ~ factor(stage))
  data.frame(
    Pathway = pw,
    JT_P = jt$p.value,
    KW_P = kw$p.value,
    Spearman_rho = round(as.numeric(sp$estimate), 3),
    Spearman_P = sp$p.value,
    Mean_F0 = round(mean(x[stage == 0]), 3),
    Mean_F4 = round(mean(x[stage == 4]), 3)
  )
}) %>% arrange(JT_P)

print(trend_results)
write.csv(trend_results,
          "results/revision/B1_GSVA_pathway_trends.csv",
          row.names = FALSE)

# ---------- 可视化 ----------
