  mutate(Stage = stage) %>%
  pivot_longer(-Stage, names_to = "Pathway", values_to = "Activity") %>%
  mutate(Pathway = gsub("_", " ", Pathway))

plot_df$Pathway <- factor(plot_df$Pathway, levels = unique(plot_df$Pathway))

