  geom_boxplot(alpha = 0.75, outlier.shape = NA, width = 0.7) +
  geom_smooth(aes(group = 1), method = "lm", se = TRUE,
              color = "#C73E1D", fill = "#C73E1D", alpha = 0.12) +
  facet_wrap(~ Pathway, scales = "free_y", ncol = 3) +
  scale_fill_brewer(palette = "OrRd") +
  labs(title = "GSVA pathway activity across fibrosis stages (GSE135251)",
       subtitle = "Curated pathway gene sets; Jonckheere-Terpstra trend test",
       x = "METAVIR fibrosis stage", y = "GSVA score") +
  theme_classic(base_size = 9) +
  theme(legend.position = "none",
        plot.title = element_text(face = "bold", size = 10),
        plot.subtitle = element_text(size = 8, color = "grey30"),
        strip.text = element_text(face = "bold", size = 8))

