# ============================================================
# P1-4A_coexpression_network.R（Seurat v5 修复版）
# ============================================================
rm(list = ls()); gc()
setwd("~/Desktop/sjfx3")
suppressPackageStartupMessages({
  library(Seurat); library(tidyverse); library(ggplot2)
  library(Matrix); library(igraph); library(ggraph)
})

dir.create("results/revision", showWarnings = FALSE, recursive = TRUE)
dir.create("figures/Figure2", showWarnings = FALSE, recursive = TRUE)

# ---------- 1. HSC 子集 ----------
sc <- readRDS("results/GSE202379_seurat_clean.rds")
avail <- unique(as.character(sc@meta.data$cell.annotation))
stella_type <- grep("stellate|hsc", avail, ignore.case = TRUE, value = TRUE)[1]
cat(sprintf("Stellate 类型: %s\n", stella_type))

sc <- subset(sc, subset = cell.annotation == stella_type)
DefaultAssay(sc) <- "RNA"

# 检查是否需要标准化
rna_data <- GetAssayData(sc, assay = "RNA", layer = "data")
cat(sprintf("RNA data max: %.2f\n", max(rna_data)))
if (max(rna_data) > 50) {
  sc <- NormalizeData(sc, verbose = FALSE)
  rna_data <- GetAssayData(sc, assay = "RNA", layer = "data")
}

# ---------- 提取表达矩阵（Seurat v5 正确写法） ----------
expr <- GetAssayData(sc, assay = "RNA", layer = "data")
cat(sprintf("提取矩阵: %d genes x %d cells\n", nrow(expr), ncol(expr)))

keep <- Matrix::rowSums(expr > 0) > ncol(expr) * 0.1
expr <- expr[keep, ]
cat(sprintf("过滤低表达后: %d genes x %d cells\n", nrow(expr), ncol(expr)))
rm(sc); gc()

# ---------- 2. 高变基因子集 ----------
if (nrow(expr) > 3000) {
  gene_mean <- Matrix::rowMeans(expr)
  gene_sq_mean <- Matrix::rowMeans(expr^2)
  gene_var <- gene_sq_mean - gene_mean^2
  top_genes <- names(sort(gene_var, decreasing = TRUE))[1:2500]
  sig11 <- c("EYA2","FERMT1","PYROXD2","EPB41L4A","CHI3L1",
             "CNKSR1","ILDR1","GSN","TMPRSS3","ESRRG","SULF2")
  extra <- c("HGF", intersect(sig11, rownames(expr)))
  top_genes <- unique(c(extra, top_genes))
  expr_sub <- expr[top_genes, ]
} else {
  expr_sub <- expr
}
rm(expr); gc()

expr_dense <- as.matrix(expr_sub)
cat(sprintf("高变基因子集: %d x %d\n", nrow(expr_dense), ncol(expr_dense)))
rm(expr_sub); gc()

# ---------- 3. 基因-基因 Spearman 相关 ----------
cat("Computing gene-gene correlations...\n")
cor_mat <- cor(t(expr_dense), method = "spearman")
cor_mat[cor_mat < 0] <- 0
diag(cor_mat) <- 0

# ---------- 4. HGF 的网络邻居 ----------
if (!("HGF" %in% rownames(cor_mat))) stop("HGF 不在高变基因中")

hgf_cor <- cor_mat["HGF", ]
hgf_neighbors <- names(hgf_cor)[abs(hgf_cor) > 0.3]
hgf_neighbors <- setdiff(hgf_neighbors, "HGF")

cat(sprintf("\nHGF 共表达邻居 (|r| > 0.3): %d\n", length(hgf_neighbors)))
cat("Top 20 HGF 邻居:\n")
print(head(sort(abs(hgf_cor), decreasing = TRUE), 20))

# ---------- 5. 与 11-gene signature 交集 ----------
sig11 <- c("EYA2","FERMT1","PYROXD2","EPB41L4A","CHI3L1",
           "CNKSR1","ILDR1","GSN","TMPRSS3","ESRRG","SULF2")
overlap <- intersect(sig11, hgf_neighbors)
cat(sprintf("\n11-gene 与 HGF 邻居交集: %d / 11\n", length(overlap)))
if (length(overlap) > 0) print(overlap)

n_total <- nrow(cor_mat)
n_neighbors <- length(hgf_neighbors)
n_sig11 <- length(intersect(sig11, rownames(cor_mat)))
n_overlap <- length(overlap)

if (n_neighbors > 0 && n_sig11 > 0) {
  ft <- fisher.test(matrix(c(
    n_overlap, n_neighbors - n_overlap,
    n_sig11 - n_overlap,
    n_total - n_neighbors - n_sig11 + n_overlap
  ), nrow = 2))
  cat(sprintf("Fisher 富集检验: OR = %.2f, P = %.3e\n",
              ft$estimate, ft$p.value))
} else {
  ft <- list(estimate = NA, p.value = NA)
}

# ---------- 6. 网络构建与可视化 ----------
top_neighbors <- names(sort(abs(hgf_cor), decreasing = TRUE))[1:50]
nodes <- unique(c("HGF", top_neighbors, sig11))

# ★ 关键修复：只保留 cor_mat 里存在的基因
nodes <- intersect(nodes, rownames(cor_mat))
cat(sprintf("nodes 保留: %d 个（过滤掉不在 cor_mat 中的基因）\n", length(nodes)))

edges <- expand.grid(from = nodes, to = nodes,
                     stringsAsFactors = FALSE) %>%
  filter(from < to) %>%
  mutate(weight = cor_mat[cbind(from, to)]) %>%
  filter(abs(weight) > 0.3)

cat(sprintf("edges: %d 条\n", nrow(edges)))

# ---------- 7. 保存 ----------
saveRDS(list(
  hgf_cor = hgf_cor,
  hgf_neighbors = hgf_neighbors,
  overlap_with_sig11 = overlap,
  fisher_p = ft$p.value,
  fisher_or = ft$estimate,
  network = if (exists("g")) g else NULL
), "results/revision/B2_network_analysis.rds")

cat("\n✅ P1-4A 完成\n")


