dir.create("figures/Figure2", showWarnings = FALSE, recursive = TRUE)

# ---------- 1. 参考 scRNA ----------
cat("Loading scRNA reference...\n")
sc <- readRDS("results/GSE202379_seurat_clean.rds")
avail <- unique(as.character(sc@meta.data$cell.annotation))
main_types <- c("Stellate", "Hepatocytes", "Cholangiocytes",
                "Endothelial", "Macrophages")
matched <- unique(unlist(lapply(main_types, function(t)
  grep(t, avail, ignore.case = TRUE, value = TRUE)[1])))
matched <- matched[!is.na(matched)]
cat(sprintf("细胞类型: %s\n", paste(matched, collapse = ", ")))

# 只保留匹配的类型
keep_cells <- which(sc@meta.data$cell.annotation %in% matched)
sc_sub <- subset(sc, cells = colnames(sc)[keep_cells])
DefaultAssay(sc_sub) <- "RNA"

# 提取稀疏矩阵（不转 dense）
rna_data <- GetAssayData(sc_sub, assay = "RNA", layer = "data")
ct_vec <- as.character(sc_sub@meta.data$cell.annotation)
rm(sc, sc_sub); gc()

cat(sprintf("稀疏矩阵: %d genes x %d cells\n", nrow(rna_data), ncol(rna_data)))

# ---------- 2. 按细胞类型求 rowMeans（稀疏分块） ----------
ref_list <- list()
for (ct in matched) {
  idx <- which(ct_vec == ct)
  if (length(idx) > 5000) {
    set.seed(123)
    idx <- sample(idx, 5000)
  }
  cat(sprintf("  %s: %d cells\n", ct, length(idx)))
  
  sub_mat <- rna_data[, idx, drop = FALSE]
  # 分块 rowSums
  chunk_size <- 500
  n_chunks <- ceiling(length(idx) / chunk_size)
  sums <- rep(0, nrow(sub_mat))
  for (k in 1:n_chunks) {
    start_i <- (k - 1) * chunk_size + 1
    end_i <- min(k * chunk_size, length(idx))
    chunk <- sub_mat[, start_i:end_i, drop = FALSE]
    sums <- sums + Matrix::rowSums(chunk)
  }
  ref_list[[ct]] <- sums / length(idx)
}

ref_matrix <- do.call(cbind, ref_list)
colnames(ref_matrix) <- names(ref_list)
ref_matrix <- as.matrix(ref_matrix)
cat(sprintf("参考矩阵: %d x %d\n", nrow(ref_matrix), ncol(ref_matrix)))
rm(rna_data, sub_mat, chunk); gc()

# ---------- 3. Bulk 数据 ----------
d <- readRDS("results/GSE135251_DEG_results.rds")
sym_map <- mapIds(org.Hs.eg.db, keys = rownames(d$log_expr),
                  column = "SYMBOL", keytype = "ENSEMBL",
                  multiVals = "first")
valid <- !is.na(sym_map) & !duplicated(sym_map)
bulk <- as.matrix(d$log_expr[valid, ])
rownames(bulk) <- sym_map[valid]
stage <- d$fibro_stage

# ---------- 4. 共同基因 + NNLS ----------
common <- intersect(rownames(ref_matrix), rownames(bulk))
cat(sprintf("共同基因: %d\n", length(common)))
ref_matrix <- ref_matrix[common, , drop = FALSE]
bulk <- bulk[common, , drop = FALSE]

cat("Running NNLS deconvolution...\n")
prop_matrix <- t(sapply(seq_len(ncol(bulk)), function(i) {
  fit <- nnls::nnls(ref_matrix, as.numeric(bulk[, i]))
  coef(fit) / sum(coef(fit))
}))
rownames(prop_matrix) <- colnames(bulk)
colnames(prop_matrix) <- colnames(ref_matrix)

# ---------- 5. 提取 HSC 比例 + 趋势检验 ----------
hsc_col <- grep("stellate|hsc", colnames(prop_matrix),
                ignore.case = TRUE, value = TRUE)[1]
hsc_prop <- prop_matrix[, hsc_col]

cat(sprintf("\nHSC proportion: %.4f - %.4f (median %.4f)\n",
            min(hsc_prop), max(hsc_prop), median(hsc_prop)))

jt <- jonckheere.test(hsc_prop, as.numeric(factor(stage)),
                      alternative = "increasing")
sp <- cor.test(hsc_prop, stage, method = "spearman")

cat(sprintf("JT trend P = %.3e\n", jt$p.value))
cat(sprintf("Spearman rho = %.3f, P = %.3e\n", sp$estimate, sp$p.value))
cat("各分期均值:\n"); print(round(tapply(hsc_prop, stage, mean), 4))

# ---------- 6. 可视化 ----------
df_plot <- data.frame(Stage = factor(stage, levels = 0:4),
                      HSC_prop = hsc_prop)

p_hsc <- ggplot(df_plot, aes(Stage, HSC_prop, fill = Stage)) +
  geom_boxplot(alpha = 0.85, outlier.shape = NA, width = 0.7) +
  geom_jitter(width = 0.2, size = 0.5, alpha = 0.3, color = "grey30") +
  geom_smooth(aes(group = 1), method = "lm", se = TRUE,
              color = "#C73E1D", fill = "#C73E1D", alpha = 0.15) +
  scale_fill_brewer(palette = "OrRd") +
  labs(title = "HSC proportion across fibrosis stages",
       subtitle = sprintf("NNLS deconvolution (GSE135251, n=%d); JT P = %.2e, rho = %.3f",
                          length(hsc_prop), jt$p.value, sp$estimate),
       x = "METAVIR fibrosis stage", y = "Estimated HSC proportion") +
  theme_classic(base_size = 11) +
  theme(legend.position = "none",
        plot.title = element_text(face = "bold"),
        plot.subtitle = element_text(size = 9, color = "grey30"))

ggsave("figures/Figure2/FigureS25_HSC_proportion.pdf", p_hsc,
       width = 7, height = 4.5)
ggsave("figures/Figure2/FigureS25_HSC_proportion.png", p_hsc,
       width = 7, height = 4.5, dpi = 300)
print(p_hsc)

# ---------- 7. 保存 ----------
saveRDS(list(
  prop_matrix = prop_matrix,
  hsc_prop = hsc_prop,
  stage = stage,
  jt_p = jt$p.value,
  spearman_rho = as.numeric(sp$estimate),
  spearman_p = sp$p.value,
  stage_means = tapply(hsc_prop, stage, mean),
  ref_celltypes = colnames(ref_matrix),
  common_genes_n = length(common)
), "results/revision/A1_deconvolution.rds")

