# ---------- 1. 建数据（复用你现有代码的逻辑） ----------
add_patient <- function(obj, celltype_col, x_cutoff = 5) {
  fov_x <- obj@meta.data %>%
    group_by(fov) %>%
    summarise(x_center = mean(x_slide_mm), .groups = "drop") %>%
    mutate(patient = ifelse(x_center < x_cutoff, "P_A", "P_B"))
  obj@meta.data$patient <- fov_x$patient[match(obj@meta.data$fov, fov_x$fov)]
  obj
}

cosmx1 <- readRDS("data/GSM8855042_Slide1_SeuratObject.RDS")
cosmx2 <- readRDS("data/GSM8855043_Slide2_SeuratObject.RDS")
cosmx1 <- add_patient(cosmx1,
                      "RNA_nbclust_8b0a3ae1.8754.4ba9.8269.45e2cf2e855a_1_clusters")
cosmx2 <- add_patient(cosmx2,
                      "RNA_nbclust_ee1320c5.9f48.455c.b54e.1fbfd34347ab_1_clusters")

extract_core <- function(obj, celltype_col, slide) {
  ct   <- obj@meta.data[[celltype_col]]
  expr <- obj[["RNA"]]$data
  df   <- obj@meta.data[, c("x_slide_mm","y_slide_mm","fov","patient")]
  df$celltype <- ct
  df$HGF      <- as.numeric(expr["HGF", ])
  df$slide    <- slide
  df
}

df_all <- rbind(
  extract_core(cosmx1,
               "RNA_nbclust_8b0a3ae1.8754.4ba9.8269.45e2cf2e855a_1_clusters", "S1"),
  extract_core(cosmx2,
               "RNA_nbclust_ee1320c5.9f48.455c.b54e.1fbfd34347ab_1_clusters", "S2")
)
df_all$patient_uid <- paste(df_all$slide, df_all$patient, sep = "_")
rm(cosmx1, cosmx2); gc()

stellate <- df_all[df_all$celltype == "Stellate.cells", ]
hep4     <- df_all[df_all$celltype == "Hep.4", ]

# ---------- 2. 距离计算：HSC → 最近 Hep.4 ----------
compute_nn <- function(src, tgt) {
  out <- rep(NA_real_, nrow(src))
  for (f in unique(src$fov)) {
    s_idx <- which(src$fov == f)
    t_idx <- which(tgt$fov == f)
    if (length(t_idx) == 0) next
    s_c <- src[s_idx, c("x_slide_mm","y_slide_mm")]
    t_c <- tgt[t_idx, c("x_slide_mm","y_slide_mm")]
    d <- sapply(seq_len(nrow(s_c)), function(i) {
      sqrt((t_c$x_slide_mm - s_c$x_slide_mm[i])^2 +
             (t_c$y_slide_mm - s_c$y_slide_mm[i])^2)
    })
    out[s_idx] <- apply(d, 2, min) * 1000
  }
  out
}

stellate$dist_to_Hep4 <- compute_nn(stellate, hep4)
stellate$HGF_pos      <- as.numeric(stellate$HGF > 0)
stellate$dist_scaled  <- as.numeric(scale(stellate$dist_to_Hep4))

cat(sprintf("HSC: %d (HGF+ %d, HGF- %d)\n",
            nrow(stellate), sum(stellate$HGF_pos == 1),
            sum(stellate$HGF_pos == 0)))
cat(sprintf("FOV: %d, 患者: %d\n",
            length(unique(stellate$fov)),
            length(unique(stellate$patient_uid))))

# ---------- 3. 三个混合效应模型 ----------
cat("\n========== 混合效应模型 ==========\n")

# 3a. Patient 随机效应
m_pat <- lmer(dist_scaled ~ HGF_pos + (1 | patient_uid),
              data = stellate, REML = FALSE)
cat("\n--- Patient random effect ---\n")
coef_tab <- summary(m_pat)$coefficients
print(coef_tab)
ci <- confint(m_pat, method = "Wald", parm = "HGF_pos")
cat(sprintf("\nHGF_pos beta = %.4f, 95%% CI: [%.4f, %.4f], P = %.3e\n",
            coef_tab["HGF_pos", "Estimate"],
            ci[1, 1], ci[1, 2],
            coef_tab["HGF_pos", "Pr(>|t|)"]))

# 3b. FOV 嵌套在 Patient 内
m_nest <- lmer(dist_scaled ~ HGF_pos + (1 | patient_uid/fov),
               data = stellate, REML = FALSE)
cat("\n--- FOV nested in Patient ---\n")
coef_tab2 <- summary(m_nest)$coefficients
print(coef_tab2)
cat(sprintf("\nHGF_pos beta = %.4f, P = %.3e\n",
            coef_tab2["HGF_pos", "Estimate"],
            coef_tab2["HGF_pos", "Pr(>|t|)"]))

# 3c. Naive cell-level t-test（作为对比，说明 pseudoreplication 的问题）
naive_t <- t.test(dist_to_Hep4 ~ HGF_pos, data = stellate)
cat(sprintf("\n--- Naive cell-level t-test ---\n"))
cat(sprintf("P = %.3e (对比: 说明 cell-level 检验会低估 P 值)\n",
            naive_t$p.value))

# ---------- 4. 患者级方向一致性 ----------
patient_agg <- stellate %>%
  group_by(patient_uid, HGF_pos) %>%
  summarise(median_dist = median(dist_to_Hep4, na.rm = TRUE),
            .groups = "drop") %>%
  pivot_wider(names_from = HGF_pos, values_from = median_dist,
              names_prefix = "HGF_") %>%
  mutate(delta = HGF_1 - HGF_0)

cat("\n--- 患者级 Δ 距离 ---\n")
print(as.data.frame(patient_agg))

n_neg <- sum(patient_agg$delta < 0, na.rm = TRUE)
binom_p <- binom.test(n_neg, nrow(patient_agg),
                      p = 0.5, alternative = "greater")$p.value
cat(sprintf("方向一致性: %d / %d 患者 HGF+ 更近\n",
            n_neg, nrow(patient_agg)))
cat(sprintf("Binomial test P = %.4f\n", binom_p))

# ---------- 5. 保存 ----------
saveRDS(list(
  m_pat = list(beta = coef_tab["HGF_pos", "Estimate"],
               se = coef_tab["HGF_pos", "Std. Error"],
               t = coef_tab["HGF_pos", "t value"],
               df = coef_tab["HGF_pos", "df"],
               p = coef_tab["HGF_pos", "Pr(>|t|)"],
               ci = ci),
  m_nest = list(beta = coef_tab2["HGF_pos", "Estimate"],
                p = coef_tab2["HGF_pos", "Pr(>|t|)"]),
  naive_t_p = naive_t$p.value,
  patient_agg = patient_agg,
  binom_p = binom_p,
  n_patients = nrow(patient_agg)
), "results/revision/A3b_mixed_effects.rds")

cat("\n✅ A3b 完成\n")


