# 通用距离计算函数
compute_nn <- function(src, tgt) {
  out <- rep(NA_real_, nrow(src))
  for (f in unique(src$fov)) {
    s_idx <- which(src$fov == f)
    t_idx <- which(tgt$fov == f)
    if (length(t_idx) == 0) next
    s_c <- src[s_idx, c("x_slide_mm","y_slide_mm")]
    t_c <- tgt[t_idx, c("x_slide_mm","y_slide_mm")]
    d <- sapply(seq_len(nrow(s_c)), function(i) {
      sqrt((t_c$x_slide_mm - s_c$x_slide_mm[i])^2 +
             (t_c$y_slide_mm - s_c$y_slide_mm[i])^2)
    })
    out[s_idx] <- apply(d, 2, min) * 1000
  }
  out
}

# ============================================================
# 分析 1: 距离阈值敏感性
# ============================================================
cat("\n========== 分析 1: 距离阈值敏感性 ==========\n")

hep4 <- df_all[df_all$celltype == "Hep.4", ]
stellate$dist_to_Hep4 <- compute_nn(stellate, hep4)

thresholds <- c(20, 30, 40, 50, 75, 100)
thr_results <- data.frame()

for (th in thresholds) {
  sub <- stellate[!is.na(stellate$dist_to_Hep4) &
                    stellate$dist_to_Hep4 <= th, ]
  if (nrow(sub) < 50 ||
      length(unique(sub$HGF_pos)) < 2 ||
      sum(sub$HGF_pos) < 10 ||
      sum(1 - sub$HGF_pos) < 10) {
    cat(sprintf("%3d um: 样本不足，跳过\n", th))
    next
  }
  
  w <- wilcox.test(dist_to_Hep4 ~ HGF_pos, data = sub)
  
  med_pos <- median(sub$dist_to_Hep4[sub$HGF_pos == 1], na.rm = TRUE)
  med_neg <- median(sub$dist_to_Hep4[sub$HGF_pos == 0], na.rm = TRUE)
  delta <- med_pos - med_neg
  
  sub$dist_scaled <- as.numeric(scale(sub$dist_to_Hep4))
  m <- tryCatch(
    lmer(dist_scaled ~ HGF_pos + (1 | patient_uid),
         data = sub, REML = FALSE),
    error = function(e) NULL
  )
  if (!is.null(m)) {
    coef_tab <- summary(m)$coefficients
    lmer_p <- coef_tab["HGF_pos", "Pr(>|t|)"]
    lmer_beta <- coef_tab["HGF_pos", "Estimate"]
  } else {
    lmer_p <- NA_real_
    lmer_beta <- NA_real_
  }
  
  thr_results <- rbind(thr_results, data.frame(
    Threshold_um = th,
    N_HSC = nrow(sub),
    N_HGFpos = sum(sub$HGF_pos == 1),
    N_HGFneg = sum(sub$HGF_pos == 0),
    Median_HGFpos = round(med_pos, 2),
    Median_HGFneg = round(med_neg, 2),
    Delta_um = round(delta, 2),
    Wilcoxon_P = w$p.value,
    Lmer_beta = round(lmer_beta, 3),
    Lmer_P = lmer_p
  ))
}

print(thr_results)
write.csv(thr_results,
          "results/revision/A4_threshold_sensitivity.csv",
          row.names = FALSE)

