mt_results <- data.frame()
for (ct in valid_ct) {
  tgt <- df_all[df_all$celltype == ct, ]
  d <- compute_nn(stellate, tgt)
  
  w <- tryCatch(
    wilcox.test(d ~ stellate$HGF_pos),
    error = function(e) NULL
  )
  if (is.null(w)) next
  
  med_pos <- median(d[stellate$HGF_pos == 1], na.rm = TRUE)
  med_neg <- median(d[stellate$HGF_pos == 0], na.rm = TRUE)
  
  mt_results <- rbind(mt_results, data.frame(
    CellType = ct,
    N_target = nrow(tgt),
    Median_HGFpos = round(med_pos, 1),
    Median_HGFneg = round(med_neg, 1),
    Delta_um = round(med_pos - med_neg, 2),
    Wilcoxon_P = w$p.value
  ))
  cat(sprintf("  %-35s done\n", ct))
}

mt_results$FDR_BH <- p.adjust(mt_results$Wilcoxon_P, method = "BH")
mt_results <- mt_results[order(mt_results$FDR_BH), ]
print(mt_results)
write.csv(mt_results,
          "results/revision/A4_multiple_testing.csv",
          row.names = FALSE)

# ---------- 分析 2 可视化 ----------
plot_mt <- mt_results %>%
  mutate(Significant = ifelse(FDR_BH < 0.05, "FDR < 0.05", "n.s."),
         CellType = factor(CellType,
                           levels = CellType[order(Delta_um)]))

p_mt <- ggplot(plot_mt, aes(Delta_um, CellType, fill = Significant)) +
  geom_col(alpha = 0.9, width = 0.75) +
  scale_fill_manual(values = c("FDR < 0.05" = "#C73E1D",
                               "n.s." = "grey70")) +
  geom_vline(xintercept = 0, linetype = "dashed", color = "grey40") +
  labs(title = "Selectivity of the HGF+ HSC niche across cell types",
       subtitle = sprintf("Δ median distance (HGF+ − HGF−); BH-corrected across %d cell types",
                          nrow(mt_results)),
       x = "Δ median distance (μm) — negative = HGF+ closer",
       y = NULL, fill = NULL) +
  theme_classic(base_size = 10) +
  theme(legend.position = "top",
        plot.title = element_text(face = "bold"),
        plot.subtitle = element_text(size = 9, color = "grey30"),
        axis.text.y = element_text(size = 8))

ggsave("figures/Figure2/FigureS31_multiple_testing.pdf", p_mt,
       width = 7, height = 6)
ggsave("figures/Figure2/FigureS31_multiple_testing.png", p_mt,
       width = 7, height = 6, dpi = 300)
print(p_mt)

saveRDS(list(mt_results = mt_results),
        "results/revision/A4_multiple_testing.rds")

# ============================================================
# 最终输出
# ============================================================
cat("\n========================================\n")
cat("✅ A4 完成\n")
cat("========================================\n")

cat("\n=== 距离阈值敏感性 ===\n")
print(thr_results)

cat("\n=== 多重比较 (BH FDR < 0.05) ===\n")
sig_mt <- mt_results[mt_results$FDR_BH < 0.05,
                     c("CellType", "N_target", "Delta_um",
                       "Wilcoxon_P", "FDR_BH")]
print(sig_mt)

cat("\n输出文件:\n")
cat("  results/revision/A4_threshold_sensitivity.csv/rds\n")
cat("  results/revision/A4_multiple_testing.csv/rds\n")
cat("  figures/Figure2/FigureS30_threshold_sensitivity.pdf/png\n")
cat("  figures/Figure2/FigureS31_multiple_testing.pdf/png\n")


