# download_public_cohorts_fixed.R
# 目的: 下载含临床变量的公共肝脏转录组数据集
# 关键修复: 先创建 destdir 子目录（getGEO 不会自动创建）
# ============================================================
rm(list = ls()); gc()
setwd("~/Desktop/sjfx3")

suppressPackageStartupMessages({
  library(GEOquery)
  library(tidyverse)
})

options(timeout = 3600)

# 需要下载的队列
cohorts <- c("GSE48452", "GSE89632", "GSE126848",
             "GSE33814", "GSE84044")

# ---------- 1. 先创建所有子目录 ----------
dir.create("data/public_cohorts",
           showWarnings = FALSE, recursive = TRUE)

for (g in cohorts) {
  dir.create(file.path("data/public_cohorts", g),
             showWarnings = FALSE, recursive = TRUE)
  cat(sprintf("目录就绪: data/public_cohorts/%s\n", g))
}

# ============================================================
# 2. 逐个下载
# ============================================================
for (g in cohorts) {
  cat(sprintf("\n========== %s ==========\n", g))
  out_rds <- file.path("data/public_cohorts", paste0(g, ".rds"))
  
  # 已下载则跳过
  if (file.exists(out_rds)) {
    cat("已存在 rds 文件，跳过\n")
    next
  }
  
  tryCatch({
    gse <- getGEO(g,
                  GSEMatrix = TRUE,
                  getGPL = FALSE,
                  destdir = file.path("data/public_cohorts", g))
    pheno <- pData(gse[[1]])
    expr  <- exprs(gse[[1]])
    
    cat(sprintf("样本数: %d\n", nrow(pheno)))
    cat(sprintf("表达矩阵: %d genes x %d samples\n",
                nrow(expr), ncol(expr)))
    
    # 打印可能的临床变量列
    clin_vars <- grep("age|ast|alt|platelet|fibrosis|steatosis|diagnosis|bmi|gender|sex|inflammation|scheuer",
                      colnames(pheno), ignore.case = TRUE, value = TRUE)
    cat("临床变量列:\n")
    print(clin_vars)
    
    saveRDS(list(expr = expr, pheno = pheno), out_rds)
    cat(sprintf("✅ %s 下载完成\n", g))
  }, error = function(e) {
    cat(sprintf("❌ %s 失败: %s\n", g, conditionMessage(e)))
  })
}

# ============================================================
# 3. 汇总
# ============================================================
cat("\n========================================\n")
cat("下载完成汇总:\n")
files <- list.files("data/public_cohorts", pattern = "\\.rds$")
if (length(files) == 0) {
  cat("  (无)\n")
} else {
  for (f in files) {
    path <- file.path("data/public_cohorts", f)
    size <- round(file.info(path)$size / 1024^2, 1)
    cat(sprintf("  %s (%.1f MB)\n", f, size))
  }
}
cat("========================================\n")

