  })
}
# ============================================================
# A5a_GSE89632_trend.R
# 目的: GSE89632 中 signature 与 fibrosis stage 的连续趋势
# 输出: results/revision/A5a_GSE89632_trend.rds
#       figures/Figure2/FigureS32_GSE89632_trend.pdf
# ============================================================
rm(list = ls()); gc()
setwd("~/Desktop/sjfx3")
suppressPackageStartupMessages({
  library(tidyverse); library(pROC); library(clinfun)
  library(ggplot2)
})

dir.create("results/revision", showWarnings = FALSE, recursive = TRUE)
dir.create("figures/Figure2", showWarnings = FALSE, recursive = TRUE)

# ---------- 1. 加载 + probe 映射 ----------
d <- readRDS("data/public_cohorts/GSE89632.rds")
expr  <- d$expr
pheno <- d$pheno

# GSE89632 平台: Illumina HumanHT-12 V4.0 (GPL10558)
# 直接用 illuminaHumanv4.db 或 biomaRt 映射

if (!requireNamespace("illuminaHumanv4.db", quietly = TRUE)) {
  if (!requireNamespace("BiocManager", quietly = TRUE))
    install.packages("BiocManager")
  BiocManager::install("illuminaHumanv4.db",
                       ask = FALSE, update = FALSE)
}
suppressPackageStartupMessages({
  library(illuminaHumanv4.db)
})

# probe → symbol
probe_ids <- rownames(expr)
symbols <- mapIds(illuminaHumanv4.db,
                  keys = probe_ids,
                  column = "SYMBOL",
                  keytype = "PROBEID",
                  multiVals = "first")

cat(sprintf("Probe 总数: %d\n", length(probe_ids)))
cat(sprintf("成功映射到 symbol: %d\n", sum(!is.na(symbols))))

# 构建 symbol → 表达矩阵（多 probe 取平均）
expr_df <- as.data.frame(expr)
expr_df$symbol <- symbols
expr_df <- expr_df[!is.na(expr_df$symbol), ]

# 去重：同 symbol 多 probe 取均值
expr_df <- expr_df %>%
  group_by(symbol) %>%
  summarise(across(where(is.numeric), mean), .groups = "drop") %>%
  column_to_rownames("symbol") %>%
  as.matrix()

cat(sprintf("映射后矩阵: %d genes x %d samples\n",
            nrow(expr_df), ncol(expr_df)))

# ---------- 2. 检查 11 基因 ----------
sig11 <- c("EYA2","FERMT1","PYROXD2","EPB41L4A","CHI3L1",
           "CNKSR1","ILDR1","GSN","TMPRSS3","ESRRG","SULF2")
sig_in <- intersect(sig11, rownames(expr_df))
cat(sprintf("\n11 基因可用: %d / 11\n", length(sig_in)))
cat("保留:", paste(sig_in, collapse=", "), "\n")
cat("缺失:", paste(setdiff(sig11, sig_in), collapse=", "), "\n")

if (length(sig_in) < 5) {
  stop("可用基因太少，无法计算 signature")
}

# ---------- 3. Signature 打分 ----------
expr_sig <- expr_df[sig_in, , drop = FALSE]
expr_z <- t(scale(t(expr_sig)))
expr_z[is.na(expr_z)] <- 0
sig_score <- colMeans(expr_z)
cat(sprintf("Signature score 范围: %.3f - %.3f\n",
            min(sig_score), max(sig_score)))

# ---------- 4. 与临床变量对齐 ----------
clin <- data.frame(
  sample   = rownames(pheno),
  age      = as.numeric(pheno[["age (y):ch1"]]),
  ast      = as.numeric(pheno[["aspartate transaminase (u/l):ch1"]]),
  alt      = as.numeric(pheno[["alanine transaminase (u/l):ch1"]]),
  bmi      = as.numeric(pheno[["body mass index (kg/m2):ch1"]]),
  diab     = ifelse(pheno[["diabetes:ch1"]] == "yes", 1, 0),
  fibrosis = as.character(pheno[["fibrosis (stage):ch1"]]),
  diagnosis = as.character(pheno[["diagnosis:ch1"]]),
  stringsAsFactors = FALSE
)

# 数值化 fibrosis
clin$fib_num <- suppressWarnings(as.numeric(clin$fibrosis))
cat("\nFibrosis 分布:\n"); print(table(clin$fib_num, useNA="ifany"))

# 对齐
common <- intersect(names(sig_score), clin$sample)
clin <- clin[match(common, clin$sample), ]
clin$sig_score <- as.numeric(sig_score[common])

# 只保留有 fibrosis 分期的样本
clin_f <- clin[!is.na(clin$fib_num), ]
cat(sprintf("\n有 fibrosis 分期样本: %d\n", nrow(clin_f)))
cat("分期分布:\n"); print(table(clin_f$fib_num))

# ---------- 5. 连续趋势分析（Spearman + JT） ----------
sp <- cor.test(clin_f$sig_score, clin_f$fib_num, method = "spearman")
jt <- jonckheere.test(clin_f$sig_score,
                      as.numeric(factor(clin_f$fib_num)),
                      alternative = "increasing")

cat(sprintf("\n=== Signature 沿 fibrosis 分期 ===\n"))
cat(sprintf("Spearman rho = %.3f, P = %.3e\n",
            sp$estimate, sp$p.value))
cat(sprintf("Jonckheere-Terpstra P = %.3e\n", jt$p.value))
cat("\n各分期 signature 均值:\n")
print(round(tapply(clin_f$sig_score, clin_f$fib_num, mean), 3))

# 亚组：F0-F1 vs F2-F4（尽管样本少，报告但标注探索性）
clin_f$fib_bin <- ifelse(clin_f$fib_num >= 2, 1, 0)
roc_obj <- roc(clin_f$fib_bin, clin_f$sig_score, quiet = TRUE)
auc_val <- as.numeric(auc(roc_obj))
ci_val  <- as.numeric(ci.auc(roc_obj))
cat(sprintf("\n[AUC F0-F1 vs F2-F4] %.3f (%.3f-%.3f) [n=%d, events=%d]\n",
            auc_val, ci_val[1], ci_val[3],
            nrow(clin_f), sum(clin_f$fib_bin)))

# ---------- 6. 可视化 ----------
plot_df <- data.frame(Stage = factor(clin_f$fib_num),
                      Sig = clin_f$sig_score)

p_trend <- ggplot(plot_df, aes(Stage, Sig, fill = Stage)) +
  geom_boxplot(alpha = 0.85, outlier.shape = NA, width = 0.6) +
  geom_jitter(width = 0.15, size = 0.8, alpha = 0.3) +
  geom_smooth(aes(group = 1), method = "lm", se = TRUE,
              color = "#C73E1D", fill = "#C73E1D", alpha = 0.15) +
  scale_fill_brewer(palette = "OrRd") +
  labs(title = "GSE89632: 11-gene signature vs fibrosis stage",
       subtitle = sprintf("Spearman rho = %.3f, P = %.2e; JT P = %.2e",
                          sp$estimate, sp$p.value, jt$p.value),
       x = "Fibrosis stage", y = "Signature score (z-mean)") +
  theme_classic(base_size = 11) +
  theme(legend.position = "none",
        plot.title = element_text(face = "bold"),
        plot.subtitle = element_text(size = 9, color = "grey30"))

ggsave("figures/Figure2/FigureS32_GSE89632_trend.pdf", p_trend,
       width = 7, height = 4.5)
ggsave("figures/Figure2/FigureS32_GSE89632_trend.png", p_trend,
       width = 7, height = 4.5, dpi = 300)
print(p_trend)

# ---------- 7. 保存 ----------
saveRDS(list(
  sig_score = sig_score,
  clin_f = clin_f,
  spearman_rho = as.numeric(sp$estimate),
  spearman_p = sp$p.value,
  jt_p = jt$p.value,
  auc = auc_val, auc_ci = ci_val,
  n = nrow(clin_f),
  n_events = sum(clin_f$fib_bin),
  sig_genes = sig_in
), "results/revision/A5a_GSE89632_trend.rds")

cat("\n✅ A5a 完成\n")
# ============================================================
