# ---------- 1. 加载 GSE84044 ----------
d <- readRDS("data/public_cohorts/GSE84044.rds")
expr <- d$expr
pheno <- d$pheno

cat(sprintf("GSE84044: %d probes x %d samples\n",
            nrow(expr), ncol(expr)))
cat("Probe preview (前 5 个):\n")
print(head(rownames(expr), 5))

# ---------- 2. Affymetrix probe → symbol ----------
if (!requireNamespace("hgu133plus2.db", quietly = TRUE)) {
  if (!requireNamespace("BiocManager", quietly = TRUE))
    install.packages("BiocManager")
  BiocManager::install("hgu133plus2.db", ask = FALSE, update = FALSE)
}
suppressPackageStartupMessages({
  library(hgu133plus2.db); library(AnnotationDbi)
})

# 确认 keytype 匹配
valid_keys <- keys(hgu133plus2.db, keytype = "PROBEID")
n_match <- sum(rownames(expr) %in% valid_keys)
cat(sprintf("\nProbe 匹配: %d / %d\n", n_match, nrow(expr)))

if (n_match < 10000) stop("映射匹配太少，可能平台不对")

symbols <- mapIds(hgu133plus2.db,
                  keys = rownames(expr),
                  column = "SYMBOL",
                  keytype = "PROBEID",
                  multiVals = "first")

cat(sprintf("成功映射到 SYMBOL: %d / %d\n",
            sum(!is.na(symbols)), length(symbols)))

# ---------- 3. 构建 symbol 矩阵（多 probe 取均值） ----------
expr_df <- as.data.frame(expr)
expr_df$symbol <- symbols
expr_df <- expr_df[!is.na(expr_df$symbol), ]

expr_df <- expr_df %>%
  group_by(symbol) %>%
  summarise(across(where(is.numeric), mean), .groups = "drop") %>%
  column_to_rownames("symbol") %>%
  as.matrix()

cat(sprintf("映射后: %d genes x %d samples\n",
            nrow(expr_df), ncol(expr_df)))

# ---------- 4. 11 基因 signature ----------
sig11 <- c("EYA2","FERMT1","PYROXD2","EPB41L4A","CHI3L1",
           "CNKSR1","ILDR1","GSN","TMPRSS3","ESRRG","SULF2")
sig_in <- intersect(sig11, rownames(expr_df))
cat(sprintf("\n11 基因可用: %d / 11\n", length(sig_in)))
cat("保留:", paste(sig_in, collapse = ", "), "\n")
cat("缺失:", paste(setdiff(sig11, sig_in), collapse = ", "), "\n")

if (length(sig_in) < 5) {
  stop("可用基因太少，GSE84044 也无法用于 signature 分析")
}

# Signature 打分
expr_sig <- expr_df[sig_in, , drop = FALSE]
expr_z <- t(scale(t(expr_sig)))
expr_z[is.na(expr_z)] <- 0
sig_score <- colMeans(expr_z)

cat(sprintf("Signature score 范围: %.3f - %.3f\n",
            min(sig_score), max(sig_score)))

# ---------- 5. 临床变量 ----------
clin <- data.frame(
  sample    = rownames(pheno),
  age       = as.numeric(pheno[["age:ch1"]]),
  gender    = as.character(pheno[["gender:ch1"]]),
  scheuer_g = as.numeric(pheno[["scheuer score g:ch1"]]),
  scheuer_s = as.numeric(pheno[["scheuer score s:ch1"]]),
  batch     = as.character(pheno[["batch:ch1"]]),
  stringsAsFactors = FALSE
)

cat("\nScheuer s (fibrosis) 分布:\n")
print(table(clin$scheuer_s, useNA = "ifany"))
cat("\nScheuer g (grade/inflammation) 分布:\n")
print(table(clin$scheuer_g, useNA = "ifany"))

# 对齐
common <- intersect(names(sig_score), clin$sample)
cat(sprintf("\n对齐样本: %d\n", length(common)))
clin <- clin[match(common, clin$sample), ]
clin$sig_score <- as.numeric(sig_score[common])

# 只保留有 Scheuer s 的样本
clin_f <- clin[!is.na(clin$scheuer_s), ]
cat(sprintf("有 Scheuer s 分期样本: %d\n", nrow(clin_f)))
cat("分期分布:\n"); print(table(clin_f$scheuer_s))

# ---------- 6. 剂量-反应检验 ----------
sp <- cor.test(clin_f$sig_score, clin_f$scheuer_s, method = "spearman")
jt <- jonckheere.test(clin_f$sig_score,
                      as.numeric(factor(clin_f$scheuer_s)),
                      alternative = "increasing")
kw <- kruskal.test(clin_f$sig_score ~ factor(clin_f$scheuer_s))

cat(sprintf("\n=== Signature 沿 Scheuer s 分期 ===\n"))
cat(sprintf("Spearman rho = %.3f, P = %.3e\n",
            sp$estimate, sp$p.value))
cat(sprintf("Jonckheere-Terpstra P = %.3e\n", jt$p.value))
cat(sprintf("Kruskal-Wallis P = %.3e\n", kw$p.value))
cat("\n各 Scheuer s 均值:\n")
print(round(tapply(clin_f$sig_score, clin_f$scheuer_s, mean), 3))

# ---------- 7. 二元对比（s0-s1 vs s3-s4，探索性） ----------
clin_f$fib_bin <- ifelse(clin_f$scheuer_s >= 3, 1,
                         ifelse(clin_f$scheuer_s <= 1, 0, NA))
clin_bin <- clin_f[!is.na(clin_f$fib_bin), ]

cat(sprintf("\n二元分组 (s0-s1 vs s3-s4):\n"))
