if (length(unique(clin_bin$fib_bin)) == 2) {
  roc_obj <- roc(clin_bin$fib_bin, clin_bin$sig_score, quiet = TRUE)
  auc_val <- as.numeric(auc(roc_obj))
  ci_val  <- as.numeric(ci.auc(roc_obj))
  cat(sprintf("AUC = %.3f (95%% CI: %.3f-%.3f) [n=%d, events=%d]\n",
              auc_val, ci_val[1], ci_val[3],
              nrow(clin_bin), sum(clin_bin$fib_bin == 1)))
} else {
  auc_val <- NA; ci_val <- c(NA, NA)
}

# ---------- 8. 可视化 ----------
plot_df <- data.frame(Stage = factor(clin_f$scheuer_s),
                      Sig = clin_f$sig_score)

p_trend <- ggplot(plot_df, aes(Stage, Sig, fill = Stage)) +
  geom_boxplot(alpha = 0.85, outlier.shape = NA, width = 0.6) +
  geom_jitter(width = 0.15, size = 0.8, alpha = 0.3) +
  geom_smooth(aes(group = 1), method = "lm", se = TRUE,
              color = "#C73E1D", fill = "#C73E1D", alpha = 0.15) +
  scale_fill_brewer(palette = "OrRd") +
  labs(title = "GSE84044: 11-gene signature vs Scheuer fibrosis stage",
       subtitle = sprintf("Spearman rho = %.3f, P = %.2e; JT P = %.2e; n = %d",
                          sp$estimate, sp$p.value, jt$p.value,
                          nrow(clin_f)),
       x = "Scheuer score (s)", y = "Signature score (z-mean)") +
  theme_classic(base_size = 11) +
  theme(legend.position = "none",
        plot.title = element_text(face = "bold"),
        plot.subtitle = element_text(size = 9, color = "grey30"))

ggsave("figures/Figure2/FigureS34_GSE84044_trend.pdf", p_trend,
