# 稳健保存
safe_save <- function(p, name, w, h, dpi = 300) {
  pdf_f <- file.path(OUT, paste0(name, ".pdf"))
  png_f <- file.path(OUT, paste0(name, ".png"))
  tryCatch({
    pdf(pdf_f, width = w, height = h); print(p); dev.off()
    png(png_f, width = w, height = h, units = "in", res = dpi)
    print(p); dev.off()
    cat(sprintf("  ✅ %s\n", name))
  }, error = function(e) {
    if (dev.cur() > 1) try(dev.off(), silent = TRUE)
    cat(sprintf("  ❌ %s: %s\n", name, conditionMessage(e)))
  })
}

theme_pub <- function(base = 10) {
  theme_classic(base_size = base) +
    theme(plot.title = element_text(face = "bold", size = base + 1),
          plot.subtitle = element_text(size = base - 1, color = "grey30"),
          plot.tag = element_text(face = "bold", size = base + 2))
}

