ct1  <- cosmx1@meta.data[[col1]]
coords1 <- cosmx1@meta.data[, c("x_slide_mm","y_slide_mm","fov")]
expr1 <- cosmx1[["RNA"]]$data

# 1a: 细胞类型组成（过滤单字母 cluster）
ct_df <- data.frame(CellType = names(table(ct1)),
                    N = as.numeric(table(ct1))) %>%
  filter(!grepl("^[a-j]$", CellType)) %>%
  mutate(Highlight = ifelse(CellType == "Stellate.cells",
                            "Stellate", "Others")) %>%
  arrange(desc(N)) %>% head(15)

p1a <- ggplot(ct_df, aes(reorder(CellType, N), N, fill = Highlight)) +
  geom_col(alpha = 0.85) +
  scale_fill_manual(values = c("Stellate" = "#C73E1D",
                               "Others" = "grey60")) +
  coord_flip() +
  labs(title = "Cell type composition",
       subtitle = sprintf("CosMx Slide1, n = %s cells",
                          format(ncol(cosmx1), big.mark = ",")),
       x = NULL, y = "Cell count") +
  theme_pub(9) +
  theme(legend.position = "none",
        axis.text.y = element_text(size = 7))

# 1b: Stellate 空间分布 + 纤维化区
fibro_sig <- c("IL6","IL1B","CCL2","CXCL9","CXCL10","TNF","MMP2","MMP14")
fibro_sig <- fibro_sig[fibro_sig %in% rownames(expr1)]
expr_f <- as.matrix(expr1[fibro_sig, , drop = FALSE])
fibro_score <- colMeans(expr_f)
non_hsc <- which(ct1 != "Stellate.cells")
thr <- quantile(fibro_score[non_hsc], 0.75, na.rm = TRUE)

plot_df <- coords1
plot_df$is_stellate <- ct1 == "Stellate.cells"
plot_df$is_fibro   <- fibro_score >= thr

p1b <- ggplot() +
  geom_point(data = plot_df[!plot_df$is_fibro, ],
             aes(x_slide_mm, y_slide_mm),
             size = 0.1, alpha = 0.15, color = "grey80") +
  geom_point(data = plot_df[plot_df$is_fibro, ],
             aes(x_slide_mm, y_slide_mm),
             size = 0.15, alpha = 0.15, color = "#F18F01") +
  geom_point(data = plot_df[plot_df$is_stellate, ],
             aes(x_slide_mm, y_slide_mm),
             size = 0.15, alpha = 0.55, color = "#C73E1D") +
  coord_fixed() +
  labs(title = "Stellate cells in fibrotic regions",
       subtitle = sprintf("Orange = fibrotic, Red = Stellate (n=%s, %.1f%%)",
                          format(sum(plot_df$is_stellate), big.mark = ","),
                          100 * mean(plot_df$is_stellate)),
       x = "x_slide_mm", y = "y_slide_mm") +
  theme_pub(9)

