cat("\n[S1] WGCNA\n")
wgcna <- readRDS("results/WGCNA_results.rds")
s1_df <- data.frame(Module = rownames(wgcna$moduleTraitCor),
                    r = as.numeric(wgcna$moduleTraitCor[, 1]),
                    P = as.numeric(wgcna$moduleTraitPvalue[, 1])) %>%
  mutate(Sig = ifelse(P < 0.05, "Significant (P < 0.05)", "n.s.")) %>%
  arrange(r)

p_s1 <- ggplot(s1_df, aes(reorder(Module, r), r, fill = Sig)) +
  geom_col(alpha = 0.9, width = 0.7) +
  scale_fill_manual(values = c("Significant (P < 0.05)" = "#C73E1D",
                               "n.s." = "grey70")) +
  geom_hline(yintercept = 0, color = "grey40") +
  coord_flip() +
  labs(title = "WGCNA module-trait correlation",
       subtitle = "Module eigengenes vs fibrosis group (GSE135251)",
       x = NULL, y = "Pearson r", fill = NULL) +
  theme_pub(10) + theme(legend.position = "top")
safe_save(p_s1, "FigureS1_WGCNA", 5, 5)

