# ============================================================
# S3: Calibration (GSE49541, MLE + Platt)
# ============================================================
cat("\n[S3] Calibration\n")
val <- readRDS("results/GSE49541_validation_unified_zscored.rds")
df_cal <- data.frame(outcome = as.integer(val$group),
                     pred = as.numeric(val$pred_prob))
df_cal <- df_cal[!is.na(df_cal$outcome), ]
df_cal$bin <- cut(df_cal$pred, breaks = seq(0, 1, 0.2), include.lowest = TRUE)

cal_df <- df_cal %>%
  group_by(bin) %>%
  summarise(mean_pred = mean(pred), obs_rate = mean(outcome),
            n = n(), .groups = "drop") %>% filter(n >= 3)

brier <- mean((df_cal$pred - df_cal$outcome)^2)
cal_model <- glm(outcome ~ qlogis(pmin(pmax(pred, 1e-10), 1 - 1e-10)),
                 data = df_cal, family = binomial)
slope <- coef(cal_model)[2]

p_s3 <- ggplot(cal_df, aes(mean_pred, obs_rate)) +
  geom_abline(intercept = 0, slope = 1, linetype = "dashed",
              color = "grey60") +
  geom_point(aes(size = n), color = "#C73E1D", alpha = 0.85) +
  geom_line(color = "#C73E1D") +
  labs(title = "Calibration plot (GSE49541)",
       subtitle = sprintf("Brier = %.3f; slope = %.3f",
                          brier, slope),
       x = "Predicted probability", y = "Observed rate", size = "N") +
  coord_fixed(xlim = c(0, 1), ylim = c(0, 1)) +
  theme_pub(10)
safe_save(p_s3, "FigureS3_calibration", 5, 5)

