roc_nested <- nested$roc

df_fixed <- data.frame(FPR = 1 - roc_fixed$specificities,
                       TPR = roc_fixed$sensitivities,
                       Method = "Fixed signature CV")
df_nested <- data.frame(FPR = 1 - roc_nested$specificities,
                        TPR = roc_nested$sensitivities,
                        Method = "Fully nested CV")

p_s4 <- ggplot(rbind(df_fixed, df_nested),
               aes(FPR, TPR, color = Method)) +
  geom_line(linewidth = 1.1) +
  geom_abline(intercept = 1, slope = 1, linetype = "dashed",
              color = "grey60") +
  scale_color_manual(values = c("Fixed signature CV" = "#C73E1D",
                                "Fully nested CV" = "#2E86AB")) +
  annotate("text", x = 0.98, y = 0.10, hjust = 1, size = 3.5,
           label = sprintf("Fixed CV AUC = %.3f\nFully nested CV AUC = %.3f",
                           as.numeric(pROC::auc(roc_fixed)),
                           as.numeric(pROC::auc(roc_nested)))) +
  labs(title = "Fixed vs nested CV",
       subtitle = "GSE135251",
       x = "1 - Specificity", y = "Sensitivity", color = NULL) +
  coord_fixed(xlim = c(0, 1), ylim = c(0, 1)) +
  theme_pub(10) + theme(legend.position = "top")
safe_save(p_s4, "FigureS4_CV_comparison", 5, 5)

