cat("\n[S5] Hep.4 identity\n")
if (file.exists("results/Hep4_scRNA_identity.rds")) {
  h4 <- readRDS("results/Hep4_scRNA_identity.rds")
  final_df <- h4$final_df
  top_cluster <- h4$top_cluster
  final_df$Is_Top <- ifelse(final_df$Cluster == top_cluster,
                            "Hep.4-mapped", "Other")
  
  p_s5a <- ggplot(final_df, aes(reorder(Cluster, Hep4_score),
                                Hep4_score, fill = Is_Top)) +
    geom_col(alpha = 0.9, width = 0.7) +
    scale_fill_manual(values = c("Hep.4-mapped" = "#C73E1D",
                                 "Other" = "grey70")) +
    coord_flip() +
    labs(title = "Hep.4 signature score across scRNA clusters",
         subtitle = sprintf("Top = %s", top_cluster),
         x = NULL, y = "Hep.4 signature score") +
    theme_pub(10) + theme(legend.position = "none")
  
  zone_long <- final_df %>%
    dplyr::select(Cluster, Zone1, Zone2, Zone3) %>%
    pivot_longer(-Cluster, names_to = "Zone", values_to = "Score")
  
  p_s5b <- ggplot(zone_long, aes(Cluster, Score, fill = Zone)) +
    geom_col(position = position_dodge(0.8), alpha = 0.9) +
    scale_fill_manual(values = c("Zone1" = "#2E86AB",
                                 "Zone2" = "#A23B72",
                                 "Zone3" = "#F18F01")) +
    labs(title = "Zone signature scores per cluster",
         x = "scRNA cluster", y = "Zone score") +
    theme_pub(10) + theme(legend.position = "top")
  
  safe_save(p_s5a / p_s5b + plot_annotation(tag_levels = "a") &
              theme(plot.tag = element_text(face = "bold", size = 11)),
            "FigureS5_Hep4_identity", 8, 8)
}

