  mle <- readRDS("results/GSE49541_validation_unified_zscored.rds")
  val <- readRDS("results/GSE49541_validation.rds")
  roc_f <- roc(as.integer(val$group), firth$pred_firth, quiet = TRUE)
  roc_m <- mle$roc
  df_f <- data.frame(FPR = 1 - roc_f$specificities,
                     TPR = roc_f$sensitivities, Method = "Firth")
  df_m <- data.frame(FPR = 1 - roc_m$specificities,
                     TPR = roc_m$sensitivities, Method = "MLE")
  p_s11 <- ggplot(rbind(df_f, df_m), aes(FPR, TPR, color = Method)) +
    geom_line(linewidth = 1.1) +
    geom_abline(intercept = 1, slope = 1, linetype = "dashed",
                color = "grey60") +
    scale_color_manual(values = c("Firth" = "#C73E1D", "MLE" = "#2E86AB")) +
    annotate("text", x = 0.62, y = 0.20, hjust = 0, size = 3.5,
             label = sprintf("Firth AUC = %.3f\nMLE AUC = %.3f",
                             firth$auc, mle$auc)) +
    labs(title = "Firth penalized-likelihood sensitivity analysis",
         subtitle = "GSE49541 external validation",
         x = "1 - Specificity", y = "Sensitivity", color = NULL) +
    coord_fixed(xlim = c(0, 1), ylim = c(0, 1)) +
    theme_pub(10) + theme(legend.position = "top")
