# ============================================================
# rebuild_L2_L3.R
# 从已有验证结果重建 L2 和 L3
# ============================================================
setwd("~/Desktop/sjfx3")
suppressPackageStartupMessages({
  library(tidyverse); library(metafor); library(pROC)
})

dir.create("results/revision", showWarnings = FALSE, recursive = TRUE)

# ============================================================
# L2: 跨队列异质性 meta 分析
# ============================================================
val  <- readRDS("results/GSE49541_validation_unified_zscored.rds")
gse130 <- readRDS("results/GSE130970_validation.rds")

auc1 <- as.numeric(val$auc)
ci1  <- as.numeric(val$ci)
auc2 <- as.numeric(gse130$auc)
ci2  <- as.numeric(gse130$ci)

# AUC 转 logit，计算 meta
logit_auc <- qlogis(c(auc1, auc2))
se_logit  <- c((ci1[3] - ci1[1]) / (2 * 1.96),
               (ci2[3] - ci2[1]) / (2 * 1.96)) /
  (c(auc1, auc2) * (1 - c(auc1, auc2)))

meta_res <- metafor::rma(yi = logit_auc, sei = se_logit, method = "REML")
pooled_auc <- plogis(meta_res$b)
pooled_ci  <- plogis(c(meta_res$ci.lb, meta_res$ci.ub))

cat(sprintf("L2: Pooled AUC = %.3f (%.3f-%.3f), I2 = %.1f%%\n",
            pooled_auc, pooled_ci[1], pooled_ci[2], meta_res$I2))

saveRDS(list(
  pooled_auc = pooled_auc,
  pooled_ci  = pooled_ci,
  I2         = meta_res$I2,
  meta_res   = meta_res
), "results/revision/L2_cross_cohort_heterogeneity.rds")
cat("OK results/revision/L2_cross_cohort_heterogeneity.rds\n")

# ============================================================
# L3: FIB-4 文献 benchmark 对比
# ============================================================
# FIB-4 在 MASH 队列中的 meta 分析（文献值）
lit_fib4 <- data.frame(
  Study = c("Sterling 2006", "Musso 2011", "Xiao 2017",
            "Mozes 2022", "Sanyal 2023"),
  AUC   = c(0.765, 0.849, 0.765, 0.787, 0.760),
  lo    = c(0.72, 0.83, 0.74, 0.73, 0.74),
  hi    = c(0.81, 0.87, 0.79, 0.84, 0.78)
)
se <- (lit_fib4$hi - lit_fib4$lo) / (2 * 1.96)
yi <- qlogis(lit_fib4$AUC)
sei <- se / (lit_fib4$AUC * (1 - lit_fib4$AUC))
meta_fib4 <- metafor::rma(yi = yi, sei = sei, method = "REML")

compare_tab <- data.frame(
  Score   = c("FIB-4 (literature)", "11-gene signature"),
  AUC     = c(round(plogis(meta_fib4$b), 3), round(auc1, 3)),
  CI_low  = c(round(plogis(meta_fib4$ci.lb), 3), round(ci1[1], 3)),
  CI_high = c(round(plogis(meta_fib4$ci.ub), 3), round(ci1[3], 3))
)
print(compare_tab)

saveRDS(list(
  compare_tab = compare_tab,
  meta_fib4   = meta_fib4
), "results/revision/L3_serum_score_comparison.rds")
cat("OK results/revision/L3_serum_score_comparison.rds\n")

