  l1 <- readRDS("results/revision/L1_EPV_analysis.rds")
  
  auc_boot <- as.numeric(l1$auc_boot)
  auc_boot <- auc_boot[is.finite(auc_boot)]
  auc_loo  <- as.numeric(l1$auc_loo)
  auc_loo  <- auc_loo[is.finite(auc_loo)]
  
  epv_val <- tryCatch(as.numeric(l1$EPV), error = function(e) NA_real_)
  riley_n <- tryCatch(as.numeric(l1$riley$n_total_min),
                      error = function(e) NA_real_)
  
  # ★ 关键修复：as.numeric() 去掉 quantile 的 names
  ci_boot <- as.numeric(quantile(auc_boot, c(0.025, 0.975), na.rm = TRUE))
  cat(sprintf("  Bootstrap 95%% CI: [%.3f, %.3f]\n", ci_boot[1], ci_boot[2]))
  cat(sprintf("  EPV = %.2f, Riley min n = %d\n", epv_val, riley_n))
  
  df_boot <- data.frame(AUC = auc_boot)
  
  p_s31a <- ggplot(df_boot, aes(AUC)) +
    geom_histogram(bins = 50, fill = "#C73E1D", alpha = 0.75,
                   color = "white") +
    geom_vline(xintercept = 0.784, color = "black", linewidth = 0.8) +
    geom_vline(xintercept = ci_boot,
               linetype = "dashed", color = "#2E86AB") +
    labs(title = "Bootstrap AUC (5,000x)",
         subtitle = sprintf("EPV = %.2f; Riley min n = %d",
                            epv_val, riley_n),
         x = "AUC", y = "Frequency") +
    theme_pub(9)
  
  loo_df <- data.frame(x = seq_along(auc_loo), y = as.numeric(auc_loo))
  
  p_s31b <- ggplot(loo_df, aes(x, y)) +
    geom_line(color = "#F18F01", linewidth = 1) +
    geom_point(size = 1.5, color = "#F18F01") +
    labs(title = "Leave-one-out AUC sensitivity",
         subtitle = sprintf("Range: %.3f - %.3f",
                            min(auc_loo), max(auc_loo)),
         x = "Iteration", y = "AUC") +
    theme_pub(9)
  
  safe_save((p_s31a | p_s31b) +
              plot_annotation(tag_levels = "a") &
              theme(plot.tag = element_text(face = "bold", size = 11)),
            "FigureS31_EPV_analysis", 10, 4)
}

