## ============================================================
# A5_clinical_correction_FIXED.R
# 修复: 
#   (1) 不用 | 组合 regex
#   (2) pattern 里加 [^;:]* 匹配 key 和 : 之间的单位
# ============================================================
rm(list = ls()); gc()
setwd("~/Desktop/sjfx3")
suppressPackageStartupMessages({
  library(tidyverse); library(pROC); library(ggplot2)
  library(stringr); library(org.Hs.eg.db)
})

dir.create("results/revision", showWarnings = FALSE, recursive = TRUE)
dir.create("figures/Figure2", showWarnings = FALSE, recursive = TRUE)

sig11 <- c("EYA2", "FERMT1", "PYROXD2", "EPB41L4A", "CHI3L1",
           "CNKSR1", "ILDR1", "GSN", "TMPRSS3", "ESRRG", "SULF2")

# ============================================================
# 1. 加载 GSE89632
# ============================================================
d <- readRDS("data/public_cohorts/GSE89632.rds")
expr <- d$expr
pheno <- d$pheno
cat(sprintf("表达矩阵: %d probes x %d samples\n", nrow(expr), ncol(expr)))

# ============================================================
# 2. 合并 characteristics + 修复后的 parse_var
# ============================================================
ch_cols <- grep("^characteristics", colnames(pheno), value = TRUE)
combined <- apply(pheno[, ch_cols, drop = FALSE], 1, function(x) {
  x <- x[!is.na(x) & x != ""]
  paste(x, collapse = "; ")
})

# ★ 修复版：单个 key_pattern，不含 |；用 [^;:]* 匹配单位
parse_var <- function(text_vec, key_pattern) {
  text_vec <- as.character(text_vec)
  text_vec[is.na(text_vec)] <- ""
  pattern <- paste0("(?:^|;\\s*)", key_pattern,
                    "[^;:]*:\\s*([-0-9.,]+)")
  m <- str_match(text_vec, regex(pattern, ignore_case = TRUE))
  values <- m[, 2]
  values <- gsub(",", "", values)
  suppressWarnings(as.numeric(values))
}

# 逐个提取（不用 | 组合）
age      <- parse_var(combined, "age\\s*\\(y\\)")
ast      <- parse_var(combined, "aspartate transaminase")
alt      <- parse_var(combined, "alanine transaminase")
bmi      <- parse_var(combined, "body mass index")
fibrosis <- parse_var(combined, "fibrosis\\s*\\(stage\\)")

parse_sex <- function(text_vec) {
  result <- rep(NA_character_, length(text_vec))
  result[grepl("gender\\s*[:=]\\s*male", text_vec, ignore.case = TRUE)]   <- "male"
  result[grepl("gender\\s*[:=]\\s*female", text_vec, ignore.case = TRUE)] <- "female"
  result
}
sex <- parse_sex(combined)

parse_diag <- function(text_vec) {
  result <- rep(NA_character_, length(text_vec))
  result[grepl("diagnosis\\s*[:=]\\s*NASH", text_vec, ignore.case = TRUE)] <- "NASH"
  result[grepl("diagnosis\\s*[:=]\\s*SS", text_vec, ignore.case = TRUE)]   <- "SS"
  result
}
diagnosis <- parse_diag(combined)

# 检查可用率
cat("\n=== 临床变量提取 ===\n")
for (v in c("age", "ast", "alt", "bmi", "fibrosis", "sex", "diagnosis")) {
  vals <- get(v)
  cat(sprintf("  %-10s: %d / %d 可用\n",
              v, sum(!is.na(vals)), length(vals)))
}

cat("\nfibrosis 分布:\n"); print(table(fibrosis, useNA = "ifany"))
cat("\ndiagnosis 分布:\n"); print(table(diagnosis, useNA = "ifany"))

# ============================================================
# 3. 探针映射
# ============================================================
cat("\n=== 探针映射 ===\n")

probe_ids <- rownames(expr)
is_probe <- all(grepl("^ILMN_", head(probe_ids, 10)))

if (is_probe) {
  if (!requireNamespace("illuminaHumanv4.db", quietly = TRUE)) {
    BiocManager::install("illuminaHumanv4.db",
                         ask = FALSE, update = FALSE)
  }
  suppressPackageStartupMessages(library(illuminaHumanv4.db))
  
  gene_symbols <- AnnotationDbi::mapIds(
    illuminaHumanv4.db,
    keys = probe_ids,
    column = "SYMBOL",
    keytype = "PROBEID",
    multiVals = "first"
  )
  cat(sprintf("映射成功: %d / %d\n",
              sum(!is.na(gene_symbols)), length(gene_symbols)))
} else {
  gene_symbols <- probe_ids
}

expr_df <- as.data.frame(expr, check.names = FALSE)
expr_df$SYMBOL <- gene_symbols
expr_df <- expr_df[!is.na(expr_df$SYMBOL), ]

expr_gene <- expr_df %>%
  group_by(SYMBOL) %>%
  summarise(across(where(is.numeric), mean), .groups = "drop") %>%
  column_to_rownames("SYMBOL") %>%
  as.matrix()

cat(sprintf("基因级矩阵: %d genes x %d samples\n",
            nrow(expr_gene), ncol(expr_gene)))

sig11_in <- intersect(sig11, rownames(expr_gene))
cat(sprintf("11-gene 在矩阵中: %d / 11\n", length(sig11_in)))
cat("缺失:", paste(setdiff(sig11, rownames(expr_gene)), collapse = ", "), "\n")

# ============================================================
# 4. Signature score
# ============================================================
mat_z <- t(scale(t(expr_gene[sig11_in, , drop = FALSE])))
mat_z[is.na(mat_z)] <- 0
sig_score <- colMeans(mat_z)

# ============================================================
# 5. 分析数据集
# ============================================================
clin_df <- data.frame(
  sample = colnames(expr),
  age = age, ast = ast, alt = alt, bmi = bmi,
  fibrosis = fibrosis, sex = sex, diagnosis = diagnosis,
  stringsAsFactors = FALSE
)

df_analysis <- data.frame(
  sample = colnames(expr_gene),
  signature = sig_score[colnames(expr_gene)],
  stringsAsFactors = FALSE
) %>% left_join(clin_df, by = "sample")

df_analysis$fibrosis_binary <- ifelse(
  df_analysis$fibrosis >= 2, 1,
  ifelse(df_analysis$fibrosis <= 1, 0, NA)
)

needed_cols <- c("signature", "age", "sex", "bmi", "ast", "alt",
                 "fibrosis_binary")
df_complete <- df_analysis[complete.cases(df_analysis[, needed_cols]), ]

cat(sprintf("\n完整案例: %d samples\n", nrow(df_complete)))
cat(sprintf("  Low (F0-F1):  %d\n", sum(df_complete$fibrosis_binary == 0)))
cat(sprintf("  High (F2-F4): %d\n", sum(df_complete$fibrosis_binary == 1)))

if (nrow(df_complete) < 20 ||
    sum(df_complete$fibrosis_binary == 0) < 5 ||
    sum(df_complete$fibrosis_binary == 1) < 5) {
  stop("完整案例不足，无法多变量分析")
}

df_complete$age_z <- as.numeric(scale(df_complete$age))
df_complete$bmi_z <- as.numeric(scale(df_complete$bmi))
df_complete$ast_z <- as.numeric(scale(df_complete$ast))
df_complete$alt_z <- as.numeric(scale(df_complete$alt))
df_complete$sig_z <- as.numeric(scale(df_complete$signature))

# ============================================================
# 6. 三模型
# ============================================================
cat("\n=== 三模型对比 ===\n")

m1 <- glm(fibrosis_binary ~ age_z + sex + bmi_z + ast_z + alt_z,
          data = df_complete, family = binomial)
pred1 <- predict(m1, type = "response")

m2 <- glm(fibrosis_binary ~ sig_z,
          data = df_complete, family = binomial)
pred2 <- predict(m2, type = "response")

m3 <- glm(fibrosis_binary ~ sig_z + age_z + sex + bmi_z + ast_z + alt_z,
          data = df_complete, family = binomial)
pred3 <- predict(m3, type = "response")

roc1 <- pROC::roc(df_complete$fibrosis_binary, pred1, quiet = TRUE)
roc2 <- pROC::roc(df_complete$fibrosis_binary, pred2, quiet = TRUE)
roc3 <- pROC::roc(df_complete$fibrosis_binary, pred3, quiet = TRUE)

ci1 <- as.numeric(pROC::ci.auc(roc1))
ci2 <- as.numeric(pROC::ci.auc(roc2))
ci3 <- as.numeric(pROC::ci.auc(roc3))

cat(sprintf("Model 1 (clinical):  AUC = %.3f (95%% CI %.3f-%.3f)\n",
            as.numeric(pROC::auc(roc1)), ci1[1], ci1[3]))
cat(sprintf("Model 2 (signature): AUC = %.3f (95%% CI %.3f-%.3f)\n",
            as.numeric(pROC::auc(roc2)), ci2[1], ci2[3]))
cat(sprintf("Model 3 (combined):  AUC = %.3f (95%% CI %.3f-%.3f)\n",
            as.numeric(pROC::auc(roc3)), ci3[1], ci3[3]))

dl_3v1 <- pROC::roc.test(roc3, roc1, method = "delong")
cat(sprintf("\nDeLong (combined vs clinical): P = %.4f\n", dl_3v1$p.value))

lrt <- anova(m1, m3, test = "LRT")
cat(sprintf("\nLRT (Model 3 vs Model 1): Chisq = %.3f, P = %.4e\n",
            lrt$Deviance[2], lrt$`Pr(>Chi)`[2]))

# NRI / IDI
nri_cont <- function(pred_old, pred_new, y) {
  up   <- pred_new > pred_old; down <- pred_new < pred_old
  event <- y == 1; nonevent <- y == 0
  (mean(up[event]) - mean(down[event])) +
    (mean(down[nonevent]) - mean(up[nonevent]))
}
nri_val <- nri_cont(pred1, pred3, df_complete$fibrosis_binary)
idi_val <- (mean(pred3[df_complete$fibrosis_binary == 1]) -
              mean(pred3[df_complete$fibrosis_binary == 0])) -
  (mean(pred1[df_complete$fibrosis_binary == 1]) -
     mean(pred1[df_complete$fibrosis_binary == 0]))
cat(sprintf("NRI = %.3f, IDI = %.3f\n", nri_val, idi_val))

