# A4b_selectivity_rerun.R
# 目的: 正确框架下的选择性分析
# 对比: 每个 HGF+ HSC 到 Hep.4 的距离 vs 到其他细胞类型的距离
# 输出: results/revision/A4b_selectivity_rerun.rds
#       results/revision/A4b_selectivity_rerun.csv
#       figures/Figure2/FigureS31b_selectivity.pdf/png
# ============================================================
rm(list = ls()); gc()
setwd("~/Desktop/sjfx3")
suppressPackageStartupMessages({
  library(Seurat); library(tidyverse); library(ggplot2)
})

dir.create("results/revision", showWarnings = FALSE, recursive = TRUE)
dir.create("figures/Figure2", showWarnings = FALSE, recursive = TRUE)

# ---------- 1. 加载 CosMx Slide1 ----------
cat("Loading CosMx Slide1...\n")
cosmx1 <- readRDS("data/GSM8855042_Slide1_SeuratObject.RDS")
celltype_col <- "RNA_nbclust_8b0a3ae1.8754.4ba9.8269.45e2cf2e855a_1_clusters"
ct     <- cosmx1@meta.data[[celltype_col]]
coords <- cosmx1@meta.data[, c("x_slide_mm","y_slide_mm","fov")]
expr   <- cosmx1[["RNA"]]$data

# ---------- 2. HGF+ HSC 与所有其他细胞类型 ----------
hsc_idx  <- which(ct == "Stellate.cells")
hgf_expr <- as.numeric(expr["HGF", ])
hgf_pos  <- hsc_idx[hgf_expr[hsc_idx] > 0]
cat(sprintf("HGF+ HSC: %d\n", length(hgf_pos)))

all_types <- sort(unique(ct))
all_types <- setdiff(all_types, "Stellate.cells")
cat(sprintf("其他细胞类型: %d\n", length(all_types)))

# ---------- 3. 距离函数（每个 HGF+ HSC 到某类型最近细胞的距离） ----------
compute_nn_to_type <- function(hsc_idx, target_idx, coords) {
  out <- rep(NA_real_, length(hsc_idx))
  for (f in unique(coords$fov)) {
    s <- hsc_idx[coords$fov[hsc_idx] == f]
    t <- target_idx[coords$fov[target_idx] == f]
    if (length(s) == 0 || length(t) == 0) next
    sc <- coords[s, ]
    tc <- coords[t, ]
    for (i in seq_along(s)) {
      d <- sqrt((tc$x_slide_mm - sc$x_slide_mm[i])^2 +
                  (tc$y_slide_mm - sc$y_slide_mm[i])^2)
      out[which(hsc_idx == s[i])] <- min(d) * 1000  # µm
    }
  }
  out
}

# ---------- 4. 对每种类型计算距离 ----------
cat("\n计算距离矩阵（每列 = 一个细胞类型）...\n")
dist_mat <- matrix(NA, nrow = length(hgf_pos), ncol = length(all_types))
colnames(dist_mat) <- all_types

for (j in seq_along(all_types)) {
  tgt_idx <- which(ct == all_types[j])
  if (length(tgt_idx) < 20) {
    cat(sprintf("  [跳过] %-30s N=%d\n", all_types[j], length(tgt_idx)))
    next
  }
  dist_mat[, j] <- compute_nn_to_type(hgf_pos, tgt_idx, coords)
  cat(sprintf("  %-30s N=%5d, median=%.1f µm\n",
              all_types[j], length(tgt_idx),
              median(dist_mat[, j], na.rm = TRUE)))
}

# ---------- 5. 配对 Wilcoxon：d_Hep4 vs d_X ----------
if (!("Hep.4" %in% colnames(dist_mat))) stop("Hep.4 不在类型列表中")

d_hep4 <- dist_mat[, "Hep.4"]
res_tab <- data.frame()

for (X in colnames(dist_mat)) {
  if (X == "Hep.4") next
  d_X <- dist_mat[, X]
  valid <- !is.na(d_hep4) & !is.na(d_X)
  if (sum(valid) < 30) next
  w <- wilcox.test(d_hep4[valid], d_X[valid],
                   paired = TRUE, alternative = "less")
  delta <- median(d_X[valid]) - median(d_hep4[valid])
  res_tab <- rbind(res_tab, data.frame(
    CellType   = X,
    N_target   = sum(ct == X),
    Median_Hep4 = round(median(d_hep4[valid]), 2),
    Median_X    = round(median(d_X[valid]), 2),
    Delta_um    = round(delta, 2),
    P_paired    = w$p.value
  ))
}

res_tab$FDR_BH <- p.adjust(res_tab$P_paired, method = "BH")
res_tab <- res_tab[order(-res_tab$Delta_um), ]

cat("\n========================================\n")
cat("选择性分析结果（Hep.4 vs 其他细胞类型）\n")
cat("========================================\n")
cat("Delta_um > 0 = Hep.4 更近（HGF+ HSC 到 Hep.4 更近）\n\n")
print(res_tab)

# ---------- 6. 保存 ----------
write.csv(res_tab,
          "results/revision/A4b_selectivity_rerun.csv",
          row.names = FALSE)

saveRDS(list(res_tab = res_tab, dist_mat = dist_mat),
        "results/revision/A4b_selectivity_rerun.rds")

# ---------- 7. 可视化 ----------
plot_df <- res_tab
plot_df$Significant <- ifelse(plot_df$FDR_BH < 0.05,
                              "FDR < 0.05", "n.s.")
plot_df$CellType <- factor(plot_df$CellType,
                           levels = plot_df$CellType[order(plot_df$Delta_um)])

p <- ggplot(plot_df, aes(Delta_um, CellType, fill = Significant)) +
  geom_col(alpha = 0.9, width = 0.7) +
  geom_vline(xintercept = 0, linetype = "dashed", color = "grey40") +
  scale_fill_manual(values = c("FDR < 0.05" = "#C73E1D",
                               "n.s." = "grey70")) +
  labs(title = "Selectivity of HGF+ HSC for Hep.4",
       subtitle = sprintf("Δ median distance (d_X − d_Hep.4) per HGF+ HSC; paired Wilcoxon; BH-corrected across %d types",
                          nrow(res_tab)),
       x = "Δ median distance (µm) — positive = Hep.4 closer",
       y = NULL, fill = NULL) +
  theme_classic(base_size = 10) +
  theme(legend.position = "top",
        plot.title = element_text(face = "bold"),
        plot.subtitle = element_text(size = 9, color = "grey30"),
        axis.text.y = element_text(size = 8))

ggsave("figures/Figure2/FigureS31b_selectivity.pdf", p,
       width = 8, height = 6)
ggsave("figures/Figure2/FigureS31b_selectivity.png", p,
       width = 8, height = 6, dpi = 300)
print(p)

# ---------- 8. 汇总 ----------
cat("\n========================================\n")
cat("汇总\n")
cat("========================================\n")
cat(sprintf("测试的细胞类型: %d\n", nrow(res_tab)))
cat(sprintf("Hep.4 更近 (Delta > 0): %d / %d\n",
            sum(res_tab$Delta_um > 0), nrow(res_tab)))
cat(sprintf("显著更近 (FDR < 0.05): %d / %d\n",
            sum(res_tab$Delta_um > 0 & res_tab$FDR_BH < 0.05),
            nrow(res_tab)))
cat(sprintf("HGF+ HSC 更远 (Delta < 0): %d / %d\n",
            sum(res_tab$Delta_um < 0), nrow(res_tab)))

cat("\n按 FDR 排序 Top 10:\n")
print(head(res_tab[order(res_tab$FDR_BH),
                   c("CellType","Delta_um","P_paired","FDR_BH")], 10))

