# 记录每个表格的状态
log_tab <- data.frame(Table = character(), Status = character(),
                      N_rows = integer(), N_cols = integer(),
                      stringsAsFactors = FALSE)

safe_write <- function(df, name, notes = "") {
  path <- file.path(OUT, paste0(name, ".csv"))
  tryCatch({
    write.csv(df, path, row.names = FALSE)
    log_tab <<- rbind(log_tab, data.frame(
      Table = name,
      Status = ifelse(notes == "", "OK", paste0("OK (", notes, ")")),
      N_rows = nrow(df), N_cols = ncol(df)
    ))
    cat(sprintf("  [OK]   %s (%d rows)\n", name, nrow(df)))
  }, error = function(e) {
    log_tab <<- rbind(log_tab, data.frame(
      Table = name, Status = paste0("FAIL: ", conditionMessage(e)),
      N_rows = NA_integer_, N_cols = NA_integer_))
    cat(sprintf("  [FAIL] %s: %s\n", name, conditionMessage(e)))
  })
}

try_load <- function(path) {
  tryCatch(readRDS(path), error = function(e) {
    cat(sprintf("  [MISS] %s\n", path)); NULL
  })
}

