# ============================================================
# P1_CellChat_spatial_communication.R
# 目的: HGF+ HSC → IL6R+ Hep.4 空间配体-受体通讯推断
# 输入: CosMx Slide1 + Slide2 Seurat 对象
# 输出: results/CellChat_spatial/ 下的 rds + 图
# ============================================================
rm(list = ls()); gc()
setwd("~/Desktop/sjfx3")

# ---------- 0. 依赖 ----------
required <- c("CellChat", "Seurat", "tidyverse", "patchwork", "NMF", "ggalluvial")
for (p in required) {
  if (!requireNamespace(p, quietly = TRUE)) {
    if (p == "CellChat") {
      if (!requireNamespace("devtools", quietly = TRUE))
        install.packages("devtools")
      devtools::install_github("jinworks/CellChat", upgrade = "never")
      devtools::install_github("immunogenomics/presto", upgrade = "never")
    } else {
      install.packages(p, repos = "https://cloud.r-project.org")
    }
  }
}
suppressPackageStartupMessages({
  library(CellChat); library(Seurat); library(tidyverse)
  library(patchwork); library(NMF); library(ggalluvial)
})

dir.create("results/CellChat_spatial", showWarnings = FALSE, recursive = TRUE)
dir.create("figures/Figure2", showWarnings = FALSE, recursive = TRUE)

# ============================================================
# 1. 加载 CosMx 数据并准备 CellChat 输入
# ============================================================
cat("=== Loading CosMx data ===\n")
cosmx1 <- readRDS("data/GSM8855042_Slide1_SeuratObject.RDS")
cosmx2 <- readRDS("data/GSM8855043_Slide2_SeuratObject.RDS")

# 细胞类型列名
col1 <- "RNA_nbclust_8b0a3ae1.8754.4ba9.8269.45e2cf2e855a_1_clusters"
col2 <- "RNA_nbclust_ee1320c5.9f48.455c.b54e.1fbfd34347ab_1_clusters"

# ---------- 1.1 细化细胞类型（拆分 HSC 为 HGF+ / HGF-） ----------
prepare_cellchat_input <- function(obj, celltype_col, slide_label) {
  ct   <- as.character(obj@meta.data[[celltype_col]])
  expr <- obj[["RNA"]]$data
  hgf_expr <- as.numeric(expr["HGF", ])
  
  # 拆分 Stellate
  ct_refined <- ct
  ct_refined[ct == "Stellate.cells" & hgf_expr > 0]  <- "Stellate_HGFpos"
  ct_refined[ct == "Stellate.cells" & hgf_expr == 0] <- "Stellate_HGFneg"
  
  # 细化 Hep.4（按 IL6R 表达拆分）
  il6r_expr <- as.numeric(expr["IL6R", ])
  ct_refined[ct == "Hep.4" & il6r_expr > 0] <- "Hep.4_IL6Rpos"
  ct_refined[ct == "Hep.4" & il6r_expr == 0] <- "Hep.4_IL6Rneg"
  
  # 保留核心类型
  keep_types <- c("Stellate_HGFpos", "Stellate_HGFneg",
                  "Hep.4_IL6Rpos", "Hep.4_IL6Rneg",
                  "Hep.1", "Hep.5",
                  "Cholangiocytes",
                  "Inflammatory.macrophages",
                  "Non.inflammatory.macrophages",
                  "Endothelial", "Periportal.LSECs",
                  "Central.venous.LSECs")
  keep_types <- keep_types[keep_types %in% unique(ct_refined)]
  
  keep_cells <- which(ct_refined %in% keep_types)
  obj_sub <- subset(obj, cells = colnames(obj)[keep_cells])
  obj_sub$celltype_refined <- ct_refined[keep_cells]
  obj_sub$slide <- slide_label
  
  cat(sprintf("%s: %d cells, %d cell types\n",
              slide_label, ncol(obj_sub),
              length(unique(obj_sub$celltype_refined))))
  return(obj_sub)
}

obj1 <- prepare_cellchat_input(cosmx1, col1, "Slide1")
obj2 <- prepare_cellchat_input(cosmx2, col2, "Slide2")
rm(cosmx1, cosmx2); gc()

# ---------- 1.2 合并双切片 ----------
obj_all <- merge(obj1, obj2)
rm(obj1, obj2); gc()

# 确保标准化
DefaultAssay(obj_all) <- "RNA"
if (max(obj_all[["RNA"]]$data) > 50) {
  obj_all <- NormalizeData(obj_all, verbose = FALSE)
}

cat(sprintf("Merged: %d cells, %d cell types\n",
            ncol(obj_all), length(unique(obj_all$celltype_refined))))

## ============================================================
# 2. 准备空间坐标（CosMx: pixels → micrometers）
# ============================================================
# CosMx 官方转换因子：1 pixel = 0.18 μm
# 数据来源：CellChat v2 官方教程 CosMx 示例
# https://github.com/jinworks/CellChat/blob/master/tutorial/CellChat_spatial.Rmd
conversion_factor <- 0.18

# 坐标从 mm 转 μm，再转 pixel
# 因为 CellChat 内部按 pixel 单位计算，最终除以 conversion_factor 回 μm
spatial_locs <- data.frame(
  x = obj_all@meta.data$x_slide_mm * 1000 / conversion_factor,
  y = obj_all@meta.data$y_slide_mm * 1000 / conversion_factor
)
rownames(spatial_locs) <- colnames(obj_all)

cat(sprintf("Cells: %d, x range: %.1f-%.1f, y range: %.1f-%.1f\n",
            nrow(spatial_locs),
            min(spatial_locs$x), max(spatial_locs$x),
            min(spatial_locs$y), max(spatial_locs$y)))

# ★ 关键修复：用 RANN 精确计算最近邻距离（不构建全矩阵）
if (!requireNamespace("RANN", quietly = TRUE)) {
  install.packages("RANN", repos = "https://cloud.r-project.org")
}
suppressPackageStartupMessages(library(RANN))

cat("Computing nearest-neighbour distances (KD-tree)...\n")
# k = 2 因为每个细胞到自身的距离是 0，第 2 列才是真正最近邻
nn_result <- RANN::nn2(spatial_locs, spatial_locs, k = 2)

# 每个细胞到最近邻的距离（pixel 单位）
nn_dists_px <- nn_result$nn.dists[, 2]

min_dist_px    <- min(nn_dists_px)
median_dist_px <- median(nn_dists_px)

# 转回 μm
min_dist_um    <- min_dist_px * conversion_factor
median_dist_um <- median_dist_px * conversion_factor

cat(sprintf("Min NN distance:    %.2f px = %.2f μm\n",
            min_dist_px, min_dist_um))
cat(sprintf("Median NN distance: %.2f px = %.2f μm\n",
            median_dist_px, median_dist_um))

# spot.size 用 min NN distance / 2（CellChat 官方推荐）
spatial_factors <- data.frame(
  ratio = conversion_factor,
  tol   = min_dist_px / 2
)

cat(sprintf("spatial.factors: ratio = %.3f, tol = %.3f\n",
            spatial_factors$ratio, spatial_factors$tol))
# ============================================================
# 3. 创建 CellChat 对象（空间模式）
# ============================================================
cat("\n=== Creating CellChat object (spatial mode) ===\n")

data_input <- GetAssayData(obj_all, assay = "RNA", layer = "data")

meta <- data.frame(
  labels  = obj_all$celltype_refined,
  samples = obj_all$slide,
  row.names = colnames(obj_all)
)

cellchat <- createCellChat(
  object      = data_input,
  meta        = meta,
  group.by    = "labels",
  datatype    = "spatial",
  coordinates = spatial_locs,
  spatial.factors = spatial_factors
)

# 设置人类配体-受体数据库
cellchat@DB <- CellChatDB.human
cat(sprintf("LR pairs in database: %d\n",
            nrow(CellChatDB.human$interaction)))

# ============================================================
# 4. 预处理
# ============================================================
cellchat <- subsetData(cellchat)
cellchat <- identifyOverExpressedGenes(cellchat)
cellchat <- identifyOverExpressedInteractions(cellchat)
cat("Preprocessing done.\n")

# ============================================================
# 5. 计算空间通讯概率（核心步骤）
# ============================================================
cat("\n=== Computing spatial communication probability ===\n")

# 关键参数说明：
#   distance.use = TRUE      : 启用空间距离约束
#   interaction.range = 250  : 最大扩散距离（默认 250 μm）
#   scale.distance = 0.01    : 距离衰减因子，使最小缩放距离在 [1,2] 范围内
#   type = "triMean"         : 截断均值法
#   trim = 0.1               : 截断比例

future::plan("multisession", workers = 2)

cellchat <- computeCommunProb(
  cellchat,
  type            = "triMean",
  trim            = 0.1,
  distance.use    = TRUE,
  interaction.range = 250,
  scale.distance  = 3.0,
  contact.dependent = TRUE,
  contact.range   = 10,       # 接触依赖信号范围（约一个细胞直径）
  nboot           = 100       # 置换检验次数
)

# 过滤：保留至少 10 个细胞的通讯
cellchat <- filterCommunication(cellchat, min.cells = 10)
cat("Communication computed and filtered.\n")

# ============================================================
# 6. 提取结果
# ============================================================
# 6.1 所有显著 LR 对
lr_df <- subsetCommunication(cellchat)
cat(sprintf("\nTotal significant LR pairs: %d\n", nrow(lr_df)))

# 6.2 HGF+ HSC 作为 sender 的通讯
hgfpos_lr <- lr_df[lr_df$source == "Stellate_HGFpos", ]
cat(sprintf("Stellate_HGFpos as sender: %d\n", nrow(hgfpos_lr)))

# 6.3 HGF+ HSC → IL6R+ Hep.4 的通讯（核心）
hgf_to_hep4 <- hgfpos_lr[hgfpos_lr$target == "Hep.4_IL6Rpos", ]
cat(sprintf("Stellate_HGFpos → Hep.4_IL6Rpos: %d\n", nrow(hgf_to_hep4)))

# 6.4 重点关注通路
key_pathways <- c("HGF", "IL6", "LIF", "OSM", "IL11", "SPP1", "TGFb")
key_lr <- hgf_to_hep4[hgf_to_hep4$pathway_name %in% key_pathways, ]

cat("\n=== Key LR pairs (HGF+ HSC → IL6R+ Hep.4) ===\n")
if (nrow(key_lr) > 0) {
  print(key_lr[, c("ligand", "receptor", "pathway_name", "prob", "pval")])
} else {
  cat("No key pathway LR pairs found in this direction.\n")
  cat("Showing all LR pairs:\n")
  print(hgf_to_hep4[, c("ligand", "receptor", "pathway_name", "prob", "pval")])
}

# 6.5 对比：HGF- HSC → IL6R+ Hep.4
hgfneg_lr <- lr_df[lr_df$source == "Stellate_HGFneg" &
                     lr_df$target == "Hep.4_IL6Rpos", ]
cat(sprintf("\nStellate_HGFneg → Hep.4_IL6Rpos: %d\n", nrow(hgfneg_lr)))

# ============================================================
# 7. 通讯概率的置换检验对比
# ============================================================
# 计算 HGF+ vs HGF- HSC 对 Hep.4_IL6Rpos 的通讯强度
all_hsc_to_hep4 <- lr_df[lr_df$source %in% c("Stellate_HGFpos", "Stellate_HGFneg") &
                           lr_df$target == "Hep.4_IL6Rpos", ]

if (nrow(all_hsc_to_hep4) > 0) {
  comparison <- all_hsc_to_hep4 %>%
    group_by(source, pathway_name) %>%
    summarise(
      n_lr = n(),
      total_prob = sum(prob, na.rm = TRUE),
      .groups = "drop"
    ) %>%
    pivot_wider(names_from = source, values_from = c(n_lr, total_prob),
                values_fill = 0)
  
  cat("\n=== Pathway-level comparison: HGF+ vs HGF- HSC → IL6R+ Hep.4 ===\n")
  print(comparison)
}

# ============================================================
# 8. 聚合到通路水平
# ============================================================
cellchat <- computeCommunProbPathway(cellchat)
cellchat <- aggregateNet(cellchat)

# ============================================================
# 9. 可视化
# ============================================================
cat("\n=== Generating visualizations ===\n")

group_size <- as.numeric(table(cellchat@idents))

# ---------- 9.1 圆图：全部通讯网络 ----------
pdf("figures/Figure2/FigureS20_CellChat_circle.pdf", width = 10, height = 10)
par(mfrow = c(1, 1), xpd = TRUE)
netVisual_circle(cellchat@net$count,
                 vertex.weight = group_size,
                 weight.scale = TRUE,
                 label.edge = FALSE,
                 title.name = "Spatial cell-cell communication network")
dev.off()

# ---------- 9.2 圆图：HGF+ HSC 作为 sender ----------
pdf("figures/Figure2/FigureS21_CellChat_HGFpos_sender.pdf", width = 8, height = 8)
par(mfrow = c(1, 1), xpd = TRUE)
