# ---------- 通用函数 ----------
compute_nn <- function(src_idx, tgt_idx, coords) {
  out <- rep(NA_real_, length(src_idx))
  for (f in unique(coords$fov)) {
    s <- src_idx[coords$fov[src_idx] == f]
    t <- tgt_idx[coords$fov[tgt_idx] == f]
    if (length(s) == 0 || length(t) == 0) next
    sc <- coords[s, ]; tc <- coords[t, ]
    for (i in seq_along(s)) {
      d <- sqrt((tc$x_slide_mm - sc$x_slide_mm[i])^2 +
                  (tc$y_slide_mm - sc$y_slide_mm[i])^2)
      out[which(src_idx == s[i])] <- min(d) * 1000
    }
  }
  out
}

analyze_slide <- function(obj, celltype_col, slide_label) {
  ct     <- obj@meta.data[[celltype_col]]
  expr   <- obj[["RNA"]]$data
  coords <- obj@meta.data[, c("x_slide_mm","y_slide_mm","fov")]
  
  hsc_idx  <- which(ct == "Stellate.cells")
  hgf_expr <- as.numeric(expr["HGF", ])
  hgf_pos  <- hsc_idx[hgf_expr[hsc_idx] > 0]
  
  hep4_idx  <- which(ct == "Hep.4")
  met_expr  <- as.numeric(expr["MET", ])
  met_pos   <- hep4_idx[met_expr[hep4_idx] > 0]
  met_neg   <- hep4_idx[met_expr[hep4_idx] == 0]
  
  cat(sprintf("[%s] HGF+ HSC: %d | Hep.4: %d (MET+ %d, MET- %d)\n",
              slide_label, length(hgf_pos),
              length(hep4_idx), length(met_pos), length(met_neg)))
  
  d_pos <- compute_nn(met_pos, hgf_pos, coords)
  d_neg <- compute_nn(met_neg, hgf_pos, coords)
  
  w <- wilcox.test(d_pos, d_neg)
  cd <- (mean(d_pos, na.rm=TRUE) - mean(d_neg, na.rm=TRUE)) /
    sqrt((var(d_pos, na.rm=TRUE) + var(d_neg, na.rm=TRUE))/2)
  
  data.frame(
    Slide    = slide_label,
    N_METpos = length(d_pos),
    N_METneg = length(d_neg),
    Median_METpos = median(d_pos, na.rm = TRUE),
    Median_METneg = median(d_neg, na.rm = TRUE),
    Delta    = median(d_pos, na.rm = TRUE) - median(d_neg, na.rm = TRUE),
    Cohen_d  = round(cd, 3),
    P_wilcox = w$p.value
  ) -> stat_row
  
  list(d_pos = d_pos, d_neg = d_neg, stat = stat_row)
}

res1 <- analyze_slide(cosmx1, col1, "Slide1")
res2 <- analyze_slide(cosmx2, col2, "Slide2")
