                      "RNA_nbclust_8b0a3ae1.8754.4ba9.8269.45e2cf2e855a_1_clusters")
cosmx2 <- add_patient(cosmx2,
                      "RNA_nbclust_ee1320c5.9f48.455c.b54e.1fbfd34347ab_1_clusters")

extract_core <- function(obj, celltype_col, slide) {
  ct   <- obj@meta.data[[celltype_col]]
  expr <- obj[["RNA"]]$data
  df   <- obj@meta.data[, c("x_slide_mm","y_slide_mm","fov","patient")]
  df$celltype <- ct
  df$HGF      <- as.numeric(expr["HGF", ])
  df$slide    <- slide
  df
}
df_all <- rbind(
  extract_core(cosmx1,
               "RNA_nbclust_8b0a3ae1.8754.4ba9.8269.45e2cf2e855a_1_clusters", "S1"),
  extract_core(cosmx2,
               "RNA_nbclust_ee1320c5.9f48.455c.b54e.1fbfd34347ab_1_clusters", "S2")
)
df_all$patient_uid <- paste(df_all$slide, df_all$patient, sep = "_")
rm(cosmx1, cosmx2); gc()

stellate <- df_all[df_all$celltype == "Stellate.cells", ]
hep4     <- df_all[df_all$celltype == "Hep.4", ]

compute_nn <- function(src, tgt) {
  out <- rep(NA_real_, nrow(src))
  for (f in unique(src$fov)) {
    s <- which(src$fov == f); t <- which(tgt$fov == f)
    if (length(t) == 0) next
    sc <- src[s, ]; tc <- tgt[t, ]
    d <- sapply(seq_len(nrow(sc)), function(i)
      sqrt((tc$x_slide_mm - sc$x_slide_mm[i])^2 +
             (tc$y_slide_mm - sc$y_slide_mm[i])^2))
    out[s] <- apply(d, 2, min) * 1000
  }
  out
}
stellate$dist_to_Hep4 <- compute_nn(stellate, hep4)
stellate$HGF_pos <- as.numeric(stellate$HGF > 0)

# ---------- 3. 每患者 bootstrap 2000 次 ----------
set.seed(123)
n_boot <- 2000
boot_res <- data.frame()

for (p in unique(stellate$patient_uid)) {
  sub <- stellate[stellate$patient_uid == p, ]
  pos <- sub$dist_to_Hep4[sub$HGF_pos == 1]
  neg <- sub$dist_to_Hep4[sub$HGF_pos == 0]
  pos <- pos[!is.na(pos)]; neg <- neg[!is.na(neg)]
  if (length(pos) < 30 || length(neg) < 30) next
  
  deltas <- replicate(n_boot, {
    median(sample(pos, replace = TRUE)) - median(sample(neg, replace = TRUE))
  })
  ci <- as.numeric(quantile(deltas, c(0.025, 0.975), na.rm = TRUE))
  
  boot_res <- rbind(boot_res, data.frame(
    Patient    = p,
    N_HGFpos   = length(pos),
    N_HGFneg   = length(neg),
    Delta      = median(pos) - median(neg),
    CI_low     = ci[1],
    CI_high    = ci[2]
  ))
}

cat("\n=== Per-patient bootstrap ===\n")
print(boot_res)
