                           levels = boot_res$Patient[order(boot_res$Delta)])

p_forest <- ggplot(boot_res, aes(Delta, Patient)) +
  geom_vline(xintercept = 0, linetype = "dashed", color = "grey40") +
  geom_errorbarh(aes(xmin = CI_low, xmax = CI_high),
                 height = 0.18, color = "#C73E1D", linewidth = 0.9) +
  geom_point(size = 4, color = "#C73E1D") +
  geom_text(aes(label = sprintf("%.1f \u00b5m (n=%d/%d)",
                                Delta, N_HGFpos, N_HGFneg)),
            hjust = 1.15, vjust = -1.2, size = 3, color = "grey20") +
  labs(title = "Cross-patient effect size (4 independent samples)",
       subtitle = sprintf("Bootstrap 95%% CI (2,000 resamples); mixed-model \u03b2 = %.3f (P = %s)",
                          mix_beta, mix_pstr),
       x = "\u0394 median distance (HGF+ \u2212 HGF\u2212) to nearest Hep.4, \u00b5m",
       y = NULL) +
  theme_pub(10) +
  coord_cartesian(xlim = c(-40, 5))

