# ---------- 亚组 AUC ----------
sub_auc <- function(idx_neg, idx_pos, label) {
  if (length(idx_neg) < 5 || length(idx_pos) < 5) return(NULL)
  idx <- c(idx_neg, idx_pos)
  y   <- c(rep(0, length(idx_neg)), rep(1, length(idx_pos)))
  r   <- roc(y, sig_score[idx], quiet = TRUE)
  ci  <- as.numeric(ci.auc(r))
  data.frame(
    Comparison = label,
    N = length(idx),
    Events = length(idx_pos),
    AUC = as.numeric(auc(r)),
    CI_low = ci[1], CI_high = ci[3]
  )
}

