prepare <- function(obj, celltype_col) {
  ct   <- as.character(obj@meta.data[[celltype_col]])
  expr <- obj[["RNA"]]$data
  hgf  <- as.numeric(expr["HGF", ])
  il6r <- as.numeric(expr["IL6R", ])
  ct_refined <- ct
  ct_refined[ct == "Stellate.cells" & hgf  > 0] <- "Stellate_HGFpos"
  ct_refined[ct == "Stellate.cells" & hgf == 0] <- "Stellate_HGFneg"
  ct_refined[ct == "Hep.4" & il6r  > 0]        <- "Hep.4_IL6Rpos"
  ct_refined[ct == "Hep.4" & il6r == 0]        <- "Hep.4_IL6Rneg"
  list(expr = expr, ct = ct_refined)
}

