compute_posrate <- function(genes) {
  mat <- sapply(genes, function(g) {
    x <- as.numeric(expr_all[g, ])
    tapply(x > 0, ct_all, mean)
  })
  mat <- mat[ct_order, , drop = FALSE]
  df <- as.data.frame(mat)
  df$CellType <- rownames(df)
  df_long <- reshape2::melt(df, id.vars = "CellType",
                            variable.name = "Gene", value.name = "PosRate")
  df_long
}

