theme_heat <- function(base = 10) {
  theme_minimal(base_size = base) +
    theme(panel.grid      = element_blank(),
          plot.title      = element_text(face = "bold", size = base + 1),
          plot.subtitle   = element_text(size = base - 1, color = "grey30"),
