cat("Stellate.cells 细胞数:", sum(cell_types == "Stellate.cells"), "\n")

## ---- 3. 距离梯度函数 ----
calc_enrichment_from_mask <- function(radius_um, meta, anchor_mask, cell_types,
                                      target_type = "Hep.4", n_perm = 1000) {
  anchor_idx <- which(anchor_mask)
  target_idx <- which(cell_types == target_type)
  
  if (length(anchor_idx) == 0 || length(target_idx) == 0) {
    return(data.frame(radius = radius_um, observed_mean = NA_real_,
                      expected_mean = NA_real_, enrichment = NA_real_,
                      p_value = NA_real_, anchor_n = 0L, target_n = 0L))
  }
  
  anchor_coords <- as.data.frame(meta[anchor_idx, c("x_um", "y_um")])
  target_coords <- as.data.frame(meta[target_idx, c("x_um", "y_um")])
  setDT(anchor_coords); setDT(target_coords)
  
  ## 观测：每个 anchor 细胞半径内的 target 数
  obs_counts <- numeric(nrow(anchor_coords))
  for (i in 1:nrow(anchor_coords)) {
    d2 <- (target_coords$x_um - anchor_coords$x_um[i])^2 +
      (target_coords$y_um - anchor_coords$y_um[i])^2
    obs_counts[i] <- sum(d2 <= radius_um^2)
  }
  obs_mean <- mean(obs_counts)
  
  ## 置换检验
  non_anchor_idx <- which(!anchor_mask)
  expected_counts <- numeric(n_perm)
  for (p in 1:n_perm) {
    fake_idx <- sample(non_anchor_idx, size = length(anchor_idx), replace = FALSE)
    fake_coords <- as.data.frame(meta[fake_idx, c("x_um", "y_um")])
    setDT(fake_coords)
    fake_counts <- numeric(nrow(fake_coords))
    for (j in 1:nrow(fake_coords)) {
      d2 <- (target_coords$x_um - fake_coords$x_um[j])^2 +
        (target_coords$y_um - fake_coords$y_um[j])^2
      fake_counts[j] <- sum(d2 <= radius_um^2)
    }
    expected_counts[p] <- mean(fake_counts)
  }
  
  enrichment_ratio <- obs_mean / mean(expected_counts)
  p_value <- (sum(expected_counts >= obs_mean) + 1) / (n_perm + 1)
  
  data.frame(
    radius = radius_um,
    observed_mean = round(obs_mean, 2),
    expected_mean = round(mean(expected_counts), 2),
    enrichment = round(enrichment_ratio, 3),
    p_value = round(p_value, 4),
    anchor_n = length(anchor_idx),
    target_n = length(target_idx)
  )
}

## ---- 4. 主分析：HGF+ cells → Hep.4 ----
radii <- c(25, 50, 75, 100, 150)
n_perm <- 1000
results <- list()

cat("\n=== HGF+ cells → Hep.4 ===\n")
