  cat("  半径", r, "um ... ")
  results[[as.character(r)]] <- calc_enrichment_from_mask(
    r, meta, hgf_pos, cell_types, n_perm = n_perm)
  cat("enrichment =", results[[as.character(r)]]$enrichment,
      "p =", results[[as.character(r)]]$p_value, "\n")
}

