# ---------- 3. 距离梯度函数 ----------
calc_gradient <- function(radius_um, meta, anchor_mask, target_mask,
                          n_perm = 1000, seed = 2024) {
  set.seed(seed)
  anchor_idx <- which(anchor_mask)
  target_idx <- which(target_mask)
  if (length(anchor_idx) == 0 || length(target_idx) == 0) return(NULL)
  
  ac <- as.data.frame(meta[anchor_idx, c("x_um","y_um")])
  tc <- as.data.frame(meta[target_idx, c("x_um","y_um")])
  setDT(ac); setDT(tc)
  
  # observed
  obs <- numeric(nrow(ac))
  for (i in seq_len(nrow(ac))) {
    d2 <- (tc$x_um - ac$x_um[i])^2 + (tc$y_um - ac$y_um[i])^2
    obs[i] <- sum(d2 <= radius_um^2)
  }
  obs_mean <- mean(obs)
  
  # permutation
  pool <- which(!anchor_mask)
  null <- numeric(n_perm)
  for (p in seq_len(n_perm)) {
    fake <- sample(pool, length(anchor_idx), replace = FALSE)
    fc <- as.data.frame(meta[fake, c("x_um","y_um")])
    setDT(fc)
    cnt <- numeric(nrow(fc))
    for (j in seq_len(nrow(fc))) {
      d2 <- (tc$x_um - fc$x_um[j])^2 + (tc$y_um - fc$y_um[j])^2
      cnt[j] <- sum(d2 <= radius_um^2)
    }
    null[p] <- mean(cnt)
  }
  
  data.frame(
    radius        = radius_um,
    observed_mean = round(obs_mean, 3),
    expected_mean = round(mean(null), 3),
    enrichment    = round(obs_mean / mean(null), 3),
    p_value       = (sum(null >= obs_mean) + 1) / (n_perm + 1),
    anchor_n      = length(anchor_idx),
    target_n      = length(target_idx)
  )
}

# ---------- 4. 跑五个半径 ----------
radii <- c(25, 50, 75, 100, 150)
n_perm <- 1000

cat("\n=== HGF+ Stellate -> Hep.4 ===\n")
main_res <- lapply(radii, function(r) {
  cat(sprintf("  radius %d um ... ", r))
  out <- calc_gradient(r, meta, anchor_main, target_mask, n_perm)
  cat(sprintf("enrichment = %.3f, p = %.4f\n", out$enrichment, out$p_value))
  out
})
main_df <- do.call(rbind, main_res)
main_df$group <- "HGF+ Stellate"

cat("\n=== HGF- Stellate -> Hep.4 (control) ===\n")
ctrl_res <- lapply(radii, function(r) {
  cat(sprintf("  radius %d um ... ", r))
  out <- calc_gradient(r, meta, anchor_ctrl, target_mask, n_perm)
  cat(sprintf("enrichment = %.3f, p = %.4f\n", out$enrichment, out$p_value))
  out
})
ctrl_df <- do.call(rbind, ctrl_res)
ctrl_df$group <- "HGF- Stellate"

combined_df <- rbind(main_df, ctrl_df)
print(main_df)
print(ctrl_df)

